#!/usr/bin/env node
"use strict";
// Cyrus Test Flight (R0): boot ONE disposable real Paper server for one Minecraft version, run the checks, tear it
// down, and print a JSON report. Runs on the build host (node-2) as root, under TF_ROOT only.
//
//   node runner.js run <resolved-spec.json>      -> report JSON on stdout (exit 0), busy (75), bad spec (2)
//   node runner.js setup <javaRelease>           -> fetch + verify one pinned JDK (21 or 25), print its path
//
// Safety model (node-2 is a shared build host):
// - one Test Flight at a time: `flock -n` on TF_ROOT/testflight.lock (a second run gets status "busy" at once);
// - the server runs inside a private network namespace (loopback only: no internet, no host ports) as uid/gid 65534
//   with no_new_privs, nice 10, -Xmx<=1g, 2 visible CPUs, an RSS watchdog and a hard wall-clock timeout;
// - processes are only ever killed by exact PID (the java PID we spawned, or a PID whose cmdline carries this run's
//   unique -Dnxeon.testflight.run marker). Never by pattern;
// - the run dir is removed afterwards; downloads (JDKs, Paper jars) are verified by sha256 before use.
// Every check is pass / fail / not_run with evidence. A check never passes unless it ran.

const fs = require("fs");
const path = require("path");
const net = require("net");
const os = require("os");
const crypto = require("crypto");
const { spawn, spawnSync } = require("child_process");
const L = require("./lib.js");

const RUNNER_VERSION = "tf-lite-3"; // 2: seeds, collect, RSS per RCON step; 3: ms per RCON step, world.generateStructures
const TF_ROOT = process.env.TF_ROOT || "/tank/nxeon-build/tmp/testflight";
const LOCK = path.join(TF_ROOT, "testflight.lock");
const RUN_UID = 65534;
const BUSY_EXIT = 75;

// Pinned toolchains (Adoptium API checksums, verified 2026-10-10). Bump deliberately, never float.
const JDKS = {
  21: { release: "jdk-21.0.12.1+1", sha256: "ce79869e1307ed8ee1e2baa86a412b1eb5b75d10a01006d788a6f968bcfaee94",
    url: "https://github.com/adoptium/temurin21-binaries/releases/download/jdk-21.0.12.1%2B1/OpenJDK21U-jdk_x64_linux_hotspot_21.0.12.1_1.tar.gz" },
  25: { release: "jdk-25.0.4.1+1", sha256: "dbb698396d478e7fa2b1e50f4103324b2a99b90569ee27c33f2261f9215cf41e",
    url: "https://github.com/adoptium/temurin25-binaries/releases/download/jdk-25.0.4.1%2B1/OpenJDK25U-jdk_x64_linux_hotspot_25.0.4.1_1.tar.gz" },
};

const log = (...a) => process.stderr.write(`[testflight] ${a.join(" ")}\n`);
const sha256File = (f) => crypto.createHash("sha256").update(fs.readFileSync(f)).digest("hex");
const now = () => Date.now();
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const clip = (s, n = 300) => String(s).slice(0, n);

function selfHash() {
  const h = crypto.createHash("sha256");
  for (const f of ["runner.js", "lib.js"]) h.update(fs.readFileSync(path.join(__dirname, f)));
  return h.digest("hex");
}

function emptyChecks(required) {
  return L.CHECK_IDS.map((id) => ({ id, status: "not_run", required: required[id], evidence: [], durationMs: 0 }));
}
function requiredFor(spec) {
  return {
    boot_done: true,
    plugins_enabled: (spec.plugins || []).length > 0,
    startup_log_clean: true,
    rcon_checks: (spec.rcon || []).length > 0 || (spec.datapacks || []).length > 0,
    clean_stop: true,
    no_leaks: true,
  };
}
function baseReport(spec, status) {
  return {
    schema: L.SCHEMA, runId: spec.runId || null, status, version: spec.version || null, javaRelease: spec.javaRelease || null,
    startedAt: new Date().toISOString(), finishedAt: null, checks: emptyChecks(requiredFor(spec || {})),
    timings: {}, bootMs: null, doneReportedSec: null, peakRssKb: null, artifacts: [], engine: null, notes: [], overall: "incomplete",
  };
}
function finish(rep) {
  rep.finishedAt = new Date().toISOString();
  rep.overall = rep.status === "completed" ? L.overallOf(rep.checks) : "incomplete";
  return rep;
}

// ------------------------------------------------------------------ toolchains (host network, lock held) ----
async function download(url, dest, expectSha) {
  const r = await fetch(url, { redirect: "follow" });
  if (!r.ok) throw new Error(`download ${url}: HTTP ${r.status}`);
  const tmp = dest + ".part";
  fs.writeFileSync(tmp, Buffer.from(await r.arrayBuffer()));
  const got = sha256File(tmp);
  if (got !== expectSha) { fs.rmSync(tmp, { force: true }); throw new Error(`sha256 mismatch for ${url}: got ${got}, want ${expectSha}`); }
  fs.renameSync(tmp, dest);
}

async function ensureJdk(release) {
  const pin = JDKS[release];
  if (!pin) throw new Error(`no pinned JDK for release ${release}`);
  const dir = path.join(TF_ROOT, "jdk", String(release));
  const ok = path.join(dir, ".nxeon-ok");
  if (fs.existsSync(ok) && fs.readFileSync(ok, "utf8").trim() === pin.sha256 && fs.existsSync(path.join(dir, "bin/java"))) {
    return { home: dir, ...pin, fetched: false };
  }
  const dl = path.join(TF_ROOT, "dl");
  fs.mkdirSync(dl, { recursive: true });
  const tgz = path.join(dl, `${pin.sha256}.tar.gz`);
  if (!fs.existsSync(tgz) || sha256File(tgz) !== pin.sha256) { log(`downloading ${pin.release}`); await download(pin.url, tgz, pin.sha256); }
  fs.mkdirSync(path.join(TF_ROOT, "jdk"), { recursive: true });
  const tmp = fs.mkdtempSync(path.join(TF_ROOT, "jdk", `.x-${release}-`));
  const x = spawnSync("tar", ["-xzf", tgz, "-C", tmp], { stdio: "inherit" });
  if (x.status !== 0) throw new Error("tar failed");
  const inner = path.join(tmp, pin.release);
  if (!fs.existsSync(path.join(inner, "bin/java"))) throw new Error(`unexpected JDK layout in ${tgz}`);
  fs.rmSync(dir, { recursive: true, force: true });
  fs.renameSync(inner, dir);
  fs.rmSync(tmp, { recursive: true, force: true });
  fs.writeFileSync(ok, pin.sha256 + "\n");
  return { home: dir, ...pin, fetched: true };
}

function jdkVersion(home) {
  try { return /JAVA_VERSION="([^"]+)"/.exec(fs.readFileSync(path.join(home, "release"), "utf8"))[1]; } catch { return null; }
}

/** Paper server jar cached by sha256 and pre-patched (paperclip patch-only) so runs need no network. */
async function ensurePaper(version, build, sha) {
  const dir = path.join(TF_ROOT, "paper", sha);
  const jar = path.join(dir, "paper.jar");
  const meta = path.join(dir, "fill.json");
  const warmed = path.join(dir, ".nxeon-warmed");
  let fill = null;
  if (!fs.existsSync(jar) || sha256File(jar) !== sha) {
    fs.mkdirSync(dir, { recursive: true });
    const api = `https://fill.papermc.io/v3/projects/paper/versions/${encodeURIComponent(version)}/builds/${build}`;
    const r = await fetch(api, { headers: { "User-Agent": "nxeon-testflight/1 (build host)" } });
    if (!r.ok) throw new Error(`Fill API ${api}: HTTP ${r.status}`);
    fill = await r.json();
    const d = fill.downloads && fill.downloads["server:default"];
    if (!d || !d.checksums || d.checksums.sha256 !== sha) throw new Error(`Fill reports sha256 ${d && d.checksums && d.checksums.sha256} for ${version} build ${build}; registry pin is ${sha}`);
    log(`downloading Paper ${version} build ${build} (${fill.channel})`);
    await download(d.url, jar, sha);
    fs.writeFileSync(meta, JSON.stringify({ id: fill.id, channel: fill.channel, time: fill.time, name: d.name, url: d.url, sha256: sha }, null, 1));
  } else if (fs.existsSync(meta)) fill = JSON.parse(fs.readFileSync(meta, "utf8"));
  return { dir, jar, warmed, fill };
}

function warmPaper(p, javaHome) {
  if (fs.existsSync(p.warmed)) return { warmed: false };
  log("pre-patching Paper (paperclip patch-only, one-off per jar)");
  const t0 = now();
  const r = spawnSync("nice", ["-n", "10", path.join(javaHome, "bin/java"), "-Xmx512m", "-Dpaperclip.patchonly=true", `-DbundlerRepoDir=${p.dir}`, "-jar", p.jar],
    { cwd: p.dir, encoding: "utf8", timeout: 300000, killSignal: "SIGKILL" });
  if (r.status !== 0) throw new Error(`paperclip patch-only failed (${r.status}): ${clip((r.stdout || "") + (r.stderr || ""), 600)}`);
  fs.writeFileSync(p.warmed, new Date().toISOString() + "\n");
  return { warmed: true, ms: now() - t0 };
}

// ------------------------------------------------------------------ leak scan (by exact marker) ----
function procsWithMarker(marker) {
  const out = [];
  for (const d of fs.readdirSync("/proc")) {
    if (!/^\d+$/.test(d) || Number(d) === process.pid) continue;
    let cmd;
    try { cmd = fs.readFileSync(`/proc/${d}/cmdline`, "utf8"); } catch { continue; }
    if (cmd.split("\0").includes(marker)) out.push({ pid: Number(d), cmd: clip(cmd.replace(/\0/g, " "), 200) });
  }
  return out;
}
function killExact(pid, marker) {
  // Re-read the cmdline right before the kill so a recycled PID is never hit.
  try {
    const cmd = fs.readFileSync(`/proc/${pid}/cmdline`, "utf8");
    if (!cmd.split("\0").includes(marker)) return false;
    process.kill(pid, "SIGKILL");
    return true;
  } catch { return false; }
}

// ------------------------------------------------------------------ stage: run (no lock yet) ----
function stageRun(specPath) {
  let spec;
  try { spec = JSON.parse(fs.readFileSync(specPath, "utf8")); } catch (e) { process.stdout.write(JSON.stringify({ error: `bad spec: ${e.message}` }) + "\n"); return 2; }
  const errs = L.validateResolvedSpec(spec, TF_ROOT);
  if (errs.length) { process.stdout.write(JSON.stringify({ error: "invalid spec", problems: errs }) + "\n"); return 2; }
  fs.mkdirSync(TF_ROOT, { recursive: true });
  const r = spawnSync("flock", ["-n", "-E", String(BUSY_EXIT), LOCK, process.execPath, __filename, "locked", specPath],
    { stdio: ["ignore", "inherit", "inherit"], timeout: ((spec.timeouts && spec.timeouts.totalSec) || 420) * 1000 + 360000, killSignal: "SIGKILL" });
  if (r.status === BUSY_EXIT) {
    const rep = baseReport(spec, "busy");
    rep.notes.push("Another Test Flight holds the node-2 lock; nothing ran. Retry later.");
    process.stdout.write(JSON.stringify(finish(rep)) + "\n");
    return BUSY_EXIT;
  }
  return r.status == null ? 1 : r.status;
}

// ------------------------------------------------------------------ stage: locked (host netns, lock held) ----
async function stageLocked(specPath) {
  const spec = JSON.parse(fs.readFileSync(specPath, "utf8"));
  const rep = baseReport(spec, "error");
  const t0 = now();
  const marker = `-Dnxeon.testflight.run=${spec.runId}`;
  const runDir = path.join(TF_ROOT, "runs", spec.runId);
  try {
    if (fs.existsSync(runDir)) throw new Error(`run dir ${runDir} already exists (runId reused?)`);
    const jdk = await ensureJdk(spec.javaRelease);
    const paper = await ensurePaper(spec.version, spec.paper.build, spec.paper.sha256);

    const paper = await ensurePaper(spec.version, spec.paper.build, spec.paper.sha256);
    const warm = warmPaper(paper, jdk.home);
    rep.timings.toolchainMs = now() - t0;
    if (warm.warmed) rep.notes.push(`Paper pre-patched this run (${warm.ms} ms, one-off per jar; not counted in bootMs).`);

    // Artifacts: verify hashes, read descriptors.
    const plugins = [];
    for (const p of spec.plugins || []) {
      const buf = fs.readFileSync(p.path);
      const sha = crypto.createHash("sha256").update(buf).digest("hex");
      if (p.sha256 && p.sha256 !== sha) throw new Error(`plugin ${path.basename(p.path)}: sha256 ${sha} does not match the spec ${p.sha256}`);
      let meta;
      try { meta = L.pluginMeta(buf); } catch (e) { meta = { descriptor: null, name: null, error: e.message }; }
      plugins.push({ path: p.path, file: path.basename(p.path), sha256: sha, ...meta });
      rep.artifacts.push({ kind: "plugin", file: path.basename(p.path), sha256: sha, pluginName: meta.name, apiVersion: meta.apiVersion || null, descriptor: meta.descriptor });
    }
    for (const d of spec.datapacks || []) {
      const st = fs.statSync(d.path);
      rep.artifacts.push({ kind: "datapack", name: d.name, sha256: st.isFile() ? sha256File(d.path) : null, directory: st.isDirectory() });
    }
    if (spec.resourcePack) rep.artifacts.push({ kind: "resourcePack", url: spec.resourcePack.url, sha1: spec.resourcePack.sha1 || null, exercised: false });

    rep.engine = {
      runner: RUNNER_VERSION, runnerSha256: selfHash(), node: process.version, host: os.hostname(), kernel: os.release(),
      jdk: { release: spec.javaRelease, version: jdkVersion(jdk.home), dist: jdk.release, sha256: jdk.sha256 },
      paper: { version: spec.version, build: spec.paper.build, sha256: spec.paper.sha256, channel: paper.fill ? paper.fill.channel : null },
      isolation: { netns: "private (loopback only)", uid: RUN_UID, noNewPrivs: true, nice: 10, activeProcessorCount: 2 },
    };

    // Fresh run dir owned by the unprivileged uid.
    fs.mkdirSync(path.join(runDir, "plugins/bStats"), { recursive: true });
    fs.mkdirSync(path.join(runDir, "tmp"));
    fs.writeFileSync(path.join(runDir, "plugins/bStats/config.txt"), "enabled=false\n");
    for (const p of plugins) fs.copyFileSync(p.path, path.join(runDir, "plugins", p.file));
    if ((spec.datapacks || []).length) {
      const dp = path.join(runDir, "world/datapacks");
      fs.mkdirSync(dp, { recursive: true });
      for (const d of spec.datapacks) {
        const st = fs.statSync(d.path);
        if (st.isDirectory()) fs.cpSync(d.path, path.join(dp, d.name), { recursive: true });
        else fs.copyFileSync(d.path, path.join(dp, d.name.endsWith(".zip") ? d.name : d.name + ".zip"));
      }
    }
    for (const sd of spec.seeds || []) {
      const r = placeSeed(runDir, sd);
      rep.artifacts.push({ kind: "seed", from: sd.from, to: sd.to, files: r.files, bytes: r.bytes, sha256: r.sha256 });
    }
    for (const f of spec.files || []) writeServerFile(runDir, f);
    if ((spec.files || []).length) rep.notes.push(`placed ${spec.files.length} server file(s): ${spec.files.map((f) => f.path).join(", ")}`);
    spawnSync("chown", ["-R", `${RUN_UID}:${RUN_UID}`, runDir]);

    const ctx = { spec, plugins, runDir, marker, javaHome: jdk.home, paperDir: paper.dir, paperJar: paper.jar, out: path.join(runDir, ".inner-report.json") };
    const ctxPath = path.join(TF_ROOT, "runs", `${spec.runId}.ctx.json`);
    fs.writeFileSync(ctxPath, JSON.stringify(ctx));

    const totalMs = ((spec.timeouts && spec.timeouts.totalSec) || 420) * 1000;
    const ti = now();
    const r = spawnSync("unshare", ["--net", "--", "sh", "-c", 'ip link set lo up && exec "$0" "$@"', process.execPath, __filename, "inner", ctxPath],
      { stdio: ["ignore", "inherit", "inherit"], timeout: totalMs + 60000, killSignal: "SIGKILL" });
    rep.timings.innerMs = now() - ti;
    let inner = null;
    try { inner = JSON.parse(fs.readFileSync(ctx.out, "utf8")); } catch { /* inner died before writing */ }
    if (inner) {
      Object.assign(rep, { checks: inner.checks, bootMs: inner.bootMs, doneReportedSec: inner.doneReportedSec, peakRssKb: inner.peakRssKb });
      Object.assign(rep.timings, inner.timings);
      rep.notes.push(...inner.notes);
      rep.status = "completed";
    } else {
      rep.notes.push(`inner stage produced no report (exit ${r.status}, signal ${r.signal}${r.error ? ", " + r.error.message : ""})`);
    }
    fs.rmSync(ctxPath, { force: true });
  } catch (e) {
    rep.notes.push(`runner error: ${clip(e.message, 600)}`);
  }

  // Host-side leak check (runs even after an error): any process still carrying this run's marker is a leak.
  const leakCheck = rep.checks.find((c) => c.id === "no_leaks");
  const tl = now();
  const leaked = procsWithMarker(marker);
  for (const p of leaked) leakCheck.evidence.push(`host: leaked pid ${p.pid} (${p.cmd}) -> SIGKILL ${killExact(p.pid, marker) ? "sent" : "skipped (gone/recycled)"}`);
  if (leaked.length) await sleep(500);
  const hostPorts = new Set();
  for (const f of ["/proc/net/tcp", "/proc/net/tcp6"]) { try { for (const p of L.listeningPorts(fs.readFileSync(f, "utf8"))) hostPorts.add(p); } catch { /* none */ } }
  const inRange = [...hostPorts].filter((p) => p >= L.PORT_RANGE.min && p <= L.PORT_RANGE.max);
  if (inRange.length) leakCheck.evidence.push(`host: listening ports in the reserved range: ${inRange.join(",")}`);
  if (leaked.length || inRange.length) leakCheck.status = "fail";
  else {
    // No pid namespace is used, so this /proc scan sees every process on the host, inside the netns or not.
    leakCheck.evidence.push(`host: no process carries ${marker}; no listening port in ${L.PORT_RANGE.min}-${L.PORT_RANGE.max}`);
    if (leakCheck.status === "not_run") leakCheck.status = "pass";
  }
  leakCheck.durationMs += now() - tl;

  if ((spec.collect || []).length && fs.existsSync(runDir)) {
    try { rep.collected = collectOut(runDir, spec); } catch (e) { rep.notes.push(`collect error: ${clip(e.message, 300)}`); }
  }
  if (!spec.keepDir) fs.rmSync(runDir, { recursive: true, force: true });
  else rep.notes.push(`run dir kept: ${runDir}`);
  rep.timings.totalMs = now() - t0;
  finish(rep);
  fs.mkdirSync(path.join(TF_ROOT, "reports"), { recursive: true });
  fs.writeFileSync(path.join(TF_ROOT, "reports", `${spec.runId}.json`), JSON.stringify(rep, null, 1));
  process.stdout.write(JSON.stringify(rep) + "\n");
  return 0;
}

/** Walk a directory without following symlinks: [{ rel, abs, size }] of regular files; throws on a symlink. */
function walkPlain(dir, rel = "", out = []) {
  for (const e of fs.readdirSync(path.join(dir, rel), { withFileTypes: true }).sort((a, b) => (a.name < b.name ? -1 : 1))) {
    const r = rel ? `${rel}/${e.name}` : e.name;
    if (e.isSymbolicLink()) throw new Error(`symlink refused: ${r}`);
    if (e.isDirectory()) walkPlain(dir, r, out);
    else if (e.isFile()) out.push({ rel: r, abs: path.join(dir, r), size: fs.statSync(path.join(dir, r)).size });
  }
  return out;
}

/** Copy TF_ROOT/seeds/<from> into runDir/<to> (seed dirs are prepared by an operator; files are hashed + reported). */
const MAX_SEED_BYTES = 256 * 1024 * 1024;
function placeSeed(runDir, sd) {
  if (!L.SEED_NAME_RE.test(sd.from) || !L.SEED_TO_RE.test(sd.to) || sd.to.split("/").includes("..")) throw new Error(`refusing seed ${sd.from} -> ${sd.to}`);
  const src = path.join(TF_ROOT, "seeds", sd.from);
  if (!fs.lstatSync(src).isDirectory()) throw new Error(`seed ${sd.from} is not a directory`);
  const files = walkPlain(src);
  const bytes = files.reduce((a, f) => a + f.size, 0);
  if (bytes > MAX_SEED_BYTES) throw new Error(`seed ${sd.from} is larger than ${MAX_SEED_BYTES} bytes`);
  const dest = path.join(runDir, sd.to);
  if (!dest.startsWith(runDir + path.sep)) throw new Error(`seed escapes the run dir: ${sd.to}`);
  const h = crypto.createHash("sha256");
  for (const f of files) {
    const d = path.join(dest, f.rel);
    fs.mkdirSync(path.dirname(d), { recursive: true });
    fs.copyFileSync(f.abs, d);
    h.update(`${sha256File(f.abs)}  ${f.rel}\n`);
  }
  return { files: files.length, bytes, sha256: h.digest("hex") };
}

/** Copy the requested server files out (or list a directory) after the stop. Never follows symlinks. */
const MAX_COLLECT_BYTES = 48 * 1024 * 1024;
function collectOut(runDir, spec) {
  const outDir = path.join(TF_ROOT, "collect", spec.runId);
  fs.mkdirSync(outDir, { recursive: true });
  const res = [];
  for (const [i, c] of (spec.collect || []).entries()) {
    if (!L.COLLECT_RE.test(c) || c.split("/").includes("..")) { res.push({ path: c, error: "refused" }); continue; }
    const abs = path.join(runDir, c.replace(/\/$/, ""));
    if (!abs.startsWith(runDir + path.sep)) { res.push({ path: c, error: "refused" }); continue; }
    let st;
    try { st = fs.lstatSync(abs); } catch { res.push({ path: c, error: "missing" }); continue; }
    if (st.isSymbolicLink()) { res.push({ path: c, error: "symlink" }); continue; }
    if (c.endsWith("/")) {
      if (!st.isDirectory()) { res.push({ path: c, error: "not a directory" }); continue; }
      let list = [];
      try { list = walkPlain(abs).map((f) => `${f.rel} ${f.size}`); } catch (e) { res.push({ path: c, error: e.message }); continue; }
      res.push({ path: c, kind: "listing", entries: list.length, listing: list.slice(0, 400) });
      continue;
    }
    if (!st.isFile()) { res.push({ path: c, error: "not a file" }); continue; }
    if (st.size > MAX_COLLECT_BYTES) { res.push({ path: c, error: `larger than ${MAX_COLLECT_BYTES} bytes` }); continue; }
    const dest = path.join(outDir, `${i}-${path.basename(abs)}`);
    fs.copyFileSync(abs, dest);
    res.push({ path: c, kind: "file", bytes: st.size, sha256: sha256File(dest), dest });
  }
  return res;
}

/** Write a spec text file under runDir (path re-validated; parent dirs and file owned by the server uid). */
function writeServerFile(runDir, f) {
  if (!L.SERVER_FILE_RE.test(f.path) || f.path.split("/").includes("..")) throw new Error(`refusing server file path ${f.path}`);
  const dest = path.join(runDir, f.path);
  if (!dest.startsWith(runDir + path.sep)) throw new Error(`server file escapes the run dir: ${f.path}`);
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  const tmp = `${dest}.tf-part`;
  fs.writeFileSync(tmp, f.content);
  fs.renameSync(tmp, dest);
  let d = path.dirname(dest);
  while (d.startsWith(runDir + path.sep)) { spawnSync("chown", [`${RUN_UID}:${RUN_UID}`, d]); d = path.dirname(d); }
  spawnSync("chown", [`${RUN_UID}:${RUN_UID}`, dest]);
  return Buffer.byteLength(f.content, "utf8");
}

// ------------------------------------------------------------------ RCON client ----
function rconConnect(port, password, timeoutMs) {
  return new Promise((resolve, reject) => {
    const sock = net.connect({ host: "127.0.0.1", port });
    let buf = Buffer.alloc(0);
    const waiters = [];
    let nextId = 100;
    const timer = setTimeout(() => { sock.destroy(); reject(new Error("rcon connect timeout")); }, timeoutMs);
    sock.on("data", (d) => {
      buf = Buffer.concat([buf, d]);
      const { packets, rest } = L.rconParse(buf);
      buf = rest;
      for (const p of packets) for (const w of waiters) w(p);
    });
    sock.on("error", (e) => { clearTimeout(timer); reject(e); });
    const request = (type, body, quietMs = 250, maxMs = timeoutMs) => new Promise((res, rej) => {
      const id = nextId++;
      let text = "", got = false, q = null;
      const done = () => { waiters.splice(waiters.indexOf(w), 1); clearTimeout(hard); clearTimeout(q); res({ id, text, got }); };
      const w = (p) => {
        if (p.id === -1 && type === 3) { waiters.splice(waiters.indexOf(w), 1); clearTimeout(hard); rej(new Error("rcon auth refused")); return; }
        if (p.id !== id) return;
        got = true; text += p.body;
        clearTimeout(q); q = setTimeout(done, type === 3 ? 0 : quietMs);
      };
      const hard = setTimeout(() => { waiters.splice(waiters.indexOf(w), 1); clearTimeout(q); got ? res({ id, text, got }) : rej(new Error(`rcon timeout after ${maxMs} ms`)); }, maxMs);
      waiters.push(w);
      sock.write(L.rconPacket(id, type, body));
    });
    sock.on("connect", async () => {
      clearTimeout(timer);
      try {
        await request(3, password);
        resolve({ command: (c, ms) => request(2, c, 250, ms), close: () => sock.destroy() });
      } catch (e) { sock.destroy(); reject(e); }
    });
  });
}

// ------------------------------------------------------------------ stage: inner (private netns) ----
async function stageInner(ctxPath) {
  const ctx = JSON.parse(fs.readFileSync(ctxPath, "utf8"));
  const { spec, plugins, runDir, marker } = ctx;
  const T = Object.assign({ bootSec: 180, rconSec: 10, stopSec: 45, totalSec: 420 }, spec.timeouts || {});
  const xmx = (spec.memory && spec.memory.xmxMb) || 1024;
  const rssCapKb = ((spec.memory && spec.memory.rssCapMb) || 1800) * 1024;
  const matchers = spec.logMatchers || L.DEFAULT_LOG_MATCHERS;
  const ignores = [...L.DEFAULT_LOG_IGNORES, ...(spec.logIgnore || [])];
  const checks = emptyChecks(requiredFor(spec));
  const C = Object.fromEntries(checks.map((c) => [c.id, c]));
  const notes = [];
  const timings = {};
  const out = { checks, notes, timings, bootMs: null, doneReportedSec: null, peakRssKb: null };
  const save = () => fs.writeFileSync(ctx.out, JSON.stringify(out));

  const { port, rconPort } = L.pickPorts();
  const rconPassword = crypto.randomBytes(18).toString("base64url");
  fs.writeFileSync(path.join(runDir, "eula.txt"), "eula=true\n");
  fs.writeFileSync(path.join(runDir, "server.properties"), L.serverProperties({ port, rconPort, rconPassword, resourcePack: spec.resourcePack, world: spec.world }));
  spawnSync("chown", [`${RUN_UID}:${RUN_UID}`, path.join(runDir, "eula.txt"), path.join(runDir, "server.properties")]);
  notes.push(`ports: server ${port}, rcon ${rconPort} (private netns, 127.0.0.1)`);

  const java = path.join(ctx.javaHome, "bin/java");
  const args = ["-n", "10", "setpriv", `--reuid=${RUN_UID}`, `--regid=${RUN_UID}`, "--clear-groups", "--no-new-privs", "--",
    java, marker, `-Xmx${xmx}m`, "-Xms128m", "-XX:+UseSerialGC", "-XX:ActiveProcessorCount=2", "-XX:MaxMetaspaceSize=256m",
    "-XX:ReservedCodeCacheSize=96m", "-XX:+ExitOnOutOfMemoryError", `-Djava.io.tmpdir=${runDir}/tmp`, `-Duser.home=${runDir}`,
    `-DbundlerRepoDir=${ctx.paperDir}`, "-Dpaper.disableChannelLimit=true", "-jar", ctx.paperJar, "--nogui"];
  const consoleLog = path.join(runDir, "console.log");
  const lines = [];
  let partial = "";
  const t0 = now();
  const child = spawn("nice", args, { cwd: runDir, stdio: ["pipe", "pipe", "pipe"], env: { PATH: "/usr/bin:/bin", HOME: runDir, LANG: "C.UTF-8" } });
  const pid = child.pid;
  let exited = null;
  const exitP = new Promise((r) => child.on("exit", (code, sig) => { exited = { code, sig, at: now() }; r(exited); }));
  const onData = (d) => {
    fs.appendFileSync(consoleLog, d);
    const s = partial + d.toString("utf8");
    const parts = s.split(/\r?\n/);
    partial = parts.pop();
    for (const p of parts) lines.push(p.replace(/\x1b\[[0-9;]*m/g, ""));
  };
  child.stdout.on("data", onData);
  child.stderr.on("data", onData);
  child.stdin.on("error", () => {});

  // Watchdog: peak RSS (VmHWM) sampling, RSS cap, hard total timeout. Kills only `pid`, and only if it is our java.
  let peak = 0, killedFor = null;
  const isOurs = () => { try { return fs.readFileSync(`/proc/${pid}/cmdline`, "utf8").split("\0").includes(marker); } catch { return false; } };
  const hardKill = (why) => { if (!exited && isOurs()) { killedFor = killedFor || why; try { process.kill(pid, "SIGKILL"); } catch { /* gone */ } } };
  const sample = () => {
    try {
      const st = fs.readFileSync(`/proc/${pid}/status`, "utf8");
      const hwm = Number((/VmHWM:\s+(\d+)/.exec(st) || [])[1] || 0), rss = Number((/VmRSS:\s+(\d+)/.exec(st) || [])[1] || 0);
      peak = Math.max(peak, hwm, rss);
      if (rss > rssCapKb) hardKill(`RSS ${rss} kB over the cap ${rssCapKb} kB`);
    } catch { /* not started or gone */ }
  };
  const sampler = setInterval(sample, 500);
  const hard = setTimeout(() => hardKill(`hard timeout ${T.totalSec}s`), T.totalSec * 1000);
  const verifyChild = setTimeout(() => { if (!exited && !isOurs()) notes.push(`warning: pid ${pid} cmdline lacks the marker`); }, 3000);

  // (a) boot_done
  let doneIdx = -1;
  const ta = now();
  while (now() - t0 < T.bootSec * 1000 && !exited) {
    doneIdx = L.findDone(lines);
    if (doneIdx >= 0) break;
    await sleep(200);
  }
  if (doneIdx < 0) doneIdx = L.findDone(lines);
  C.boot_done.durationMs = now() - ta;
  if (doneIdx >= 0) {
    out.bootMs = now() - t0;
    out.doneReportedSec = L.doneSeconds(lines[doneIdx]);
    C.boot_done.status = "pass";
    C.boot_done.evidence.push(`L${doneIdx + 1}: ${clip(lines[doneIdx], 200)}`, `wall ${out.bootMs} ms from spawn`);
  } else {
    C.boot_done.status = "fail";
    C.boot_done.evidence.push(exited ? `server exited before Done (code ${exited.code}, signal ${exited.sig})` : `no "Done" line within ${T.bootSec}s`);
    C.boot_done.evidence.push(...lines.slice(-8).map((l) => clip(l, 240)));
  }
  sample();
  save();

  let rcon = null, rconErr = null, pluginReply = null;
  const up = doneIdx >= 0 && !exited;
  if (up) {
    const tr = now();
    try { rcon = await rconConnect(rconPort, rconPassword, T.rconSec * 1000); } catch (e) { rconErr = e.message; }
    timings.rconConnectMs = now() - tr;
    if (rcon && plugins.length) { try { pluginReply = (await rcon.command("plugins", T.rconSec * 1000)).text; } catch (e) { rconErr = e.message; } }
  }

  // (b) plugins_enabled: log evidence is required; the RCON `plugins` listing corroborates (red = disabled -> fail).
  if (plugins.length && doneIdx >= 0) {
    const tb = now();
    const listed = pluginReply != null ? L.parsePluginList(pluginReply) : null;
    let allOk = true;
    for (const p of plugins) {
      if (!p.name) { allOk = false; C.plugins_enabled.evidence.push(`${p.file}: no plugin.yml/paper-plugin.yml name (${p.error || "descriptor missing"})`); continue; }
      const st = L.pluginLogStatus(lines, p.name, lines.length);
      const inList = listed ? (p.name in listed ? listed[p.name] : "absent") : "rcon unavailable";
      const ok = st.enabled && inList !== false && inList !== "absent";
      if (!ok) allOk = false;
      C.plugins_enabled.evidence.push(`${p.name}: ${ok ? "enabled" : "NOT enabled"} (log: enabling=${st.sawEnabling} enableError=${st.enableError} loadError=${st.loadError} disabled=${st.disabledBeforeStop}; rcon plugins: ${inList})`);
      C.plugins_enabled.evidence.push(...st.evidence.slice(0, 4));
    }
    if (pluginReply != null) C.plugins_enabled.evidence.push(`rcon plugins -> ${clip(L.stripColors(pluginReply).replace(/\n/g, " | "), 300)}`);
    C.plugins_enabled.status = allOk ? "pass" : "fail";
    C.plugins_enabled.durationMs = now() - tb;
  } else if (plugins.length) C.plugins_enabled.evidence.push("server never reached Done; plugin state not checked");

  // (c) startup_log_clean: matcher hits from spawn up to and including the Done line.
  if (lines.length) {
    const tc = now();
    const end = doneIdx >= 0 ? doneIdx + 1 : lines.length;
    const { hits, ignored } = L.matchLogDetailed(lines, matchers, ignores, 0, end);
    C.startup_log_clean.status = doneIdx >= 0 ? (hits.length ? "fail" : "pass") : (hits.length ? "fail" : "not_run");
    const igIds = [...new Set(ignored.map((x) => x.ignore))];
    C.startup_log_clean.evidence.push(`${end} startup lines scanned with ${matchers.length} matchers, ${ignores.length} ignores: ${hits.length} hits, ${ignored.length} ignored${igIds.length ? " (" + igIds.join(", ") + ")" : ""}`);
    C.startup_log_clean.evidence.push(...hits.slice(0, 15).map((h) => `L${h.line} [${h.matcher}] ${clip(h.text, 240)}`));
    if (doneIdx < 0 && !hits.length) C.startup_log_clean.evidence.push("startup never finished, so a clean log proves nothing");
    C.startup_log_clean.durationMs = now() - tc;
  }

  // (d) rcon_checks: spec commands plus one auto `datapack list enabled` check per datapack.
  const rchecks = [...(spec.rcon || []).map((c, i) => ({ id: c.id || `rcon-${i + 1}`, ...c }))];
  if ((spec.datapacks || []).length) rchecks.push({ id: "datapacks-enabled", command: "datapack list enabled", expect: spec.datapacks.map((d) => `file/${d.name}`), auto: true });
  if (rchecks.length) {
    const td = now();
    if (!up) C.rcon_checks.evidence.push("server not up; no RCON commands sent");
    else if (!rcon) { C.rcon_checks.status = "fail"; C.rcon_checks.evidence.push(`RCON unavailable: ${rconErr}`); }
    else {
      let allOk = true;
      for (const c of rchecks) {
        try {
          if (c.writeFile) C.rcon_checks.evidence.push(`${c.id}: wrote ${c.writeFile.path} (${writeServerFile(runDir, c.writeFile)} bytes) before the command`);
          if (c.waitMs) await sleep(c.waitMs);
          const tc = now();
          const r = await rcon.command(c.command, T.rconSec * 1000);
          const tookMs = now() - tc;
          const ev = L.evalRcon(c, r.text);
          if (!ev.ok && c.required !== false) allOk = false;
          const rssNow = (() => { try { return Number((/VmRSS:\s+(\d+)/.exec(fs.readFileSync(`/proc/${pid}/status`, "utf8")) || [])[1] || 0); } catch { return 0; } })();
          C.rcon_checks.evidence.push(`${c.id} '${c.command}' [rss ${Math.round(rssNow / 1024)} MB, ${tookMs} ms]: ${ev.ok ? "ok" : "FAILED"}${ev.missing.length ? " missing " + JSON.stringify(ev.missing) : ""}${ev.forbidden.length ? " forbidden " + JSON.stringify(ev.forbidden) : ""}${c.required === false ? " (optional)" : ""} -> ${clip(L.stripColors(r.text).replace(/\n/g, " | "), 240)}`);
        } catch (e) { if (c.required !== false) allOk = false; C.rcon_checks.evidence.push(`${c.id} '${c.command}': ERROR ${e.message}`); }
      }
      C.rcon_checks.status = allOk ? "pass" : "fail";
    }
    C.rcon_checks.durationMs = now() - td;
  } else C.rcon_checks.evidence.push("no RCON checks in the spec");
  sample();
  save();

  // (e) clean_stop: `stop` over RCON (stdin fallback), exit 0 within stopSec, no matcher hits during shutdown.
  const te = now();
  const stopFrom = lines.length;
  if (!exited) {
    let via = null;
    if (rcon) { try { await rcon.command("stop", 3000); via = "rcon"; } catch (e) { via = /timeout/.test(e.message) ? "rcon (no reply, expected while stopping)" : null; } }
    if (!via) { try { child.stdin.write("stop\n"); via = "stdin"; } catch { via = null; } }
    if (rcon) rcon.close();
    const res = await Promise.race([exitP, sleep(T.stopSec * 1000).then(() => null)]);
    const shutdownHits = L.matchLog(lines, matchers, ignores, stopFrom, lines.length);
    if (!res) {
      hardKill(`stop timeout ${T.stopSec}s`);
      await Promise.race([exitP, sleep(5000)]);
      C.clean_stop.status = up ? "fail" : "not_run";
      C.clean_stop.evidence.push(`no exit within ${T.stopSec}s after stop via ${via}; SIGKILL pid ${pid}`);
    } else if (!up) {
      C.clean_stop.evidence.push(`server was not up; exited (code ${res.code}) after stop via ${via}`);
    } else {
      const ok = res.code === 0 && !shutdownHits.length && !killedFor;
      C.clean_stop.status = ok ? "pass" : "fail";
      C.clean_stop.evidence.push(`stop via ${via}; exit code ${res.code} signal ${res.sig} after ${res.at - te} ms; ${shutdownHits.length} shutdown log hits`);
      C.clean_stop.evidence.push(...shutdownHits.slice(0, 8).map((h) => `L${h.line} [${h.matcher}] ${clip(h.text, 240)}`));
    }
  } else {
    C.clean_stop.evidence.push(`server had already exited (code ${exited.code}, signal ${exited.sig})${killedFor ? "; killed: " + killedFor : ""} before stop`);
    if (up) C.clean_stop.status = "fail";
  }
  C.clean_stop.durationMs = now() - te;
  if (killedFor) notes.push(`watchdog killed pid ${pid}: ${killedFor}`);
  clearInterval(sampler); clearTimeout(hard); clearTimeout(verifyChild);
  out.peakRssKb = peak || null;
  timings.serverWallMs = (exited ? exited.at : now()) - t0;

  // (f) no_leaks inside the netns: our pid gone, nothing carries the marker, no listening ports.
  const tf = now();
  await sleep(300);
  const alive = fs.existsSync(`/proc/${pid}`) && isOurs();
  const marked = procsWithMarker(marker);
  const ports = new Set();
  for (const f of ["/proc/net/tcp", "/proc/net/tcp6"]) { try { for (const p of L.listeningPorts(fs.readFileSync(f, "utf8"))) ports.add(p); } catch { /* none */ } }
  const ourPorts = [port, rconPort].filter((p) => ports.has(p));
  C.no_leaks.status = !alive && !marked.length && !ourPorts.length ? "pass" : "fail";
  C.no_leaks.evidence.push(`netns: java pid ${pid} ${alive ? "STILL ALIVE" : "gone"}; ${marked.length} marked processes; listening ${ourPorts.length ? ourPorts.join(",") : "none"} of ${port},${rconPort}`);
  for (const m of marked) C.no_leaks.evidence.push(`netns: leaked pid ${m.pid} -> SIGKILL ${killExact(m.pid, marker) ? "sent" : "skipped"}`);
  C.no_leaks.durationMs = now() - tf;
  save();
  return 0;
}

// ------------------------------------------------------------------ main ----
(async () => {
  const [cmd, arg] = process.argv.slice(2);
  try {
    if (cmd === "run" && arg) process.exitCode = stageRun(arg);
    else if (cmd === "locked" && arg) process.exitCode = await stageLocked(arg);
    // Exit explicitly: a pending race timer (stop timeout) must not keep the inner stage alive.
    else if (cmd === "inner" && arg) process.exit(await stageInner(arg));
    else if (cmd === "setup" && arg) { const j = await ensureJdk(Number(arg)); process.stdout.write(JSON.stringify({ home: j.home, release: j.release, sha256: j.sha256, fetched: j.fetched, version: jdkVersion(j.home) }) + "\n"); }
    else { process.stderr.write("usage: runner.js run <spec.json> | setup <21|25>\n"); process.exitCode = 2; }
  } catch (e) {
    log(`fatal: ${e.stack || e.message}`);
    process.exitCode = 1;
  }
})();

// Cyrus engine core: ModSpec v1, the typed source of truth of a mod project (MASTER-PLAN 4.1/4.3).
// GAME-AGNOSTIC: nothing here knows any one game. Game facts (versions, which routes and asset kinds a game
// can deliver) come from a GameAdapter (lib/cyrus/adapters) passed in by the caller.
// Pure + client-safe. Zod types in code; `modSpecJsonSchema()` is the portable contract (JSON Schema).
// Every rule failure comes back as a structured issue { path, code, message }, never a thrown error.
import { z } from "zod";
import type { GameAdapter } from "../adapters/types";
import { NAMESPACE_RE } from "./identifiers";

export const CURRENT_SCHEMA_VERSION = 1 as const;

/** What a mod can be built as. Each game adapter says which of these it can really produce. */
export const ARTIFACT_ROUTES = ["plugin", "resourcePack", "dataPack", "clientMod"] as const;
export type ArtifactRoute = (typeof ARTIFACT_ROUTES)[number];

export const ASSET_KINDS = ["texture", "sound", "model", "ui"] as const;
export type AssetKind = (typeof ASSET_KINDS)[number];

/**
 * Where an asset slot's content comes from. generate / library / upload / edit put NEW or CHANGED asset content
 * into the project (plan-gated, lib/cyrus/engine-core/asset-gate.ts); existing / imported keep content the project
 * already holds or brought in with an imported mod (never gated).
 */
export const ASSET_SOURCES = ["generate", "library", "upload", "edit", "existing", "imported"] as const;
export type AssetSource = (typeof ASSET_SOURCES)[number];

export const TEST_KINDS = ["compile", "scan", "boot", "functional", "manual"] as const;

export const REQ_ID_RE = /^REQ-[1-9][0-9]{0,3}$/;
export const TEST_ID_RE = /^T-[1-9][0-9]{0,3}$/;
export const SLOT_ID_RE = /^[a-z][a-z0-9_]{0,47}$/;
export const GAME_ID_RE = /^[a-z][a-z0-9-]{1,31}$/;
/** A catalog asset reference (same pattern as lib/cyrus/library/v2/entry.ts CATALOG_REF_RE). */
export const LIBRARY_REF_RE = /^cat:[0-9a-f]{64}$/;

const line = (max: number) => z.string().trim().min(1).max(max);

const RequirementZ = z.object({
  id: z.string().regex(REQ_ID_RE, "requirement ids are REQ-1, REQ-2, ..."),
  text: z.string().trim().min(3).max(500),
  priority: z.enum(["must", "should", "could"]).default("must"),
}).strict();

const AssetSlotZ = z.object({
  id: z.string().regex(SLOT_ID_RE, "asset ids are lowercase letters, digits and underscores"),
  kind: z.enum(ASSET_KINDS),
  purpose: z.string().trim().min(3).max(300),
  source: z.enum(ASSET_SOURCES).default("generate"),
  /** source "library" only: the catalog asset this slot uses (lib/cyrus/library/v2, `cat:<sha256>`) */
  libraryRef: z.string().regex(LIBRARY_REF_RE, "library refs are cat:<64 hex>").optional(),
  requirementIds: z.array(z.string().regex(REQ_ID_RE)).max(20).default([]),
}).strict();

const TestPlanZ = z.object({
  id: z.string().regex(TEST_ID_RE, "test ids are T-1, T-2, ..."),
  kind: z.enum(TEST_KINDS),
  description: z.string().trim().min(3).max(500),
  covers: z.array(z.string().regex(REQ_ID_RE)).max(50).default([]),
}).strict();

const InstallZ = z.object({
  side: z.enum(["server", "client", "both"]),
  restartRequired: z.boolean(),
  /** What a player must do on their own PC, if anything. */
  clientSteps: z.array(line(300)).max(10).default([]),
  notes: z.array(line(300)).max(10).default([]),
}).strict();

export const ModSpecV1Schema = z.object({
  schemaVersion: z.literal(1),
  game: z.string().regex(GAME_ID_RE),
  target: z.object({ version: z.string().trim().min(1).max(32) }).strict(),
  /** The project's reserved namespace (nx_<hash>); every identifier the mod defines lives under it. */
  namespace: z.string().regex(NAMESPACE_RE, "namespace must be the project's reserved nx_<hash>"),
  summary: z.string().trim().min(10).max(2000),
  routes: z.array(z.enum(ARTIFACT_ROUTES)).min(1).max(ARTIFACT_ROUTES.length),
  requirements: z.array(RequirementZ).min(1).max(100),
  nonGoals: z.array(line(300)).max(50).default([]),
  constraints: z.array(line(300)).max(50).default([]),
  assets: z.array(AssetSlotZ).max(200).default([]),
  tests: z.array(TestPlanZ).max(100).default([]),
  install: InstallZ,
}).strict();

export type ModSpec = z.output<typeof ModSpecV1Schema>;
export type ModSpecInput = z.input<typeof ModSpecV1Schema>;
export type Requirement = ModSpec["requirements"][number];
export type AssetSlot = ModSpec["assets"][number];
export type TestPlan = ModSpec["tests"][number];

export type SpecIssue = { path: string; code: string; message: string };

/** JSON Schema (draft 2020-12) of what a producer writes (defaults optional). */
export function modSpecJsonSchema(): Record<string, unknown> {
  return z.toJSONSchema(ModSpecV1Schema, { io: "input" }) as Record<string, unknown>;
}

// ---------------------------------------------------------------------------
// schemaVersion migrations
// ---------------------------------------------------------------------------

/** `SPEC_MIGRATIONS[n]` rewrites a version-n document into version n+1. Empty while v1 is the only version. */
export type SpecMigration = (doc: Record<string, unknown>) => Record<string, unknown>;
export const SPEC_MIGRATIONS: Readonly<Record<number, SpecMigration>> = {};

export type MigrateResult =
  | { ok: true; doc: Record<string, unknown>; from: number; applied: number[] }
  | { ok: false; errors: SpecIssue[] };

/** Bring a stored document up to CURRENT_SCHEMA_VERSION. Never guesses a missing version. */
export function migrateSpec(raw: unknown, migrations: Readonly<Record<number, SpecMigration>> = SPEC_MIGRATIONS, current: number = CURRENT_SCHEMA_VERSION): MigrateResult {
  const err = (code: string, message: string): MigrateResult => ({ ok: false, errors: [{ path: "schemaVersion", code, message }] });
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return { ok: false, errors: [{ path: "", code: "not_object", message: "spec must be a JSON object" }] };
  const v = (raw as Record<string, unknown>).schemaVersion;
  if (v === undefined) return err("missing_schema_version", "spec has no schemaVersion");
  if (typeof v !== "number" || !Number.isInteger(v) || v < 0) return err("bad_schema_version", "schemaVersion must be a whole number");
  if (v > current) return err("schema_too_new", `spec schemaVersion ${v} is newer than this engine (${current})`);
  let doc = { ...(raw as Record<string, unknown>) };
  const applied: number[] = [];
  for (let n = v; n < current; n++) {
    const m = migrations[n];
    if (!m) return err("no_migration", `no migration from schemaVersion ${n} to ${n + 1}`);
    doc = { ...m(doc), schemaVersion: n + 1 };
    applied.push(n);
  }
  return { ok: true, doc, from: v, applied };
}

// ---------------------------------------------------------------------------
// validation
// ---------------------------------------------------------------------------

export type ValidateOptions = {
  /** Game adapter lookup (lib/cyrus/adapters getAdapter). Without it, game and version are not checked (`unchecked_game` warning). */
  adapterFor?: (game: string) => GameAdapter | null;
  migrations?: Readonly<Record<number, SpecMigration>>;
};

export type ValidateResult =
  | { ok: true; spec: ModSpec; warnings: SpecIssue[]; migratedFrom: number }
  | { ok: false; errors: SpecIssue[]; warnings: SpecIssue[] };

const pathOf = (p: readonly PropertyKey[]) => p.map((k) => (typeof k === "number" ? `[${k}]` : `.${String(k)}`)).join("").replace(/^\./, "");

/** Untrusted JSON -> ModSpec, or every problem found. */
export function validateModSpec(raw: unknown, opts: ValidateOptions = {}): ValidateResult {
  const mig = migrateSpec(raw, opts.migrations);
  if (!mig.ok) return { ok: false, errors: mig.errors, warnings: [] };
  const parsed = ModSpecV1Schema.safeParse(mig.doc);
  if (!parsed.success) {
    return { ok: false, warnings: [], errors: parsed.error.issues.map((i) => ({ path: pathOf(i.path), code: i.code, message: i.message })) };
  }
  const spec = parsed.data;
  const errors: SpecIssue[] = [];
  const warnings: SpecIssue[] = [];

  const dupes = (list: string[], path: string, what: string) => {
    const seen = new Set<string>();
    list.forEach((id, i) => {
      if (seen.has(id)) errors.push({ path: `${path}[${i}]`, code: "duplicate_id", message: `${what} ${id} is listed twice` });
      seen.add(id);
    });
  };
  dupes(spec.requirements.map((r) => r.id), "requirements", "requirement");
  dupes(spec.assets.map((a) => a.id), "assets", "asset");
  dupes(spec.tests.map((t) => t.id), "tests", "test");
  dupes(spec.routes, "routes", "route");

  const reqs = new Set(spec.requirements.map((r) => r.id));
  spec.assets.forEach((a, i) => {
    if (a.libraryRef && a.source !== "library") errors.push({ path: `assets[${i}].libraryRef`, code: "library_ref_needs_library_source", message: `asset ${a.id} has a libraryRef but its source is ${a.source}` });
    if (a.source === "library" && !a.libraryRef) warnings.push({ path: `assets[${i}]`, code: "library_ref_missing", message: `asset ${a.id} comes from the library but names no catalog asset (libraryRef)` });
  });
  spec.assets.forEach((a, i) => a.requirementIds.forEach((r, j) => {
    if (!reqs.has(r)) errors.push({ path: `assets[${i}].requirementIds[${j}]`, code: "unknown_requirement", message: `asset ${a.id} points at ${r}, which is not a requirement` });
  }));
  const covered = new Set<string>();
  spec.tests.forEach((t, i) => t.covers.forEach((r, j) => {
    if (!reqs.has(r)) errors.push({ path: `tests[${i}].covers[${j}]`, code: "unknown_requirement", message: `test ${t.id} covers ${r}, which is not a requirement` });
    covered.add(r);
  }));
  spec.requirements.forEach((r, i) => {
    if (r.priority === "must" && !covered.has(r.id)) warnings.push({ path: `requirements[${i}]`, code: "untested_requirement", message: `${r.id} is a must-have with no acceptance test` });
  });

  if (!opts.adapterFor) {
    warnings.push({ path: "game", code: "unchecked_game", message: "game and target version were not checked against an adapter" });
  } else {
    const adapter = opts.adapterFor(spec.game);
    if (!adapter) {
      errors.push({ path: "game", code: "unknown_game", message: `no game adapter for "${spec.game}"` });
    } else {
      const v = adapter.versions.get(spec.target.version);
      if (!v) errors.push({ path: "target.version", code: "unknown_version", message: `${adapter.name} ${spec.target.version} is not in the version registry` });
      else if (v.status === "blocked") errors.push({ path: "target.version", code: "blocked_version", message: `${adapter.name} ${spec.target.version} is blocked` });
      else if (!v.buildable) warnings.push({ path: "target.version", code: "version_not_buildable", message: `${adapter.name} ${spec.target.version} is ${v.status}: Cyrus cannot build it yet` });
      spec.routes.forEach((r, i) => {
        const a = adapter.artifacts.find((x) => x.route === r);
        if (!a || a.availability === "unsupported") warnings.push({ path: `routes[${i}]`, code: "route_unsupported", message: `${adapter.name} cannot use the ${r} route` });
      });
      spec.assets.forEach((a, i) => {
        if (!adapter.assetDelivery[a.kind].supported) warnings.push({ path: `assets[${i}]`, code: "asset_kind_undeliverable", message: `${adapter.name} has no way to deliver ${a.kind} assets` });
      });
    }
  }
  return errors.length ? { ok: false, errors, warnings } : { ok: true, spec, warnings, migratedFrom: mig.from };
}

// Thin Test Flight invoker: push the runner + artifacts to node-2, run ONE flight, parse the report, summarise.
// Not wired into the live build path. All I/O goes through the injectable `Remote`, so tests use a fake.
// Server-only (node:child_process / node:fs).
import { spawn } from "node:child_process";
import { createHash, randomBytes } from "node:crypto";
import { readFileSync, readdirSync, statSync } from "node:fs";
import path from "node:path";
import type { TestFlightReport, TestFlightSpec, TestFlightSummary, ResolvedSpec } from "./types";
import { resolveSpec, validateSpec, TF_DEFAULT_ROOT } from "./spec";
import { summarize } from "./summary";

export type ExecResult = { code: number | null; stdout: string; stderr: string };
/** Runs a shell command line on the build host. `input` is piped to stdin. */
export type Remote = { exec: (command: string, opts?: { input?: Buffer; timeoutMs?: number }) => Promise<ExecResult> };

export const NODE2 = "root@178.63.94.114";
export const BUSY_EXIT = 75;

/** POSIX single-quote a word for a remote shell. */
export const shq = (s: string) => `'${String(s).replace(/'/g, `'\\''`)}'`;

/** Real transport: ssh with BatchMode (no prompts), hard local timeout (SIGKILL of the ssh child we spawned). */
export function sshRemote(host = NODE2): Remote {
  return {
    exec: (command, opts = {}) => new Promise((resolve) => {
      const child = spawn("ssh", ["-o", "BatchMode=yes", "-o", "ConnectTimeout=15", host, command], { stdio: ["pipe", "pipe", "pipe"] });
      let stdout = "", stderr = "";
      child.stdout.on("data", (d) => (stdout += d));
      child.stderr.on("data", (d) => (stderr += d));
      const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
      child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
      child.stdin.on("error", () => {});
      child.stdin.end(opts.input ?? undefined);
    }),
  };
}

export type RunOptions = {
  remote?: Remote;
  root?: string;
  /** Directory holding runner.js + lib.js (default: the repo copy). */
  runnerDir?: string;
  runId?: string;
  readFile?: (p: string) => Buffer;
  /** Files of a local datapack directory, relative path -> absolute path. */
  listDir?: (dir: string) => { rel: string; abs: string }[];
};

export type RunResult = { report: TestFlightReport; summary: TestFlightSummary; resolved: ResolvedSpec; stderr: string };

const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");

function walk(dir: string, rel = ""): { rel: string; abs: string }[] {
  const out: { rel: string; abs: string }[] = [];
  for (const e of readdirSync(path.join(dir, rel)).sort()) {
    const r = rel ? `${rel}/${e}` : e;
    if (statSync(path.join(dir, r)).isDirectory()) out.push(...walk(dir, r));
    else out.push({ rel: r, abs: path.join(dir, r) });
  }
  return out;
}

export function newRunId(version: string): string {
  return `tf-${version.replace(/[^0-9]+/g, "-")}-${Date.now().toString(36)}-${randomBytes(3).toString("hex")}`.toLowerCase();
}

/** Minimal POSIX ustar archive (regular files only) so one ssh call can carry every artifact. */
export function tarball(entries: { name: string; data: Buffer }[]): Buffer {
  const blocks: Buffer[] = [];
  for (const e of entries) {
    if (!e.name || e.name.startsWith("/") || e.name.split("/").includes("..") || Buffer.byteLength(e.name) > 99) throw new Error(`bad tar entry name ${e.name}`);
    const h = Buffer.alloc(512);
    h.write(e.name, 0, "utf8");
    h.write("0000644\0", 100); h.write("0000000\0", 108); h.write("0000000\0", 116);
    h.write(e.data.length.toString(8).padStart(11, "0") + "\0", 124);
    h.write("00000000000\0", 136);
    h.fill(" ", 148, 156);
    h.write("0", 156);
    h.write("ustar\0" + "00", 257);
    let sum = 0;
    for (const b of h) sum += b;
    h.write(sum.toString(8).padStart(6, "0") + "\0 ", 148);
    blocks.push(h, e.data, Buffer.alloc((512 - (e.data.length % 512)) % 512));
  }
  blocks.push(Buffer.alloc(1024));
  return Buffer.concat(blocks);
}

/** Push the runner if node-2's copy differs (content hash), so every flight runs the code in this repo. */
async function ensureRunner(remote: Remote, root: string, dir: string, read: (p: string) => Buffer) {
  const files = ["lib.js", "runner.js"];
  const want = files.map((f) => `${sha256(read(path.join(dir, f)))}  ${root}/runner/${f}`).join("\n") + "\n";
  const have = await remote.exec(`sha256sum ${files.map((f) => shq(`${root}/runner/${f}`)).join(" ")} 2>/dev/null || true`);
  if (have.stdout === want) return;
  const stage = `${root}/runner/.new-${randomBytes(4).toString("hex")}`;
  const tar = tarball(files.map((f) => ({ name: f, data: read(path.join(dir, f)) })));
  const r = await remote.exec(`mkdir -p ${shq(stage)} && tar --no-same-owner -xf - -C ${shq(stage)} && ${files.map((f) => `mv -f ${shq(`${stage}/${f}`)} ${shq(`${root}/runner/${f}`)}`).join(" && ")} && rmdir ${shq(stage)}`, { input: tar });
  if (r.code !== 0) throw new Error(`could not install the runner on the build host: ${r.stderr.slice(0, 300)}`);
}

/** Run one Test Flight. Throws only for an invalid spec or a transport failure; every server outcome is in the report. */
export async function runTestFlight(spec: TestFlightSpec, opts: RunOptions = {}): Promise<RunResult> {
  const v = validateSpec(spec);
  if (!v.ok) throw new Error(`invalid Test Flight spec: ${v.errors.join("; ")}`);
  const remote = opts.remote ?? sshRemote();
  const root = (opts.root ?? TF_DEFAULT_ROOT).replace(/\/$/, "");
  const read = opts.readFile ?? ((p: string) => readFileSync(p));
  const list = opts.listDir ?? ((d: string) => walk(d));
  const runId = opts.runId ?? newRunId(spec.version);
  const resolved = resolveSpec(spec, { runId, root });
  const inbox = `${root}/inbox/${runId}`;
  const rel = (p: string) => p.slice(inbox.length + 1);

  // Everything local goes into one tar: plugins, datapacks, the resolved spec.
  const entries: { name: string; data: Buffer }[] = [];
  for (const [i, p] of (spec.plugins ?? []).entries()) {
    if (!p.localPath) continue;
    const buf = read(p.localPath);
    if (p.sha256 && sha256(buf) !== p.sha256) throw new Error(`${p.localPath}: sha256 does not match the spec`);
    resolved.plugins[i].sha256 = sha256(buf); // the runner re-hashes on node-2 and refuses a mismatch
    entries.push({ name: rel(resolved.plugins[i].path), data: buf });
  }
  for (const [i, d] of (spec.datapacks ?? []).entries()) {
    if (!d.localPath) continue;
    if (/\.zip$/.test(d.localPath)) {
      resolved.datapacks[i].path += ".zip";
      entries.push({ name: rel(resolved.datapacks[i].path), data: read(d.localPath) });
      continue;
    }
    for (const f of list(d.localPath)) entries.push({ name: `${rel(resolved.datapacks[i].path)}/${f.rel}`, data: read(f.abs) });
  }
  entries.push({ name: "spec.json", data: Buffer.from(JSON.stringify(resolved)) });

  await ensureRunner(remote, root, opts.runnerDir ?? path.join(process.cwd(), "services/modbuilder/tools/testflight"), read);
  // One call: unpack, run (outer hard timeout on node-2 on top of the runner's own), always remove the inbox.
  const hard = resolved.timeouts.totalSec + 420;
  const cmd = [
    `mkdir -p ${shq(inbox)} && tar --no-same-owner -xf - -C ${shq(inbox)} || exit 3`,
    `TF_ROOT=${shq(root)} timeout -s KILL ${hard} node ${shq(`${root}/runner/runner.js`)} run ${shq(`${inbox}/spec.json`)}`,
    `rc=$?; rm -rf -- ${shq(inbox)}; exit $rc`,
  ].join("\n");
  const r = await remote.exec(cmd, { input: tarball(entries), timeoutMs: (hard + 60) * 1000 });
  const line = r.stdout.trim().split("\n").filter(Boolean).pop() ?? "";
  let report: TestFlightReport;
  try { report = JSON.parse(line); } catch { throw new Error(`runner gave no report (exit ${r.code}): ${(r.stderr || r.stdout).slice(-400)}`); }
  if ((report as unknown as { error?: string }).error) throw new Error(`runner refused the spec: ${JSON.stringify(report).slice(0, 400)}`);
  if (r.code === BUSY_EXIT && report.status !== "busy") report.status = "busy";
  return { report, summary: summarize(spec, report), resolved, stderr: r.stderr };
}

/**
 * Fetch the files a flight collected (spec `collect`, runner tf-lite-2) and remove them from the build host.
 * Each file is re-hashed against the sha256 the runner reported; a mismatch throws.
 */
export async function pullCollected(report: TestFlightReport, opts: { remote?: Remote; root?: string } = {}): Promise<Map<string, Buffer>> {
  const remote = opts.remote ?? sshRemote();
  const root = (opts.root ?? TF_DEFAULT_ROOT).replace(/\/$/, "");
  const out = new Map<string, Buffer>();
  const items = (report.collected ?? []).filter((c) => c.kind === "file" && c.dest && c.sha256);
  const dir = `${root}/collect/${report.runId}`;
  try {
    for (const c of items) {
      if (!c.dest!.startsWith(dir + "/") || c.dest!.split("/").includes("..")) throw new Error(`collected path outside ${dir}: ${c.dest}`);
      const r = await remote.exec(`base64 -w0 ${shq(c.dest!)}`, { timeoutMs: 120000 });
      if (r.code !== 0) throw new Error(`could not read ${c.dest}: ${r.stderr.slice(0, 200)}`);
      const buf = Buffer.from(r.stdout.trim(), "base64");
      if (sha256(buf) !== c.sha256) throw new Error(`${c.path}: sha256 changed in transit`);
      out.set(c.path, buf);
    }
  } finally {
    if (report.runId && /^[a-z0-9][a-z0-9-]{5,63}$/.test(report.runId)) await remote.exec(`rm -rf -- ${shq(dir)}`);
  }
  return out;
}

// Cyrus Test Flight (R0) types: the typed spec a caller writes, the resolved spec the node-2 runner receives,
// and the report it returns. The runner is services/modbuilder/tools/testflight/runner.js (plain Node on node-2).
// A check passes only if it actually ran; a skipped required check means the flight is NOT a success.

export const CHECK_IDS = ["boot_done", "plugins_enabled", "startup_log_clean", "rcon_checks", "clean_stop", "no_leaks"] as const;
export type CheckId = (typeof CHECK_IDS)[number];
export type CheckStatus = "pass" | "fail" | "not_run";

/** A regex matched against each log line (JS syntax; flags limited to i/m/s/u). */
export type LogMatcher = { id: string; pattern: string; flags?: string };

/** A small text file in the server directory (e.g. a plugin's config). Path relative to the server root, under plugins/ only. */
export type ServerFile = { path: string; content: string };

export type SeedRef = { from: string; to: string };

export type RconCheck = {
  id?: string;
  /** Written (created or replaced) in the server dir right before this command is sent, e.g. to test a config reload. */
  writeFile?: ServerFile;
  /** Wait this long (ms, max 30000) before sending the command (after writeFile), e.g. for a file watcher. */
  waitMs?: number;
  /** One console command without the leading slash. stop/restart/op/deop/reload are reserved for the runner. */
  command: string;
  /** Every substring must appear in the reply (colour codes stripped). Empty = the command only has to answer. */
  expect?: string[];
  /** None of these may appear. */
  expectNot?: string[];
  /** Default true. An optional check is reported but does not fail the stage. */
  required?: boolean;
};

/** An artifact either on the caller's disk (uploaded by the invoker) or already on node-2 under the Test Flight root. */
export type ArtifactRef = { localPath: string; remotePath?: never; sha256?: string } | { remotePath: string; localPath?: never; sha256?: string };

export type TestFlightSpec = {
  /** Exact registry id, e.g. "26.2" or "1.21.11". The registry supplies the JDK and the pinned Paper server jar. */
  version: string;
  plugins?: ArtifactRef[];
  /** Datapacks go into world/datapacks before first boot; each one adds an automatic `datapack list enabled` check. */
  datapacks?: (ArtifactRef & { name: string })[];
  /** Written to server.properties only. No client connects, so the pack itself is NOT exercised (reported as such). */
  resourcePack?: { url: string; sha1?: string; id?: string; required?: boolean };
  /** Small text files placed before the first boot (max 16, 64 KB each, under plugins/). */
  files?: ServerFile[];
  /**
   * Read-only directories prepared on node-2 under `<root>/seeds/<from>` copied into the server dir before boot
   * (`to` = "libraries" or a path under plugins/). The flight has no internet, so a managed plugin's pinned runtime
   * libraries are seeded this way (runner tf-lite-2).
   */
  seeds?: SeedRef[];
  /** Server-dir files copied out after the stop to `<root>/collect/<runId>/` (a path ending in "/" = a listing). */
  collect?: string[];
  rcon?: RconCheck[];
  /** Replace the runner's default startup-log matchers (omit to use the defaults). */
  logMatchers?: LogMatcher[];
  /** Extra ignore patterns, added to the runner's sandbox ignores. */
  logIgnore?: LogMatcher[];
  timeouts?: { bootSec?: number; rconSec?: number; stopSec?: number; totalSec?: number };
  /** xmxMb max 1024 (node-2 rule). rssCapMb is a watchdog: above it the server is killed and the run fails. */
  memory?: { xmxMb?: number; rssCapMb?: number };
  /** Extra stages to treat as required even if the spec would not make them required. */
  requireStages?: CheckId[];
  /** Keep the server dir on node-2 for debugging (default false). */
  keepDir?: boolean;
  /** World options (runner tf-lite-3): generateStructures turns structure generation on (default off: a tiny flat world). */
  world?: { generateStructures?: boolean };
};

/** What the runner receives: registry pins resolved, artifact paths on node-2. */
export type ResolvedSpec = {
  schema: 1;
  runId: string;
  version: string;
  javaRelease: 21 | 25;
  paper: { build: number; sha256: string };
  plugins: { path: string; sha256?: string }[];
  datapacks: { path: string; name: string }[];
  resourcePack?: TestFlightSpec["resourcePack"];
  files?: ServerFile[];
  seeds?: SeedRef[];
  collect?: string[];
  rcon: RconCheck[];
  logMatchers?: LogMatcher[];
  logIgnore?: LogMatcher[];
  timeouts: { bootSec: number; rconSec: number; stopSec: number; totalSec: number };
  memory: { xmxMb: number; rssCapMb: number };
  keepDir: boolean;
  world?: { generateStructures?: boolean };
};

export type CheckResult = { id: CheckId; status: CheckStatus; required: boolean; evidence: string[]; durationMs: number };

export type ReportArtifact =
  | { kind: "plugin"; file: string; sha256: string; pluginName: string | null; apiVersion: string | null; descriptor: string | null }
  | { kind: "datapack"; name: string; sha256: string | null; directory: boolean }
  | { kind: "resourcePack"; url: string; sha1: string | null; exercised: false }
  | { kind: "seed"; from: string; to: string; files: number; bytes: number; sha256: string };

/** A collected server file (runner tf-lite-2) or a directory listing. */
export type CollectedItem = { path: string; kind?: "file" | "listing"; bytes?: number; sha256?: string; dest?: string; entries?: number; listing?: string[]; error?: string };

export type EngineMeta = {
  runner: string;
  runnerSha256: string;
  node: string;
  host: string;
  kernel: string;
  jdk: { release: number; version: string | null; dist: string; sha256: string };
  paper: { version: string; build: number; sha256: string; channel: string | null };
  isolation: { netns: string; uid: number; noNewPrivs: boolean; nice: number; activeProcessorCount: number };
};

/** Raw runner output. `status` says whether the runner itself completed; `overall` is its own verdict (recomputed by summarize). */
export type TestFlightReport = {
  schema: 1;
  runId: string | null;
  status: "completed" | "busy" | "error";
  version: string | null;
  javaRelease: number | null;
  startedAt: string;
  finishedAt: string | null;
  checks: CheckResult[];
  timings: Record<string, number>;
  bootMs: number | null;
  doneReportedSec: number | null;
  peakRssKb: number | null;
  artifacts: ReportArtifact[];
  engine: EngineMeta | null;
  notes: string[];
  overall: "passed" | "failed" | "incomplete";
  collected?: CollectedItem[];
};

export type Overall = "passed" | "failed" | "incomplete" | "busy" | "error";

export type TestFlightSummary = {
  version: string;
  overall: Overall;
  /** true only when overall === "passed". */
  success: boolean;
  passed: CheckId[];
  failed: CheckId[];
  /** Required checks that did not run (or "passed" without evidence): any entry here blocks success. */
  skippedRequired: CheckId[];
  notRunOptional: CheckId[];
  reasons: string[];
  bootMs: number | null;
  peakRssKb: number | null;
  runId: string | null;
};

export type MatrixSummary = { overall: Overall; success: boolean; versions: TestFlightSummary[] };
// Test Flight spec validation + resolution against the version registry. Pure (no I/O): fails closed on anything
// the registry cannot vouch for (unknown version, no pinned Paper server jar).
import { getVersion, type VersionRow } from "../versions/registry";
import type { CheckId, ResolvedSpec, TestFlightSpec, LogMatcher, ServerFile } from "./types";
import { CHECK_IDS } from "./types";

export const TF_DEFAULT_ROOT = "/tank/nxeon-build/tmp/testflight";
export const DEFAULT_TIMEOUTS = { bootSec: 180, rconSec: 10, stopSec: 45, totalSec: 420 } as const;
export const DEFAULT_MEMORY = { xmxMb: 1024, rssCapMb: 1800 } as const;
const RESERVED_COMMANDS = /^\/?(stop|restart|op|deop|reload)\b/i;
const SHA256 = /^[0-9a-f]{64}$/;
/** Same rule as lib.js SERVER_FILE_RE: relative, under plugins/, plain segments only. */
export const SERVER_FILE_RE = /^plugins\/[A-Za-z0-9_-][A-Za-z0-9_.-]{0,63}(\/[A-Za-z0-9_-][A-Za-z0-9_.-]{0,63}){0,3}$/;
export const MAX_SERVER_FILES = 16;
export const MAX_SERVER_FILE_BYTES = 64 * 1024;
/** Same rules as lib.js (runner tf-lite-2). */
export const SEED_NAME_RE = /^[a-z0-9][a-z0-9._-]{0,63}$/;
export const SEED_TO_RE = /^(libraries|plugins\/[A-Za-z0-9_-][A-Za-z0-9_.-]{0,63}(\/(?!\.\.?(\/|$))[A-Za-z0-9_.-]{1,64}){0,4})$/;
export const COLLECT_RE = /^[A-Za-z0-9_-][A-Za-z0-9_.-]{0,63}(\/(?!\.\.?(\/|$))[A-Za-z0-9_.-]{1,64}){0,7}\/?$/;
export const MAX_SEEDS = 8;
export const MAX_COLLECT = 12;

function checkFile(f: ServerFile | undefined, key: string, errs: string[]) {
  if (!f || typeof f.path !== "string" || !SERVER_FILE_RE.test(f.path) || f.path.split("/").includes("..")) errs.push(`${key}.path must be a relative path under plugins/ (plain segments)`);
  if (!f || typeof f.content !== "string" || Buffer.byteLength(f.content, "utf8") > MAX_SERVER_FILE_BYTES) errs.push(`${key}.content must be text of at most ${MAX_SERVER_FILE_BYTES} bytes`);
}

function checkMatchers(list: LogMatcher[] | undefined, key: string, errs: string[]) {
  for (const [i, m] of (list ?? []).entries()) {
    if (!m || typeof m.pattern !== "string" || !m.pattern) { errs.push(`${key}[${i}]: pattern is required`); continue; }
    if (m.pattern.length > 400) errs.push(`${key}[${i}]: pattern longer than 400 chars`);
    try { new RegExp(m.pattern, (m.flags ?? "").replace(/[^imsu]/g, "")); } catch (e) { errs.push(`${key}[${i}]: ${(e as Error).message}`); }
  }
}

export type PinnedRow = VersionRow & { paperBuild: number; paperServerSha256: string };
export type SpecCheck = { ok: true; row: PinnedRow } | { ok: false; errors: string[] };

/** Validate a caller spec. `lookup` is injectable for tests; defaults to the real registry. */
export function validateSpec(spec: TestFlightSpec, lookup: (id: string) => VersionRow | null = getVersion): SpecCheck {
  const errs: string[] = [];
  const row = lookup(String(spec?.version ?? ""));
  if (!row) errs.push(`Minecraft ${spec?.version} is not in the version registry`);
  else {
    if (!row.paperBuild || !Number.isInteger(row.paperBuild)) errs.push(`${row.id} has no pinned Paper server build, so it cannot be test-flown`);
    if (!SHA256.test(String(row.paperServerSha256 ?? ""))) errs.push(`${row.id} has no pinned Paper server sha256`);
  }
  const arts = [...(spec.plugins ?? []).map((a, i) => ["plugins", i, a] as const), ...(spec.datapacks ?? []).map((a, i) => ["datapacks", i, a] as const)];
  for (const [k, i, a] of arts) {
    const hasLocal = typeof a?.localPath === "string" && a.localPath.length > 0;
    const hasRemote = typeof a?.remotePath === "string" && a.remotePath.length > 0;
    if (hasLocal === hasRemote) errs.push(`${k}[${i}]: give exactly one of localPath or remotePath`);
    if (a?.sha256 != null && !SHA256.test(a.sha256)) errs.push(`${k}[${i}]: sha256 must be 64 lowercase hex chars`);
    if (k === "plugins" && !/\.jar$/.test(String(a?.localPath ?? a?.remotePath ?? ""))) errs.push(`plugins[${i}]: must be a .jar`);
  }
  for (const [i, d] of (spec.datapacks ?? []).entries()) if (!/^[a-z0-9_.-]{1,64}$/.test(String(d?.name ?? ""))) errs.push(`datapacks[${i}].name must be 1-64 chars of a-z 0-9 _ . -`);
  const pluginNames = new Set<string>();
  for (const p of spec.plugins ?? []) {
    const b = String(p.localPath ?? p.remotePath ?? "").split("/").pop()!;
    if (pluginNames.has(b)) errs.push(`two plugins share the file name ${b}`);
    pluginNames.add(b);
  }
  for (const [i, c] of (spec.rcon ?? []).entries()) {
    const cmd = String(c?.command ?? "");
    if (!cmd.trim() || cmd.length > 200 || /[\r\n]/.test(cmd)) errs.push(`rcon[${i}].command must be one line of 1-200 chars`);
    if (RESERVED_COMMANDS.test(cmd.trim())) errs.push(`rcon[${i}]: '${cmd}' is reserved for the runner`);
    if (c.expect != null && !Array.isArray(c.expect)) errs.push(`rcon[${i}].expect must be an array of strings`);
    if (c.writeFile != null) checkFile(c.writeFile, `rcon[${i}].writeFile`, errs);
    if (c.waitMs != null && !(Number.isInteger(c.waitMs) && c.waitMs >= 0 && c.waitMs <= 30000)) errs.push(`rcon[${i}].waitMs must be 0-30000`);
  }
  if ((spec.files ?? []).length > MAX_SERVER_FILES) errs.push(`files: at most ${MAX_SERVER_FILES}`);
  for (const [i, f] of (spec.files ?? []).entries()) checkFile(f, `files[${i}]`, errs);
  if ((spec.seeds ?? []).length > MAX_SEEDS) errs.push(`seeds: at most ${MAX_SEEDS}`);
  for (const [i, sd] of (spec.seeds ?? []).entries()) {
    if (!SEED_NAME_RE.test(String(sd?.from ?? ""))) errs.push(`seeds[${i}].from must be a seed name under <root>/seeds`);
    if (!SEED_TO_RE.test(String(sd?.to ?? "")) || String(sd?.to).split("/").includes("..")) errs.push(`seeds[${i}].to must be libraries or a path under plugins/`);
  }
  if ((spec.collect ?? []).length > MAX_COLLECT) errs.push(`collect: at most ${MAX_COLLECT}`);
  for (const [i, c] of (spec.collect ?? []).entries()) {
    if (typeof c !== "string" || !COLLECT_RE.test(c) || c.split("/").includes("..")) errs.push(`collect[${i}] must be a relative path of plain segments`);
  }
  checkMatchers(spec.logMatchers, "logMatchers", errs);
  checkMatchers(spec.logIgnore, "logIgnore", errs);
  if (spec.logMatchers && spec.logMatchers.length === 0) errs.push("logMatchers: an empty list would make the log check vacuous; omit it to use the defaults");
  const t = spec.timeouts ?? {};
  for (const [k, max] of [["bootSec", 600], ["rconSec", 60], ["stopSec", 120], ["totalSec", 900]] as const) {
    const v = t[k];
    if (v != null && !(Number.isFinite(v) && v > 0 && v <= max)) errs.push(`timeouts.${k} must be 1-${max}`);
  }
  const m = spec.memory ?? {};
  if (m.xmxMb != null && !(Number.isInteger(m.xmxMb) && m.xmxMb >= 256 && m.xmxMb <= 1024)) errs.push("memory.xmxMb must be 256-1024 (node-2 allows at most -Xmx1g)");
  if (m.rssCapMb != null && !(Number.isInteger(m.rssCapMb) && m.rssCapMb >= 512 && m.rssCapMb <= 2048)) errs.push("memory.rssCapMb must be 512-2048");
  for (const s of spec.requireStages ?? []) if (!(CHECK_IDS as readonly string[]).includes(s)) errs.push(`requireStages: unknown stage ${s}`);
  if (spec.world != null && (Object.keys(spec.world).some((k) => k !== "generateStructures") || (spec.world.generateStructures != null && typeof spec.world.generateStructures !== "boolean"))) errs.push("world may only hold generateStructures (boolean)");
  if (errs.length || !row) return { ok: false, errors: errs };
  return { ok: true, row: row as PinnedRow };
}

/** Required stages for a spec. The summary uses THIS (what we asked for), not the runner's own flags. */
export function requiredStages(spec: TestFlightSpec): Set<CheckId> {
  const req = new Set<CheckId>(["boot_done", "startup_log_clean", "clean_stop", "no_leaks"]);
  if ((spec.plugins ?? []).length) req.add("plugins_enabled");
  if ((spec.rcon ?? []).length || (spec.datapacks ?? []).length) req.add("rcon_checks");
  for (const s of spec.requireStages ?? []) req.add(s);
  return req;
}

const base = (p: string) => p.split("/").pop()!;

/** Resolve a validated spec for the runner. Local artifacts are mapped to `<root>/inbox/<runId>/<file>`. */
export function resolveSpec(spec: TestFlightSpec, opts: { runId: string; root?: string; lookup?: (id: string) => VersionRow | null }): ResolvedSpec {
  const v = validateSpec(spec, opts.lookup);
  if (!v.ok) throw new Error(`invalid Test Flight spec: ${v.errors.join("; ")}`);
  if (!/^[a-z0-9][a-z0-9-]{5,63}$/.test(opts.runId)) throw new Error("runId must be 6-64 chars of a-z, 0-9, -");
  const root = (opts.root ?? TF_DEFAULT_ROOT).replace(/\/$/, "");
  const inbox = `${root}/inbox/${opts.runId}`;
  return {
    schema: 1,
    runId: opts.runId,
    version: v.row.id,
    javaRelease: v.row.javaRelease,
    paper: { build: v.row.paperBuild, sha256: v.row.paperServerSha256 },
    plugins: (spec.plugins ?? []).map((p) => ({ path: p.remotePath ?? `${inbox}/${base(p.localPath!)}`, ...(p.sha256 ? { sha256: p.sha256 } : {}) })),
    datapacks: (spec.datapacks ?? []).map((d) => ({ name: d.name, path: d.remotePath ?? `${inbox}/dp-${d.name}` })),
    ...(spec.resourcePack ? { resourcePack: spec.resourcePack } : {}),
    ...(spec.files?.length ? { files: spec.files } : {}),
    ...(spec.seeds?.length ? { seeds: spec.seeds } : {}),
    ...(spec.collect?.length ? { collect: spec.collect } : {}),
    rcon: spec.rcon ?? [],
    ...(spec.logMatchers ? { logMatchers: spec.logMatchers } : {}),
    ...(spec.logIgnore ? { logIgnore: spec.logIgnore } : {}),
    timeouts: { ...DEFAULT_TIMEOUTS, ...(spec.timeouts ?? {}) },
    memory: { ...DEFAULT_MEMORY, ...(spec.memory ?? {}) },
    keepDir: !!spec.keepDir,
    ...(spec.world ? { world: { ...(spec.world.generateStructures != null ? { generateStructures: spec.world.generateStructures } : {}) } } : {}),
  };
}

