"use strict";
// Cyrus Test Flight (R0): pure helpers for the disposable real-server runner (runner.js).
// No I/O, no child processes: everything here is unit-tested (test/cyrus-testflight.test.ts).
// Plain CommonJS so it runs as-is on node-2 (copied next to runner.js) and in the repo tests.

const zlib = require("zlib");

const SCHEMA = 1;
/** The ordered checks. A check passes only if it actually ran and its evidence says so. */
const CHECK_IDS = ["boot_done", "plugins_enabled", "startup_log_clean", "rcon_checks", "clean_stop", "no_leaks"];
const STATUSES = ["pass", "fail", "not_run"];

/** Reserved port range for Test Flight servers (they also run in a private network namespace). */
const PORT_RANGE = { min: 47100, max: 47199 };

/**
 * Default startup-log matchers. Each hit is a problem unless an ignore pattern also matches the line.
 * Paper prints console lines as "[HH:MM:SS LEVEL]: msg" (stdout) or "[HH:MM:SS] [thread/LEVEL]: msg" (latest.log).
 */
const DEFAULT_LOG_MATCHERS = [
  { id: "level-error", pattern: "(?:^\\[[\\d:]+ (?:ERROR|FATAL)\\]|\\[[^\\]]*/(?:ERROR|FATAL)\\])", flags: "" },
  { id: "exception-header", pattern: "^\\s*(?:Caused by: )?(?:[a-zA-Z_$][\\w$]*\\.)+[\\w$]*(?:Exception|Error)(?::|$)", flags: "" },
  { id: "enable-error", pattern: "Error occurred while (?:enabling|loading|disabling) ", flags: "" },
  { id: "could-not-load", pattern: "Could not load (?:plugin )?'", flags: "" },
  { id: "datapack-error", pattern: "(?:Couldn't (?:parse|load) data file|Failed to (?:load|parse) (?:datapack|data pack|function))", flags: "i" },
];

/**
 * Lines that are known-harmless on a Test Flight server. Each one is caused by the sandbox itself (the server runs in a
 * private network namespace with no internet), never by the plugin under test. Kept short and specific on purpose;
const MAX_SEEDS = 8, MAX_COLLECT = 12;
function serverFileErrors(f, key) {
  const errs = [];
  if (!f || typeof f.path !== "string" || !SERVER_FILE_RE.test(f.path) || f.path.split("/").includes("..")) errs.push(`${key}.path must be a relative path under plugins/`);
  if (!f || typeof f.content !== "string" || Buffer.byteLength(f.content, "utf8") > 64 * 1024) errs.push(`${key}.content must be text of at most 65536 bytes`);
  return errs;
}

function validateResolvedSpec(s, root) {
  const errs = [];
  if (!s || typeof s !== "object") return ["spec must be an object"];
  if (s.schema !== SCHEMA) errs.push(`schema must be ${SCHEMA}`);
  if (!/^[a-z0-9][a-z0-9-]{5,63}$/.test(String(s.runId || ""))) errs.push("runId must be 6-64 chars of a-z, 0-9, -");
  if (!VERSION_ID.test(String(s.version || ""))) errs.push("version must be an exact Minecraft id (1.21.x or 26.x)");
  if (![21, 25].includes(s.javaRelease)) errs.push("javaRelease must be 21 or 25");
  if (!s.paper || !Number.isInteger(s.paper.build) || s.paper.build <= 0) errs.push("paper.build must be an exact build number");
  if (!s.paper || !SHA256.test(String(s.paper.sha256 || ""))) errs.push("paper.sha256 must be a sha256 hex digest");
  const under = (p) => typeof p === "string" && p.startsWith(root.replace(/\/$/, "") + "/") && !p.split("/").includes("..");
  for (const [i, pl] of (s.plugins || []).entries()) {
    if (!under(pl.path) || !/\.jar$/.test(pl.path)) errs.push(`plugins[${i}].path must be a .jar under ${root}`);
    if (pl.sha256 != null && !SHA256.test(pl.sha256)) errs.push(`plugins[${i}].sha256 is not a sha256`);
  }
  for (const [i, d] of (s.datapacks || []).entries()) {
    if (!under(d.path)) errs.push(`datapacks[${i}].path must be under ${root}`);
    if (!/^[a-z0-9_.-]{1,64}$/.test(String(d.name || ""))) errs.push(`datapacks[${i}].name must be 1-64 chars of a-z 0-9 _ . -`);
  }
  for (const [i, c] of (s.rcon || []).entries()) {
    if (typeof c.command !== "string" || !c.command.trim() || c.command.length > 200 || /[\r\n]/.test(c.command)) errs.push(`rcon[${i}].command must be one line, 1-200 chars`);
    if (/^\/?(stop|restart|op|deop|reload)\b/i.test(String(c.command || "").trim())) errs.push(`rcon[${i}]: '${c.command}' is managed by the runner, not allowed in checks`);
    if (!Array.isArray(c.expect || [])) errs.push(`rcon[${i}].expect must be an array`);
    if (c.writeFile != null) errs.push(...serverFileErrors(c.writeFile, `rcon[${i}].writeFile`));
    if (c.waitMs != null && !(Number.isInteger(c.waitMs) && c.waitMs >= 0 && c.waitMs <= 30000)) errs.push(`rcon[${i}].waitMs must be 0-30000`);
  }
  if (s.world != null && (typeof s.world !== "object" || Object.keys(s.world).some((k) => k !== "generateStructures") || (s.world.generateStructures != null && typeof s.world.generateStructures !== "boolean"))) errs.push("world may only hold generateStructures (boolean)");
  if ((s.files || []).length > 16) errs.push("files: at most 16");
  for (const [i, f] of (s.files || []).entries()) errs.push(...serverFileErrors(f, `files[${i}]`));
  if ((s.seeds || []).length > MAX_SEEDS) errs.push(`seeds: at most ${MAX_SEEDS}`);
  for (const [i, sd] of (s.seeds || []).entries()) {
    if (!sd || !SEED_NAME_RE.test(String(sd.from || ""))) errs.push(`seeds[${i}].from must be a seed name (a-z 0-9 . _ -) under ${root}/seeds`);
    if (!sd || !SEED_TO_RE.test(String(sd.to || "")) || String(sd.to).split("/").includes("..")) errs.push(`seeds[${i}].to must be libraries or a path under plugins/`);
  }
  if ((s.collect || []).length > MAX_COLLECT) errs.push(`collect: at most ${MAX_COLLECT}`);
  for (const [i, c] of (s.collect || []).entries()) {
    if (typeof c !== "string" || !COLLECT_RE.test(c) || c.split("/").includes("..") || c.split("/").includes(".")) errs.push(`collect[${i}] must be a relative path of plain segments`);
  }
  for (const [k, list] of [["logMatchers", s.logMatchers], ["logIgnore", s.logIgnore]]) {
    if (list == null) continue;
    try { compileMatchers(list); } catch (e) { errs.push(`${k}: ${e.message}`); }
  }
  const t = s.timeouts || {};
  for (const [k, max] of [["bootSec", 600], ["stopSec", 120], ["rconSec", 60], ["totalSec", 900]]) {
    if (t[k] != null && !(Number.isFinite(t[k]) && t[k] > 0 && t[k] <= max)) errs.push(`timeouts.${k} must be 1-${max}`);
  }
  const m = s.memory || {};
  if (m.xmxMb != null && !(Number.isInteger(m.xmxMb) && m.xmxMb >= 256 && m.xmxMb <= 1024)) errs.push("memory.xmxMb must be 256-1024 (node-2 rule: at most -Xmx1g)");
  if (m.rssCapMb != null && !(Number.isInteger(m.rssCapMb) && m.rssCapMb >= 512 && m.rssCapMb <= 2048)) errs.push("memory.rssCapMb must be 512-2048");
  return errs;
}

/** Same rule as lib/cyrus/testflight/summary.ts: success only if every required check ran and passed. */
function overallOf(checks) {
  const req = checks.filter((c) => c.required);
  if (req.some((c) => c.status === "fail")) return "failed";
  if (req.some((c) => c.status !== "pass")) return "incomplete";
  return "passed";
}

/** Pick two distinct ports from the reserved range using a random source r() in [0,1). */
function pickPorts(r = Math.random) {
  const span = PORT_RANGE.max - PORT_RANGE.min + 1;
  const a = PORT_RANGE.min + Math.floor(r() * span);
  let b = PORT_RANGE.min + Math.floor(r() * span);
  if (b === a) b = a === PORT_RANGE.max ? PORT_RANGE.min : a + 1;
  return { port: a, rconPort: b };
}

/** Listening TCP ports from /proc/net/tcp{,6} text (state 0A). */
function listeningPorts(procNetTcp) {
  const out = new Set();
  for (const l of String(procNetTcp).split("\n").slice(1)) {
    const f = l.trim().split(/\s+/);
    if (f.length > 3 && f[3] === "0A") out.add(parseInt(f[1].split(":").pop(), 16));
  }
  return out;
}

module.exports = {
  SCHEMA, CHECK_IDS, STATUSES, PORT_RANGE, DEFAULT_LOG_MATCHERS, DEFAULT_LOG_IGNORES,
  compileMatchers, matchLog, matchLogDetailed, findDone, doneSeconds, stripColors, parsePluginYml, readZipEntry, pluginMeta,
  pluginLogStatus, parsePluginList, evalRcon, rconPacket, rconParse, serverProperties, validateResolvedSpec, SERVER_FILE_RE,
  SEED_NAME_RE, SEED_TO_RE, COLLECT_RE, MAX_SEEDS, MAX_COLLECT,
  overallOf, pickPorts, listeningPorts,
};

