"use strict";
// Cyrus playtest bots (R3): pure helpers shared by the Test Flight runner (runner.js), the bot process (bot.js) and
// the repo tests. No I/O, no network. Plain CommonJS so it runs as-is on node-2.
//
// A playtest is a list of SCENARIOS (one per acceptance test of the ModSpec, e.g. "T-2"), each a list of typed STEPS.
// The bot is a scripted Mineflayer client that joins the disposable Test Flight server (private netns, offline mode),
// performs the actions and checks the outcomes. There is no free-form code: only the step kinds below exist.
// Every step is pass / fail / not_run with evidence; a scenario passes only if every step ran and passed.

const crypto = require("crypto");

const PLAYTEST_SCHEMA = 1;
const STEP_KINDS = ["join", "command", "chat", "server", "wait", "hold", "use_item",
  "expect_chat", "expect_no_chat", "expect_inventory", "expect_no_item", "expect_effect", "expect_title", "expect_moved"];
const ACTION_KINDS = new Set(["command", "chat", "server", "hold", "use_item"]);
/** Commands neither the bot nor a `server` step may send: they belong to the runner (or would end the test). */
const RESERVED_RE = /^\/?(stop|restart|reload|op|deop|kick|ban|ban-ip|pardon|pardon-ip|whitelist|save-off|save-all|minecraft:(stop|reload|op|deop|kick|ban))\b/i;
const USERNAME_RE = /^[A-Za-z0-9_]{3,16}$/;
const ID_RE = /^[a-z0-9_:./-]{1,64}$/;
const SCENARIO_ID_RE = /^T-[1-9][0-9]{0,3}$/;
const REQ_RE = /^REQ-[1-9][0-9]{0,3}$/;
const LIMITS = { scenarios: 16, steps: 24, text: 200, contains: 6, withinMsMax: 15000, waitMsMax: 10000, totalSecMax: 180, joinSecMax: 60 };
const DEFAULTS = { username: "NxPlaytest", withinMs: 3000, forMs: 1500, totalSec: 90, joinSec: 30 };

const isStr = (s, max = LIMITS.text) => typeof s === "string" && s.trim().length > 0 && s.length <= max && !/[\r\n\u0000]/.test(s);
const intIn = (v, lo, hi) => Number.isInteger(v) && v >= lo && v <= hi;

function stepErrors(st, key) {
  const e = [];
  if (!st || typeof st !== "object" || !STEP_KINDS.includes(st.kind)) return [`${key}.kind must be one of ${STEP_KINDS.join(", ")}`];
  const strList = (v, k) => {
    if (!Array.isArray(v) || !v.length || v.length > LIMITS.contains || !v.every((s) => isStr(s))) e.push(`${key}.${k} must be 1-${LIMITS.contains} strings of 1-${LIMITS.text} chars`);
  };
  const within = (k) => { if (st[k] != null && !intIn(st[k], 100, LIMITS.withinMsMax)) e.push(`${key}.${k} must be 100-${LIMITS.withinMsMax} ms`); };
  switch (st.kind) {
    case "command":
      if (!isStr(st.text) || !st.text.startsWith("/")) e.push(`${key}.text must be one line starting with /`);
      else if (RESERVED_RE.test(st.text.trim())) e.push(`${key}: '${st.text}' is reserved (never sent by a playtest)`);
      break;
    case "chat":
      if (!isStr(st.text) || st.text.startsWith("/")) e.push(`${key}.text must be one line of chat (commands use kind "command")`);
      break;
    case "server":
      if (!isStr(st.command)) e.push(`${key}.command must be one line of 1-${LIMITS.text} chars`);
      else if (RESERVED_RE.test(st.command.trim())) e.push(`${key}: '${st.command}' is reserved (never sent by a playtest)`);
      if (st.expect != null) strList(st.expect, "expect");
      break;
    case "wait":
      if (!intIn(st.ms, 1, LIMITS.waitMsMax)) e.push(`${key}.ms must be 1-${LIMITS.waitMsMax}`);
      break;
    case "hold":
      if (!isStr(st.item, 64) || !ID_RE.test(st.item)) e.push(`${key}.item must be an item id (e.g. diamond or minecraft:diamond)`);
      break;
    case "expect_chat":
      strList(st.contains, "contains"); within("withinMs");
      break;
    case "expect_no_chat":
      strList(st.contains, "contains"); within("forMs");
      break;
    case "expect_inventory":
      if (!isStr(st.item, 64) || !ID_RE.test(st.item)) e.push(`${key}.item must be an item id`);
      if (st.count != null && !intIn(st.count, 1, 6400)) e.push(`${key}.count must be 1-6400`);
      if (st.name != null && !isStr(st.name, 100)) e.push(`${key}.name must be 1-100 chars`);
      within("withinMs");
      break;
    case "expect_no_item":
      if (!isStr(st.item, 64) || !ID_RE.test(st.item)) e.push(`${key}.item must be an item id`);
      within("forMs");
      break;
    case "expect_effect":
      if (!isStr(st.effect, 64) || !ID_RE.test(st.effect)) e.push(`${key}.effect must be an effect id (e.g. speed)`);
      within("withinMs");
      break;
    case "expect_title":
      strList(st.contains, "contains"); within("withinMs");
      break;
    case "expect_moved":
      if (st.minBlocks != null && !(typeof st.minBlocks === "number" && st.minBlocks > 0 && st.minBlocks <= 256)) e.push(`${key}.minBlocks must be >0 and <=256`);
      within("withinMs");
      break;
    default: break;
  }
  const allowed = { join: [], command: ["text"], chat: ["text"], server: ["command", "expect"], wait: ["ms"], hold: ["item"], use_item: [],
    expect_chat: ["contains", "withinMs"], expect_no_chat: ["contains", "forMs"], expect_inventory: ["item", "count", "name", "withinMs"],
    expect_no_item: ["item", "forMs"], expect_effect: ["effect", "withinMs"], expect_title: ["contains", "withinMs"], expect_moved: ["minBlocks", "withinMs"] }[st.kind];
  for (const k of Object.keys(st)) if (k !== "kind" && k !== "note" && !allowed.includes(k)) e.push(`${key}: unknown field ${k} for ${st.kind}`);
  if (st.note != null && !isStr(st.note, 300)) e.push(`${key}.note must be 1-300 chars`);
  return e;
}

/** Validate a playtest plan (same rules as lib/cyrus/playtest/plan.ts). Returns a list of problems (empty = ok). */
function validatePlaytest(pt) {
  const e = [];
  if (!pt || typeof pt !== "object" || Array.isArray(pt)) return ["playtest must be an object"];
  if (pt.schema !== PLAYTEST_SCHEMA) e.push(`playtest.schema must be ${PLAYTEST_SCHEMA}`);
  if (pt.username != null && !USERNAME_RE.test(String(pt.username))) e.push("playtest.username must be 3-16 chars of A-Z a-z 0-9 _");
  if (pt.op != null && typeof pt.op !== "boolean") e.push("playtest.op must be a boolean");
  if (pt.totalSec != null && !intIn(pt.totalSec, 10, LIMITS.totalSecMax)) e.push(`playtest.totalSec must be 10-${LIMITS.totalSecMax}`);
  if (pt.joinSec != null && !intIn(pt.joinSec, 5, LIMITS.joinSecMax)) e.push(`playtest.joinSec must be 5-${LIMITS.joinSecMax}`);
  if (!Array.isArray(pt.scenarios) || !pt.scenarios.length || pt.scenarios.length > LIMITS.scenarios) { e.push(`playtest.scenarios must hold 1-${LIMITS.scenarios} scenarios`); return e; }
  const seen = new Set();
  for (const [i, sc] of pt.scenarios.entries()) {
    const k = `playtest.scenarios[${i}]`;
    if (!sc || typeof sc !== "object") { e.push(`${k} must be an object`); continue; }
    if (!SCENARIO_ID_RE.test(String(sc.id || ""))) e.push(`${k}.id must be a test id (T-1, T-2, ...)`);
    if (seen.has(sc.id)) e.push(`${k}.id ${sc.id} is listed twice`);
    seen.add(sc.id);
    if (sc.title != null && !isStr(sc.title, 500)) e.push(`${k}.title must be 1-500 chars`);
    if (sc.covers != null && (!Array.isArray(sc.covers) || sc.covers.length > 50 || !sc.covers.every((r) => REQ_RE.test(String(r))))) e.push(`${k}.covers must be requirement ids (REQ-n)`);
    if (sc.reset != null && typeof sc.reset !== "boolean") e.push(`${k}.reset must be a boolean`);
    if (!Array.isArray(sc.steps) || !sc.steps.length || sc.steps.length > LIMITS.steps) { e.push(`${k}.steps must hold 1-${LIMITS.steps} steps`); continue; }
    for (const [j, st] of sc.steps.entries()) e.push(...stepErrors(st, `${k}.steps[${j}]`));
    sc.steps.forEach((st, j) => { if (st && st.kind === "join" && j !== 0) e.push(`${k}.steps[${j}]: join must be the first step`); });
    if (!sc.steps.some((st) => st && String(st.kind).startsWith("expect_")) && !sc.steps.some((st) => st && st.kind === "server" && st.expect)) e.push(`${k}: a scenario needs at least one expect_* step (otherwise it proves nothing)`);
  }
  return e;
}

/** Minecraft's offline-mode UUID (UUID.nameUUIDFromBytes("OfflinePlayer:" + name)), for ops.json. */
function offlineUuid(name) {
  const b = crypto.createHash("md5").update(`OfflinePlayer:${name}`, "utf8").digest();
  b[6] = (b[6] & 0x0f) | 0x30;
  b[8] = (b[8] & 0x3f) | 0x80;
  const h = b.toString("hex");
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
}

/** `{bot}` in a server command becomes the bot's username. */
const expandBot = (s, name) => String(s).replace(/\{bot\}/g, name);

/** "minecraft:diamond" -> "diamond"; lower-case. */
const bareId = (id) => String(id).toLowerCase().replace(/^minecraft:/, "");
/** Effect names compare without case, underscores or the namespace: "mining_fatigue" == "MiningFatigue". */
const normEffect = (s) => bareId(s).replace(/[_\s]/g, "");

const stripColors = (s) => String(s).replace(/\u00a7[0-9a-fk-orx]/gi, "");

/** Flatten a chat component (JSON string, object, or plain string) to its visible text. */
function chatText(v, depth = 0) {
  if (v == null || depth > 20) return "";
  if (typeof v === "string") {
    const t = v.trim();
    if ((t.startsWith("{") && t.endsWith("}")) || (t.startsWith("[") && t.endsWith("]")) || (t.startsWith('"') && t.endsWith('"'))) {
      try { return chatText(JSON.parse(t), depth + 1); } catch { /* plain text that looks like JSON */ }
    }
    return stripColors(v);
  }
  if (Array.isArray(v)) return v.map((x) => chatText(x, depth + 1)).join("");
  if (typeof v === "object") {
    if (typeof v.toString === "function" && v.toString !== Object.prototype.toString && !("text" in v) && !("extra" in v) && !("translate" in v)) {
      try { return stripColors(String(v.toString())); } catch { /* fall through */ }
    }
    let s = "";
    if (typeof v.text === "string" || typeof v.text === "number") s += String(v.text);
    else if (v.text && typeof v.text === "object") s += chatText(v.text, depth + 1);
    if (v[""] != null) s += chatText(v[""], depth + 1);
    if (typeof v.translate === "string" && !s) s += v.translate;
    if (Array.isArray(v.with)) s += v.with.map((x) => chatText(x, depth + 1)).join(" ");
    if (v.extra) s += chatText(v.extra, depth + 1);
    if (v.value != null && typeof v.type === "string") s += chatText(v.value, depth + 1); // prismarine-nbt shape
    return stripColors(s);
  }
  return String(v);
}

/** Which of `want` appear (case-sensitive substring, colours stripped) in the joined messages. */
function containsAll(messages, want) {
  const hay = messages.map((m) => stripColors(m)).join("\n");
  const missing = want.filter((w) => !hay.includes(w));
  return { ok: missing.length === 0, missing };
}
function containsAny(messages, banned) {
  const hay = messages.map((m) => stripColors(m)).join("\n");
  const found = banned.filter((w) => hay.includes(w));
  return { ok: found.length === 0, found };
}

/**
 * Does the inventory satisfy an expect_inventory step? `items` = [{ name, count, customName }] (customName is any
 * chat-ish value). count = at least this many in total; name = substring of the visible custom name.
 */
function inventoryMatch(items, step) {
  const id = bareId(step.item);
  const same = items.filter((it) => bareId(it.name) === id);
  const named = step.name != null ? same.filter((it) => chatText(it.customName).includes(step.name)) : same;
  const total = named.reduce((a, it) => a + (Number(it.count) || 0), 0);
  const want = step.count || 1;
  return { ok: total >= want, total, sameId: same.reduce((a, it) => a + (Number(it.count) || 0), 0), want };
}

/** Short inventory listing for evidence lines. */
function describeInventory(items) {
  if (!items.length) return "empty";
  return items.slice(0, 12).map((it) => `${it.count}x ${bareId(it.name)}${it.customName ? ` "${chatText(it.customName).slice(0, 40)}"` : ""}`).join(", ");
}

/** Scenario verdict: pass only if every step ran and passed. */
function scenarioStatus(steps) {
  if (steps.some((s) => s.status === "fail")) return "fail";
  if (!steps.length || steps.some((s) => s.status !== "pass")) return "not_run";
  return "pass";
}

/** Check verdict for the runner: pass only if the bot joined and every scenario passed. */
function playtestCheckStatus(result) {
  if (!result || !result.joined) return result && result.joinFailed ? "fail" : "not_run";
  const sc = result.scenarios || [];
  if (!sc.length) return "not_run";
  if (sc.some((s) => s.status === "fail")) return "fail";
  if (sc.some((s) => s.status !== "pass")) return "not_run";
  return "pass";
}

module.exports = {
  PLAYTEST_SCHEMA, STEP_KINDS, ACTION_KINDS, RESERVED_RE, LIMITS, DEFAULTS, USERNAME_RE,
  validatePlaytest, stepErrors, offlineUuid, expandBot, bareId, normEffect, chatText, stripColors,
  containsAll, containsAny, inventoryMatch, describeInventory, scenarioStatus, playtestCheckStatus,
};

