// Cyrus playtest bots (R3): turn a ModSpec's ACCEPTANCE TESTS into a playtest plan. Deterministic, no model call.
// Pure + client-safe.
//
// Source of each scenario, in order:
//   1. an explicit script for the test id (`opts.scripts["T-2"]`, typed steps, e.g. written by the AI author or a
//      designer and validated here) -> "explicit";
//   2. the test's description compiled with the CRITERIA GRAMMAR below -> "scripted";
//   3. otherwise the test is reported "not_scriptable" with the reason. It is never silently dropped or claimed.
// Only `functional` tests become scenarios. `manual` tests stay manual; compile/scan/boot tests are proven by the
// build, the scanner and the Test Flight boot (not by the bot) and are reported as such.
//
// CRITERIA GRAMMAR (what a test description may say; quotes may be "straight" or "curly"):
//   triggers  : `when a player joins` / `on join`            -> join (messages since the bot joined)
//               running `/cmd args` (backticks; or bare /cmd without args) -> the bot player runs the command
//               the console runs `cmd`                         -> console command over RCON
//               holding `item_id` ... right-click(ing)         -> hold the item, then use it
//               after 2 seconds / waits 500 ms                 -> wait
//   outcomes  : says / replies / sees / sends / shows / tells / message "text"  -> expect_chat
//               never / not / no ... "text"                    -> expect_no_chat
//               title "text"                                   -> expect_title
//               gives / receives / has [N | a] `item` | N item [named "Name"]   -> expect_inventory
//               never / not ... gives [N | a] `item`           -> expect_no_item
//               the `speed` effect / the speed effect          -> expect_effect
//               teleports / moves / launches [N blocks]        -> expect_moved
import type { ModSpec, TestPlan } from "../engine-core/spec";
import { PLAYTEST_SCHEMA, validatePlaytestPlan, stepErrors, type PlaytestPlan, type PlaytestScenario, type PlaytestStep } from "./plan";

export type CoverageStatus = "explicit" | "scripted" | "not_scriptable" | "manual" | "other_check";
export type TestCoverage = {
  testId: string;
  kind: TestPlan["kind"];
  covers: string[];
  status: CoverageStatus;
  /** Why it is not a scenario (not_scriptable / manual / other_check), or what the compiler could not use. */
  reason?: string;
  steps?: number;
};

export type GenerateOptions = {
  /** Explicit steps per test id; they win over the compiled description. */
  scripts?: Record<string, PlaytestStep[]>;
  /** Force the bot's operator status (default: on when a description says "as an operator" / "as op"). */
  op?: boolean;
  username?: string;
  totalSec?: number;
};

export type GenerateResult = { plan: PlaytestPlan | null; coverage: TestCoverage[]; problems: string[] };

type Hit = { at: number; end: number; step: PlaytestStep; action: boolean };

const ACTION = new Set(["join", "command", "chat", "server", "wait", "hold", "use_item"]);
const NOT_ITEMS = new Set(["the", "a", "an", "effect", "message", "title", "item", "items", "player", "them", "you", "it", "chat", "reply", "speed"]);
const NEG_BEFORE = /(?:\bnever|\bnot|\bno longer|\bdoesn't|\bdoes not|\bwithout|\bno)\s+(?:\w+\s+){0,3}$/i;

function normalise(s: string): string {
  return s.replace(/[\u201c\u201d\u201e\u00ab\u00bb]/g, '"').replace(/[\u2018\u2019]/g, "'").replace(/\s+/g, " ").trim();
}

/** Compile one test description into steps (textual order, actions before the outcomes they cause). */
export function compileCriterion(description: string): { steps: PlaytestStep[]; problems: string[]; op: boolean } {
  const text = normalise(description);
  const hits: Hit[] = [];
  const claimed: [number, number][] = [];
  const free = (a: number, b: number) => !claimed.some(([x, y]) => a < y && b > x);
  const claim = (a: number, b: number) => claimed.push([a, b]);
  const all = (re: RegExp, fn: (m: RegExpExecArray) => void) => { for (const m of text.matchAll(re)) fn(m as RegExpExecArray); };
  const problems: string[] = [];
  const op = /\bas (?:an? )?(?:op|operator|admin)\b/i.test(text);

  // triggers
  all(/\b(?:when|after|once|as soon as) (?:a|the) player joins\b|\bon join\b/gi, (m) => { hits.push({ at: m.index, end: m.index + m[0].length, step: { kind: "join" }, action: true }); claim(m.index, m.index + m[0].length); });
  all(/\b(?:the )?(?:console|server) runs? `\/?([^`]{1,200})`/gi, (m) => { hits.push({ at: m.index, end: m.index + m[0].length, step: { kind: "server", command: m[1].trim() }, action: true }); claim(m.index, m.index + m[0].length); });
  all(/`(\/[^`]{1,199})`/g, (m) => { if (!free(m.index, m.index + m[0].length)) return; hits.push({ at: m.index, end: m.index + m[0].length, step: { kind: "command", text: m[1].trim() }, action: true }); claim(m.index, m.index + m[0].length); });
  all(/\b(?:running|runs?|typing|types?|executing|executes?|using|uses?) (\/[a-z0-9_:-]{1,40})(?![\w/`])/gi, (m) => {
    const at = m.index + m[0].indexOf(m[1]);
    if (!free(at, at + m[1].length)) return;
    hits.push({ at, end: at + m[1].length, step: { kind: "command", text: m[1] }, action: true }); claim(at, at + m[1].length);
  });
  all(/\bholding (?:a |an |the )?`([a-z0-9_:]{1,64})`/gi, (m) => { hits.push({ at: m.index, end: m.index + m[0].length, step: { kind: "hold", item: m[1].toLowerCase() }, action: true }); claim(m.index, m.index + m[0].length); });
  all(/\bright[- ]?click(?:s|ing|ed)?\b/gi, (m) => { hits.push({ at: m.index, end: m.index + m[0].length, step: { kind: "use_item" }, action: true }); claim(m.index, m.index + m[0].length); });
  all(/\b(?:waits?|waiting|after) (\d+(?:\.\d+)?) ?(ms|milliseconds?|s|secs?|seconds?)\b/gi, (m) => {
    const ms = Math.round(Number(m[1]) * (/^m/i.test(m[2]) ? 1 : 1000));
    hits.push({ at: m.index, end: m.index + m[0].length, step: { kind: "wait", ms: Math.min(Math.max(ms, 1), 10000) }, action: true }); claim(m.index, m.index + m[0].length);
  });

  // outcomes that own a quoted string (inventory name, title) before plain chat
  all(/\b(?:gives?|giving|receives?|gets?|has|have|ends? up with|obtains?)\s+(?:the player |them |you |a player |him |her )?(?:(\d{1,4}) |an? )?(?:`([a-z0-9_:]{1,64})`|([a-z][a-z_]{1,40}(?::[a-z_]{1,40})?))(?: (?:named|called) "([^"]{1,100})")?/gi, (m) => {
    const id = (m[2] ?? m[3] ?? "").toLowerCase();
    if (!m[2] && (!m[1] && !/ an? $/i.test(m[0].slice(0, m[0].indexOf(m[3]))) || NOT_ITEMS.has(id))) return; // a bare word needs a count or "a"
    if (!m[2] && /^\s*effect\b/i.test(text.slice(m.index + m[0].length))) return; // "gives a speed effect" is an effect
    const end = m.index + m[0].length;
    if (!free(m.index, end)) return;
    const neg = NEG_BEFORE.test(text.slice(Math.max(0, m.index - 40), m.index));
    const step: PlaytestStep = neg ? { kind: "expect_no_item", item: id }
      : { kind: "expect_inventory", item: id, ...(m[1] ? { count: Number(m[1]) } : {}), ...(m[4] ? { name: m[4] } : {}) };
    hits.push({ at: m.index, end, step, action: false }); claim(m.index, end);
  });
  all(/\btitle\b[^".]{0,40}?"([^"]{1,200})"/gi, (m) => { const end = m.index + m[0].length; if (!free(end - m[1].length - 2, end)) return; hits.push({ at: m.index, end, step: { kind: "expect_title", contains: [m[1]] }, action: false }); claim(end - m[1].length - 2, end); });
  all(/\b(?:never|not|no|doesn't|does not|without)\b[^".]{0,60}?"([^"]{1,200})"/gi, (m) => { const end = m.index + m[0].length; if (!free(end - m[1].length - 2, end)) return; hits.push({ at: m.index, end, step: { kind: "expect_no_chat", contains: [m[1]] }, action: false }); claim(end - m[1].length - 2, end); });
  all(/\b(?:says?|saying|repl(?:y|ies|ied)|responds?|sends?|sees?|shows?|tells?|messages?|chat|prints?|answers?)\b[^".]{0,60}?"([^"]{1,200})"/gi, (m) => { const end = m.index + m[0].length; if (!free(end - m[1].length - 2, end)) return; hits.push({ at: m.index, end, step: { kind: "expect_chat", contains: [m[1]] }, action: false }); claim(end - m[1].length - 2, end); });
  all(/(?:\bthe |\ban? )?(?:`([a-z0-9_:]{1,64})`|\b([a-z]+(?:_[a-z]+)*)) effect\b/gi, (m) => {
    const id = (m[1] ?? m[2]).toLowerCase();
    if (NOT_ITEMS.has(id) && id !== "speed") return;
    if (NEG_BEFORE.test(text.slice(Math.max(0, m.index - 40), m.index))) { problems.push(`"no ${id} effect" cannot be checked (only effects that ARE given)`); return; }
    hits.push({ at: m.index, end: m.index + m[0].length, step: { kind: "expect_effect", effect: id }, action: false });
  });
  all(/\b(?:teleports?|teleporting|moves?|launch(?:es)?|pushes|knocks? (?:back|away))\b(?:[^.]{0,40}?(\d+(?:\.\d+)?) blocks?)?/gi, (m) => {
    hits.push({ at: m.index, end: m.index + m[0].length, step: { kind: "expect_moved", ...(m[1] ? { minBlocks: Number(m[1]) } : {}) }, action: false });
  });

  // Quoted strings nothing claimed are reported (never silently treated as a check).
  all(/"([^"]{1,200})"/g, (m) => { if (free(m.index, m.index + m[0].length)) problems.push(`quoted text "${m[1]}" is not tied to a checkable outcome (say/reply/title/named/never)`); });

  hits.sort((a, b) => a.at - b.at || (a.action === b.action ? 0 : a.action ? -1 : 1));
  // Expectations written before the first action ("The player sees "x" after running `/y`") move behind it.
  const firstAction = hits.findIndex((h) => h.action);
  let ordered = hits;
  if (firstAction > 0) {
    const lead = hits.slice(0, firstAction);
    let k = firstAction;
    while (k < hits.length && hits[k].action) k++;
    ordered = [...hits.slice(firstAction, k), ...lead, ...hits.slice(k)];
  }
  const steps = ordered.map((h) => h.step);
  const joinAt = steps.findIndex((s) => s.kind === "join");
  if (joinAt > 0) steps.unshift(...steps.splice(joinAt, 1));
  const dedup = steps.filter((s, i) => !(s.kind === "join" && i > 0));
  return { steps: dedup, problems, op };
}

/** ModSpec (+ optional explicit scripts) -> playtest plan + honest per-test coverage. */
export function planFromSpec(spec: ModSpec, opts: GenerateOptions = {}): GenerateResult {
  const coverage: TestCoverage[] = [];
  const scenarios: PlaytestScenario[] = [];
  const problems: string[] = [];
  let op = false;
  for (const t of spec.tests) {
    const base = { testId: t.id, kind: t.kind, covers: [...t.covers] };
    if (t.kind === "manual") { coverage.push({ ...base, status: "manual", reason: "manual test: a person checks it; the bot never claims it" }); continue; }
    if (t.kind !== "functional") { coverage.push({ ...base, status: "other_check", reason: `${t.kind} is proven by the ${t.kind === "boot" ? "Test Flight boot" : t.kind === "scan" ? "scanner" : "build"}, not by the bot` }); continue; }
    const explicit = opts.scripts?.[t.id];
    if (explicit) {
      const errs = explicit.flatMap((st, j) => stepErrors(st, `scripts.${t.id}[${j}]`));
      if (errs.length) { coverage.push({ ...base, status: "not_scriptable", reason: `explicit script invalid: ${errs.slice(0, 3).join("; ")}` }); problems.push(...errs); continue; }
      scenarios.push({ id: t.id, title: t.description.slice(0, 500), covers: [...t.covers], steps: explicit });
      coverage.push({ ...base, status: "explicit", steps: explicit.length });
      continue;
    }
    const c = compileCriterion(t.description);
    const hasAction = c.steps.some((s) => ACTION.has(s.kind));
    const hasExpect = c.steps.some((s) => s.kind.startsWith("expect_"));
    if (!hasAction || !hasExpect) {
      coverage.push({ ...base, status: "not_scriptable", reason: !hasAction ? "no trigger found (write: running `/cmd`, when a player joins, the console runs `cmd`, holding `item` and right-clicking)" : "no checkable outcome found (write: says \"text\", gives 1 `item`, the `speed` effect, title \"text\", teleports N blocks)", ...(c.problems.length ? {} : {}) });
      continue;
    }
    if (c.steps.length > 24) { coverage.push({ ...base, status: "not_scriptable", reason: "more than 24 steps; split the test" }); continue; }
    op = op || c.op;
    scenarios.push({ id: t.id, title: t.description.slice(0, 500), covers: [...t.covers], steps: c.steps });
    coverage.push({ ...base, status: "scripted", steps: c.steps.length, ...(c.problems.length ? { reason: c.problems.join("; ") } : {}) });
  }
  if (!scenarios.length) return { plan: null, coverage, problems };
  const plan: PlaytestPlan = {
    schema: PLAYTEST_SCHEMA,
    ...(opts.username ? { username: opts.username } : {}),
    op: opts.op ?? op,
    ...(opts.totalSec ? { totalSec: opts.totalSec } : {}),
    scenarios: scenarios.slice(0, 16),
  };
  if (scenarios.length > 16) problems.push(`only the first 16 of ${scenarios.length} scenarios fit in one playtest`);
  const errs = validatePlaytestPlan(plan);
  if (errs.length) {
    // Drop just the scenarios that fail validation (e.g. a compiled reserved command) and say so.
    const bad = new Set(errs.map((e) => /scenarios\[(\d+)\]/.exec(e)?.[1]).filter((x): x is string => x != null).map(Number));
    const keep = plan.scenarios.filter((_, i) => !bad.has(i));
    for (const i of bad) {
      const id = plan.scenarios[i]?.id;
      const cv = coverage.find((c) => c.testId === id);
      if (cv) { cv.status = "not_scriptable"; cv.reason = errs.filter((e) => e.includes(`scenarios[${i}]`)).slice(0, 2).join("; "); delete cv.steps; }
    }
    problems.push(...errs);
    if (!keep.length) return { plan: null, coverage, problems };
    plan.scenarios = keep;
  }
  return { plan, coverage, problems };
}

