    assert.deepEqual(compileCriterion("The player sees \"Hi\" after running `/hi`.").steps, [{ kind: "command", text: "/hi" }, { kind: "expect_chat", contains: ["Hi"] }], "expectations move behind the action");
  });
  it("explicit scripts win, and an invalid explicit script is reported, not run", () => {
    const spec = loadSpec();
    const ok = planFromSpec(spec, { scripts: { "T-4": [{ kind: "command", text: "/tfup" }, { kind: "expect_moved", minBlocks: 7 }] } });
    assert.equal(ok.coverage.find((c) => c.testId === "T-4")!.status, "explicit");
    assert.deepEqual(ok.plan!.scenarios.find((s) => s.id === "T-4")!.steps[1], { kind: "expect_moved", minBlocks: 7 });
    const bad = planFromSpec(spec, { scripts: { "T-4": [{ kind: "command", text: "/stop" }, { kind: "expect_moved" }] } });
    const c = bad.coverage.find((x) => x.testId === "T-4")!;
    assert.equal(c.status, "not_scriptable");
    assert.match(c.reason!, /reserved/);
    assert.ok(!bad.plan!.scenarios.some((s) => s.id === "T-4"));
  });
  it("a compiled reserved command drops only that scenario", () => {
    const spec = { ...loadSpec(), tests: [
      { id: "T-1", kind: "functional" as const, description: "Running `/op NxPlaytest` says \"Made\".", covers: ["REQ-1"] },
      { id: "T-2", kind: "functional" as const, description: "Running `/tfup` teleports the player 5 blocks.", covers: ["REQ-4"] },
    ] };
    const g = planFromSpec(spec);
    assert.deepEqual(g.plan!.scenarios.map((s) => s.id), ["T-2"]);
    assert.equal(g.coverage[0].status, "not_scriptable");
  });
});

describe("plan validation (TS == runner JS)", () => {
  const good: PlaytestPlan = { schema: 1, scenarios: [{ id: "T-1", steps: [{ kind: "command", text: "/a" }, { kind: "expect_chat", contains: ["x"] }] }] };
  const bad: unknown[] = [
    null, { schema: 2, scenarios: good.scenarios }, { schema: 1, scenarios: [] },
    { schema: 1, scenarios: [{ id: "X-1", steps: good.scenarios[0].steps }] },
    { schema: 1, scenarios: [{ id: "T-1", steps: [{ kind: "command", text: "/a" }] }] }, // proves nothing
    { schema: 1, scenarios: [{ id: "T-1", steps: [{ kind: "command", text: "/stop" }, { kind: "expect_chat", contains: ["x"] }] }] },
    { schema: 1, scenarios: [{ id: "T-1", steps: [{ kind: "server", command: "minecraft:op x" }, { kind: "expect_chat", contains: ["x"] }] }] },
    { schema: 1, scenarios: [{ id: "T-1", steps: [{ kind: "expect_chat", contains: ["x"] }, { kind: "join" }] }] },
    { schema: 1, scenarios: [{ id: "T-1", steps: [{ kind: "command", text: "/a", evil: 1 }, { kind: "expect_chat", contains: ["x"] }] }] },
    { schema: 1, scenarios: [{ id: "T-1", steps: [{ kind: "command", text: "/a\nstop" }, { kind: "expect_chat", contains: ["x"] }] }] },
    { schema: 1, scenarios: [{ id: "T-1", steps: [{ kind: "wait", ms: 60000 }, { kind: "expect_chat", contains: ["x"] }] }] },
    { schema: 1, scenarios: [{ id: "T-1", steps: [{ kind: "eval", code: "x" }] }] },
    { schema: 1, username: "a b", scenarios: good.scenarios },
    { schema: 1, scenarios: [good.scenarios[0], good.scenarios[0]] },
  ];
  it("both validators accept a good plan and refuse each bad one", () => {
    assert.deepEqual(validatePlaytestPlan(good), []);
    assert.deepEqual(PT.validatePlaytest(good), []);
    for (const b of bad) {
      const ts = validatePlaytestPlan(b), js = PT.validatePlaytest(b);
      assert.ok(ts.length > 0, `TS accepted ${JSON.stringify(b)}`);
      assert.deepEqual(js, ts, `TS and JS disagree on ${JSON.stringify(b)}`);
    }
  });
  it("Test Flight spec: a playtest makes the check required, is refused on unverified versions, resolves through", () => {
    const spec = { version: "1.21.11", plugins: [{ remotePath: "/tank/nxeon-build/tmp/testflight/inbox/fx/A.jar" }], playtest: good };
    assert.equal(validateSpec(spec).ok, true);
    assert.ok(requiredStages(spec).has("playtest"));
    assert.ok(!requiredStages({ version: "1.21.11" }).has("playtest"));
    const r = resolveSpec(spec, { runId: "tf-pt-0001" });
    assert.deepEqual(r.playtest, good);
    assert.deepEqual(L.validateResolvedSpec(r, "/tank/nxeon-build/tmp/testflight"), []);
    const v = validateSpec({ ...spec, version: "26.2" });
    assert.equal(v.ok, false);
    assert.match((v as { errors: string[] }).errors.join(" "), /no verified playtest bot for Minecraft 26.2/);
    assert.equal(playtestVersion("1.21.11").ok, true);
    assert.deepEqual([...PLAYTEST_BOT_VERSIONS], PT.BOT_VERSIONS, "TS and runner agree on the bot versions");
    assert.ok(L.validateResolvedSpec({ ...r, playtest: { schema: 1, scenarios: [] } }, "/tank/nxeon-build/tmp/testflight").length > 0);
    assert.deepEqual([...CHECK_IDS], L.CHECK_IDS, "TS and runner agree on the check list");
  });
  it("withPlaytest raises the flight time budget to fit the bot", () => {
    assert.equal(withPlaytest({ version: "1.21.11" }, good).timeouts!.totalSec, 420);
    assert.equal(withPlaytest({ version: "1.21.11" }, { ...good, totalSec: 180, joinSec: 60 }).timeouts!.totalSec, 540);
  });
});

// ---- verdicts ----
const checks = (over: Record<string, Partial<CheckResult>> = {}): CheckResult[] =>
  CHECK_IDS.map((id) => ({ id, status: "pass", required: true, evidence: [`${id} ok`], durationMs: 1, ...(over[id] ?? {}) }) as CheckResult);
const run = (scs: PlaytestRunResult["scenarios"], over: Partial<PlaytestRunResult> = {}): PlaytestRunResult => ({
  schema: 1, username: "NxPlaytest", version: "1.21.11", joined: true, joinFailed: false, joinMs: 900, op: false,
  bot: { mineflayer: "4.39.0", minecraftProtocol: "1.68.0", lockSha256: "x" }, scenarios: scs, notes: [], disconnect: null, ...over,
});
const sc = (id: string, status: "pass" | "fail" | "not_run", covers: string[], stepStatus = status): PlaytestRunResult["scenarios"][number] =>
  ({ id, title: null, covers, status, ms: 10, steps: [{ i: 0, kind: "command", status: "pass", evidence: ["sent"], ms: 1 }, { i: 1, kind: "expect_chat", status: stepStatus, evidence: stepStatus === "pass" ? ["saw"] : ["missing [\"x\"]"], ms: 1 }] });
const rep = (pt: PlaytestRunResult | undefined, over: Partial<TestFlightReport> = {}): TestFlightReport => ({
  schema: 1, runId: "tf-x", status: "completed", version: "1.21.11", javaRelease: 21, startedAt: "", finishedAt: "", checks: checks(), timings: {},
  bootMs: 1, doneReportedSec: 1, peakRssKb: 1, artifacts: [], engine: null, notes: [], overall: "passed", ...(pt ? { playtest: pt } : {}), ...over,
});

describe("verdict (never claims more than ran)", () => {
  const spec = loadSpec();
  const g = planFromSpec(spec);
  it("all scenarios passed -> passed, requirement table, boot/manual kept apart", () => {
    const v = playtestVerdict(g.plan!, rep(run(g.plan!.scenarios.map((s) => sc(s.id, "pass", s.covers ?? [])))), g.coverage);
    assert.equal(v.verdict, "passed");
    assert.equal(v.label, "Playtested on Paper 1.21.11: 6 of 6 acceptance checks passed");
    assert.deepEqual(v.requirements.map((r) => [r.id, r.status]), [["REQ-1", "passed"], ["REQ-2", "passed"], ["REQ-3", "passed"], ["REQ-4", "passed"], ["REQ-5", "other_check"], ["REQ-6", "manual"]]);
  });
  it("one failing scenario fails its requirement even when other scenarios covering it passed", () => {
    const v = playtestVerdict(g.plan!, rep(run(g.plan!.scenarios.map((s) => sc(s.id, s.id === "T-2" ? "fail" : "pass", s.covers ?? [])))), g.coverage);
    assert.equal(v.verdict, "failed");
    assert.equal(v.requirements.find((r) => r.id === "REQ-2")!.status, "failed");
    assert.match(v.scenarios.find((s) => s.id === "T-2")!.reason!, /step 2 \(expect_chat\)/);
    assert.match(v.label, /5 of 6 acceptance checks passed, 1 failed/);
  });
  it("a pass without evidence, a missing scenario, a bot that never joined and a busy runner are never passes", () => {
    const noEv = run([{ ...sc("T-1", "pass", ["REQ-1"]), steps: [{ i: 0, kind: "join", status: "pass", evidence: [], ms: 0 }] }]);
    const v1 = playtestVerdict(g.plan!, rep(noEv));
    assert.equal(v1.scenarios.find((s) => s.id === "T-1")!.status, "not_run");
    assert.equal(v1.verdict, "incomplete");
    const v2 = playtestVerdict(g.plan!, rep(run([], { joined: false, notes: ["bot did not spawn within 30000 ms"] })));
    assert.equal(v2.verdict, "not_run");
    assert.equal(v2.label, "Playtest not run");
    const v3 = playtestVerdict(g.plan!, rep(run([], { joined: false, joinFailed: true, disconnect: { reason: "kicked: banned", kicked: true } })));
    assert.equal(v3.verdict, "failed");
    const v4 = playtestVerdict(g.plan!, rep(undefined, { status: "busy" }));
    assert.equal(v4.verdict, "not_run");
    assert.ok(v4.requirements.every((r) => r.status !== "passed"));
  });
  it("Test Flight summary: a requested playtest that did not run makes the flight incomplete; a failed one fails it", () => {
    const tf = withPlaytest({ version: "1.21.11", plugins: [{ remotePath: "/tank/nxeon-build/tmp/testflight/inbox/fx/A.jar" }] }, g.plan!);
    assert.equal(summarize(tf, rep(undefined, { checks: checks({ playtest: { status: "not_run", evidence: [] } }) })).overall, "incomplete");
    assert.equal(summarize(tf, rep(undefined, { checks: checks({ playtest: { status: "fail" } }) })).overall, "failed");
    assert.equal(summarize(tf, rep(undefined, { checks: checks().filter((c) => c.id !== "playtest") })).overall, "incomplete", "an old runner without the check");
    const noPt = { version: "1.21.11" };
    assert.equal(summarize(noPt, rep(undefined, { checks: checks().filter((c) => c.id !== "playtest") })).overall, "passed", "boot-only flights are unchanged");
  });
  it("runPlaytest: off by default, refuses a version mismatch, runs once with the plan attached", async () => {
    const calls: unknown[] = [];
    const fake = async (s: Parameters<Parameters<typeof runPlaytest>[2]>[0]) => { calls.push(s); return { report: rep(run(g.plan!.scenarios.map((x) => sc(x.id, "pass", x.covers ?? [])))), summary: null as never }; };
    const off = await runPlaytest(spec, { version: "1.21.11" }, fake, { enabled: undefined });
    assert.equal(off.ran, false);
    assert.match((off as { reason: string }).reason, /CYRUS_PLAYTEST is off/);
    const mism = await runPlaytest(spec, { version: "26.2" }, fake, { enabled: true });
    assert.equal(mism.ran, false);
    const ok = await runPlaytest(spec, { version: "1.21.11" }, fake, { enabled: true });
    assert.equal(ok.ran, true);
    assert.equal(calls.length, 1);
    assert.ok((calls[0] as { playtest?: unknown }).playtest);
    if (ok.ran) { assert.equal(ok.verdict.verdict, "passed"); assert.equal(ok.summary.overall, "passed"); }
  });
});

describe("runner helpers (playtest-lib.js)", () => {
  it("offline UUIDs are version 3 and stable; chat components flatten; effects and items compare loosely", () => {
    const u = PT.offlineUuid("NxPlaytest");
    assert.match(u, /^[0-9a-f]{8}-[0-9a-f]{4}-3[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/);
    assert.equal(PT.offlineUuid("NxPlaytest"), u);
    assert.equal(PT.chatText('{"text":"Cyrus ","extra":[{"text":"Gem","color":"gold"}]}'), "Cyrus Gem");
    assert.equal(PT.chatText({ type: "compound", value: { text: { type: "string", value: "BOOST" } } }), "BOOST");
    assert.equal(PT.chatText("\u00a76Gold"), "Gold");
    assert.equal(PT.normEffect("minecraft:mining_fatigue"), PT.normEffect("MiningFatigue"));
    assert.deepEqual(PT.inventoryMatch([{ name: "diamond", count: 2, customName: '{"text":"Cyrus Gem"}' }, { name: "diamond", count: 1 }], { item: "minecraft:diamond", count: 2, name: "Cyrus Gem" }), { ok: true, total: 2, sameId: 3, want: 2 });
    assert.equal(PT.inventoryMatch([{ name: "dirt", count: 1, customName: "Cyrus Gem" }], { item: "diamond" }).ok, false);
    assert.equal(PT.playtestCheckStatus({ joined: true, scenarios: [{ status: "pass" }, { status: "not_run" }] }), "not_run");
    assert.equal(PT.playtestCheckStatus({ joined: false, joinFailed: true }), "fail");
    assert.equal(PT.expandBot("give {bot} apple", "Bob"), "give Bob apple");
  });
});

describe("bot.js against a fake mineflayer (step logic, no server)", () => {
  const BOT = path.join(__dirname, "..", "services/modbuilder/tools/testflight/bot.js");
  const runBot = (plan: PlaytestPlan, env: Record<string, string> = {}) => {
    const dir = mkdtempSync(path.join(tmpdir(), "cyrus-pt-"));
    try {
      const script = path.join(dir, "s.json");
      writeFileSync(script, JSON.stringify({ port: 1, rconPort: 1, rconPassword: "x", version: "1.21.11", plan, modulesDir: path.join(FIX, "fake-modules"), lockSha256: "fake" }));
      const r = spawnSync(process.execPath, [BOT, script, "-Dnxeon.testflight.run=test"], { encoding: "utf8", timeout: 60000, env: { ...process.env, ...env } });
      const line = r.stdout.split("\n").filter((l) => l.startsWith("@@PT ")).map((l) => JSON.parse(l.slice(5))).find((e) => e.ev === "result");
      assert.ok(line, `no result: ${r.stdout} ${r.stderr}`);
      return { result: line.result, events: r.stdout.split("\n").filter((l) => l.startsWith("@@PT ")).length };
    } finally { rmSync(dir, { recursive: true, force: true }); }
  };
  const plan = (): PlaytestPlan => ({ ...planFromSpec(loadSpec()).plan!, totalSec: 30, joinSec: 5 });
  it("the good fixture passes every scenario; RCON being unavailable is noted, not hidden", () => {
    const { result, events } = runBot(plan());
    assert.equal(result.joined, true);
    assert.deepEqual(result.scenarios.map((s: { id: string; status: string }) => [s.id, s.status]), [["T-1", "pass"], ["T-2", "pass"], ["T-3", "pass"], ["T-4", "pass"], ["T-5", "pass"], ["T-6", "pass"]]);
    assert.match(result.notes.join(" "), /bot RCON unavailable/);
    assert.equal(events, 6 * 2 + 1, "start + end per scenario, then the result");
  });
  it("the broken fixture fails exactly the gem scenarios, and later steps of a failed scenario are not_run", () => {
    const { result } = runBot(plan(), { FAKE_BROKEN: "1" });
    const st = Object.fromEntries(result.scenarios.map((s: { id: string; status: string }) => [s.id, s.status]));
    assert.deepEqual(st, { "T-1": "pass", "T-2": "fail", "T-3": "pass", "T-4": "pass", "T-5": "fail", "T-6": "pass" });
    const t2 = result.scenarios.find((s: { id: string }) => s.id === "T-2");
    assert.equal(t2.steps[1].status, "fail");
    assert.match(t2.steps[1].evidence.join(" "), /LACKS 1x diamond named "Cyrus Gem" \(matching 0, same id 0\).*1x dirt "Cyrus Gem"/s);
    assert.equal(t2.steps[2].status, "not_run");
  });
  it("a kick at login is a join failure with the reason", () => {
    const { result } = runBot(plan(), { FAKE_KICK: "1" });
    assert.equal(result.joined, false);
    assert.equal(result.joinFailed, true);
    assert.match(result.disconnect.reason, /You are not welcome/);
  });
});

