// REAL playtest flights on node-2 (not part of the unit suite). Each flight is ONE Test Flight (real Paper 1.21.11,
// private netns, node-2 lock; busy -> retry with backoff) with the scripted Mineflayer bot.
//   ssh node-2: cd /tank/nxeon-build/wt/<worktree> && npx tsx test/cyrus-playtest-real.ts --local [--out file.json]
//   (run in the ssh session, NOT inside `devhost run`: the agents slice has no room for a 1 GB server.)
//   1. TfPlay (good fixture)   -> boot checks pass AND all 6 scripted acceptance tests pass
//   2. TfPlayBroken (/tfgem gives dirt) -> boot checks STILL pass (it loads fine), playtest FAILS on T-2 and T-5 only
import { spawn } from "node:child_process";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import path from "node:path";
import { runTestFlight, type Remote } from "../lib/cyrus/testflight/client";
import { validateModSpec, type ModSpec } from "../lib/cyrus/engine-core/spec";
import { getAdapter } from "../lib/cyrus/adapters";
import { runPlaytest } from "../lib/cyrus/playtest/flight";
import type { TestFlightSpec } from "../lib/cyrus/testflight/types";

const FX = "/tank/nxeon-build/tmp/testflight/inbox/fx";
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d)); child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {}); child.stdin.end(opts.input ?? undefined);
  }),
};
const REMOTE = process.argv.includes("--local") ? localRemote : undefined;
const outArg = process.argv.indexOf("--out");
const OUT = outArg > 0 ? process.argv[outArg + 1] : null;

async function flyWithRetry(spec: TestFlightSpec) {
  for (let i = 0, wait = 15000; i < 16; i++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec, { remote: REMOTE });
    if (r.report.status !== "busy") return r;
    console.log(`node-2 busy, retry in ${wait / 1000}s`); await sleep(wait);
  }
  throw new Error("node-2 stayed busy");
}

async function main() {
  const v = validateModSpec(JSON.parse(readFileSync(path.join(__dirname, "fixtures/cyrus-playtest/tfplay.modspec.json"), "utf8")), { adapterFor: getAdapter });
  if (!v.ok) throw new Error(JSON.stringify(v.errors));
  const spec: ModSpec = v.spec;
  const flights = [];
  for (const [label, jar] of [["good", "TfPlay-1.21.11.jar"], ["broken", "TfPlayBroken-1.21.11.jar"]] as const) {
    const t0 = Date.now();
    const r = await runPlaytest(spec, { version: "1.21.11", plugins: [{ remotePath: `${FX}/${jar}` }], rcon: [{ command: "plugins", expect: ["TfPlay"] }, { command: "help tfgem", required: false }] },
      (s) => flyWithRetry(s), { enabled: true });
    if (!r.ran) { flights.push({ label, jar, ran: false, reason: r.reason }); console.log(label, "NOT RUN", r.reason); continue; }
    const pt = r.report.playtest as { scenarios?: { id: string; status: string; steps: { kind: string; status: string; evidence: string[] }[]; logHits?: string[] }[]; joinMs?: number; bot?: unknown; notes?: string[] } | undefined;
    const rec = {
      label, jar, ran: true, wallMs: Date.now() - t0, runId: r.report.runId, overall: r.summary.overall,
      checks: Object.fromEntries(r.report.checks.map((c) => [c.id, c.status])),
      playtestEvidence: r.report.checks.find((c) => c.id === "playtest")?.evidence ?? [],
      verdict: r.verdict, joinMs: pt?.joinMs ?? null, bot: pt?.bot ?? null, botNotes: pt?.notes ?? [],
      scenarios: (pt?.scenarios ?? []).map((s) => ({ id: s.id, status: s.status, logHits: s.logHits ?? [], steps: s.steps.map((x) => ({ kind: x.kind, status: x.status, evidence: x.evidence })) })),
      bootMs: r.report.bootMs, peakRssKb: r.report.peakRssKb, engine: r.report.engine, notes: r.report.notes, timings: r.report.timings,
    };
    flights.push(rec);
    console.log(`${label}: flight ${r.summary.overall}; ${r.verdict.label}`);
    for (const s of r.verdict.scenarios) console.log(`  ${s.id} ${s.status}${s.reason ? " - " + s.reason : ""}`);
  }
  const res = { recordedAt: new Date().toISOString(), what: "Cyrus playtest bots (R3): real Test Flights on node-2 with a scripted Mineflayer player", plan: "test/fixtures/cyrus-playtest/tfplay.modspec.json -> planFromSpec", flights };
  if (OUT) {
    const prev = existsSync(OUT) ? JSON.parse(readFileSync(OUT, "utf8")) : {};
    writeFileSync(OUT, JSON.stringify({ ...prev, playtest: res }, null, 1));
  } else console.log(JSON.stringify(res, null, 1));
}

main().catch((e) => { console.error(e); process.exit(1); });

