  if ((props["resource-pack"] ?? "").trim()) owners.push({ kind: "server.properties", name: "server.properties", detail: `resource-pack=${props["resource-pack"].slice(0, 200)}${props["require-resource-pack"] === "true" ? " (required)" : ""}` });
  for (const p of rep.packLoader.packs) owners.push({ kind: "pack-loader", name: "NxeonPackLoader", detail: `pack ${p.id} sha1=${p.sha1}` });
