  for (const o of KNOWN_PACK_OWNERS) if (names.has(o.toLowerCase())) owners.push({ kind: "plugin", name: names.get(o.toLowerCase())!, detail: `${o} manages its own resource pack` });
  rep.resourcePackOwners = owners;
  rep.bedrock.geyser = [...names.keys()].some((n) => n.startsWith("geyser"));
  rep.bedrock.floodgate = names.has("floodgate");
  for (const p of rep.plugins) {
    if (!p.descriptor) rep.undetermined.push(`${p.file}: no plugin.yml or paper-plugin.yml${p.flags.unreadable ? ` (${p.flags.unreadable})` : ""}`);
  }
  return rep;
}

