/**
 * The lifecycle state of a Cyrus mod on one server (PURE, client-safe).
 *
 * The DB row (ServerMod.status) says what the ENGINE did; this adds what the customer needs to
 * know on top: does it need a restart, did it break, is it out of date. One function derives the
 * state everyone shows (Mods tab row, server card, server banner, NxLabs "On my servers"), and
 * one transition table documents and tests how it moves (docs/DOCUMENTATION.md has the diagram).
 *
 *   resting:   enabled · disabled · pending_restart · failed · broken · outdated
 *   in flight: installing · updating · enabling · disabling · removing
 *
 * Priority when several are true: in flight > failed > broken > disabled > pending_restart >
 * outdated > enabled. ("Broken" outranks "Disabled" only while it is still switched on: a mod we
 * auto-disabled is Disabled, with the reason.)
 */
import type { OutdatedReason } from "./compat";

export type LifecycleState =
  | "installing" | "updating" | "enabling" | "disabling" | "removing"
  | "enabled" | "disabled" | "pending_restart" | "failed" | "broken" | "outdated";

export type LifecycleAction = "enable" | "disable" | "update" | "rollback" | "restart" | "remove" | "retry" | "rebuild";

export type LifecycleInput = {
  /** ServerMod.status */
  status: string;
  /** ServerMod.error (the last failure). */
  error: string | null;
  /** The last mod job changed this mod and the game hasn't restarted since. */
  restartPending: boolean;
  /** Open BROKEN signal / a load verdict "error" for the installed build. */
  broken: { evidence: string | null; apiMismatch: boolean } | null;
  /** We switched it off ourselves (crash loop after install). */
  autoDisabled: { why: string } | null;
  outdated: OutdatedReason[];
  /** The previous version is still on the server after a failed update (engine rolled back). */
  rolledBack: boolean;
};

export type LifecycleView = {
  state: LifecycleState;
  label: string;
  tone: "ok" | "info" | "warn" | "bad" | "muted";
  /** Customer-facing sentences, most important first. */
  notes: string[];
  actions: LifecycleAction[];
};

const FLIGHT: Record<string, LifecycleState> = { INSTALLING: "installing", UPDATING: "updating", ENABLING: "enabling", DISABLING: "disabling", REMOVING: "removing" };

export const STATE_LABEL: Record<LifecycleState, string> = {
  installing: "Installing", updating: "Updating", enabling: "Enabling", disabling: "Disabling", removing: "Removing",
  enabled: "Enabled", disabled: "Disabled", pending_restart: "Pending restart", failed: "Failed", broken: "Broken", outdated: "Outdated",
};

export function deriveLifecycle(i: LifecycleInput): LifecycleView {
  const flight = FLIGHT[i.status];
  if (flight) return { state: flight, label: STATE_LABEL[flight], tone: "info", notes: [], actions: [] };

  if (i.status === "FAILED") {
    return {
      state: "failed", label: "Failed", tone: "bad",
      notes: [i.error ?? "The last change didn't go through.", "Nothing half-installed was left behind: the engine rolls back a write that fails."],
      actions: ["retry", "remove"],
    };
  }

  const on = i.status === "INSTALLED";
  const notes: string[] = [];
  if (i.rolledBack && i.error) notes.push(`The update failed and the previous version was kept: ${i.error}`);

  if (on && i.broken) {
    return {
      state: "broken", label: "Broken", tone: "bad",
      notes: [
        i.broken.apiMismatch
          ? "The game log shows this mod calling something your game version doesn't have: it's out of date for this version."
          : "The game log shows errors naming this mod.",
        ...(i.broken.evidence ? [i.broken.evidence] : []),
        ...notes,
      ],
      actions: ["update", "rollback", "disable", "rebuild"],
    };
  }

  if (i.status === "DISABLED") {
    if (i.autoDisabled) notes.unshift(`We switched it off: ${i.autoDisabled.why} Its config and data were kept.`);
    return { state: "disabled", label: "Disabled", tone: "muted", notes, actions: ["enable", "remove"] };
  }

  if (on && i.restartPending) {
    return { state: "pending_restart", label: "Pending restart", tone: "info", notes: ["Restart the server to load this change.", ...notes], actions: ["restart", "disable"] };
  }

  if (on && i.outdated.length) {
    return {
      state: "outdated", label: "Outdated", tone: "warn",
      notes: [...i.outdated.map((o) => o.text), ...notes],
      actions: i.outdated.some((o) => o.code === "newer-build") ? ["update", "disable"] : ["rebuild", "disable"],
    };
  }

  return { state: "enabled", label: "Enabled", tone: "ok", notes, actions: ["disable", "remove"] };
}

/* ── transition table (documentation + tests; the engine/worker do the moving) ── */

export type LifecycleEvent =
  | "install" | "update" | "enable" | "disable" | "remove"
  | "job_ok_restart" | "job_ok_hot" | "job_failed" | "update_failed_rolled_back"
  | "restarted" | "log_error" | "crash_loop" | "log_clean" | "game_ahead" | "newer_build";

export const TRANSITIONS: Record<LifecycleState, Partial<Record<LifecycleEvent, LifecycleState>>> = {
  installing: { job_ok_restart: "pending_restart", job_ok_hot: "enabled", job_failed: "failed" },
  updating: { job_ok_restart: "pending_restart", job_ok_hot: "enabled", job_failed: "failed", update_failed_rolled_back: "enabled" },
  enabling: { job_ok_restart: "pending_restart", job_ok_hot: "enabled", job_failed: "failed" },
  disabling: { job_ok_restart: "disabled", job_ok_hot: "disabled", job_failed: "enabled" },
  removing: { job_failed: "enabled" },
  enabled: { disable: "disabling", update: "updating", remove: "removing", log_error: "broken", crash_loop: "disabling", game_ahead: "outdated", newer_build: "outdated" },
  pending_restart: { restarted: "enabled", log_error: "broken", crash_loop: "disabling", disable: "disabling" },
  outdated: { update: "updating", disable: "disabling", remove: "removing", log_error: "broken", crash_loop: "disabling" },
  broken: { update: "updating", disable: "disabling", remove: "removing", log_clean: "enabled", crash_loop: "disabling" },
  disabled: { enable: "enabling", remove: "removing" },
  failed: { install: "installing", remove: "removing" },
};

/** Next state for an event, or null when the event can't happen in that state. */
export function nextState(s: LifecycleState, e: LifecycleEvent): LifecycleState | null {
  return TRANSITIONS[s][e] ?? null;
}
/**
 * Reading a game log for a Cyrus mod's health (PURE: log text in, verdicts out).
 *
 * Builds on lib/mod-health.ts (the load-line readers every installed mod already uses) and
 * adds what a Cyrus mod needs on top:
 *   - RUNTIME errors that name the mod after it loaded (an event handler or a scheduled task
 *     throwing), not only load failures;
 *   - API-MISMATCH errors (NoSuchMethodError, NoSuchFieldError, ClassNotFoundException on the
 *     game's own API, UnsupportedClassVersionError): the signature of a mod that is out of date
 *     for the game version, which also feeds the creator warning;
 *   - CRASH LOOPS right after an install/update: the game started several times since the
 *     change and never finished starting.
 *
 * Honesty: "broken" needs a line that NAMES the mod (lib/mod-health.ts nameForms). A crash loop
 * blames a mod only when the crash names it, or when it is the ONLY mod changed in the window
 * (then the evidence says so). Patterns marked `verified: false` were written from the
 * framework's documented output but not yet seen on a live Nxeon server.
 */
import { judgeModHealth, nameForms, type HealthMod } from "../../mod-health";

export type LogPatterns = {
  /** A line that marks the game starting (one per boot). */
  start: RegExp;
  /** The game finished starting. */
  ready: RegExp;
  /** Errors at runtime that usually carry the plugin's name. */
  runtime: RegExp[];
  /** Errors that mean "built against a different game/API version". */
  apiMismatch: RegExp[];
  /** Fatal lines that end a boot. */
  fatal: RegExp[];
  verified: boolean;
};

/** Per server game family. Only Minecraft (Paper) is used for real today; the rest are ready for the game agents' mods. */
export const LOG_PATTERNS: Record<string, LogPatterns> = {
  minecraft: {
    start: /Starting minecraft server version/,
    ready: /Done \([0-9.]+s\)! For help, type/,
    runtime: [/Could not pass event \w+ to (\S+) v/, /Task #\d+ for (\S+) v\S+ generated an exception/, /Error occurred while enabling (\S+) v/, /Error occurred while disabling (\S+) v/, /Could not load '([^']+)'/],
    apiMismatch: [/java\.lang\.NoSuchMethodError/, /java\.lang\.NoSuchFieldError/, /java\.lang\.NoClassDefFoundError: (?:org\/bukkit|io\/papermc|net\/kyori|com\/destroystokyo)/, /UnsupportedClassVersionError/, /Unsupported API version/],
    fatal: [/Encountered an unexpected exception/, /Exception in server tick loop/, /This crash report has been saved to/, /java\.lang\.OutOfMemoryError/],
    verified: true,
  },
  valheim: {
    start: /\[Info\s*:\s*BepInEx\] BepInEx \d/,
    ready: /Game server connected/,
    runtime: [/\[Error\s*:\s*([^\]]+)\]/],
    apiMismatch: [/MissingMethodException/, /MissingFieldException/, /TypeLoadException/],
    fatal: [/Crash!!!/],
    verified: false,
  },
  rust: {
    start: /Loading Oxide|Carbon (?:v|\d)/,
    ready: /Server startup complete/,
    runtime: [/Failed to call hook '\w+' on plugin '([^' ]+)/, /Error while compiling:? (\S+)/],
    apiMismatch: [/does not contain a definition for/, /MissingMethodException/],
    fatal: [/Unhandled Exception/],
    verified: false,
  },
  terraria: {
    start: /TShock \d/,
    ready: /Server started/,
    runtime: [/Plugin (.+?) failed to load/],
    apiMismatch: [/MissingMethodException/, /TypeLoadException/],
    fatal: [/Unhandled exception/i],
    verified: false,
  },
  palworld: {
    start: /\[UE4SS\]|UE4SS - v/,
    ready: /Running Palworld dedicated server|Setting breakpad minidump AppID/,
    runtime: [/\[Lua\] .*error/i, /Failed to load mod/i],
    apiMismatch: [/Could not find function|attempt to call a nil value/],
    fatal: [/Fatal error!/],
    verified: false,
  },
  projectzomboid: {
    start: /versionNumber=|server is listening on port/,
    ready: /\*\*\* SERVER STARTED \*\*\*/,
    runtime: [/ERROR: .*mod/i, /LuaManager.*error/i],
    apiMismatch: [/attempted index: \w+ of non-table: null/],
    fatal: [/Exception thrown/],
    verified: false,
  },
};

const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, "");
const mentions = (line: string, m: HealthMod) => {
  const l = norm(line);
  return nameForms(m).some((f) => l.includes(f));
};

/** The LAST game version the log reports (a log can span restarts). Minecraft only today. */
export function gameVersionFromLog(family: string, log: string): string | null {
  if (family !== "minecraft") return null;
  const all = [...log.matchAll(/Starting minecraft server version ([0-9][0-9A-Za-z.\-+]*)/g)];
  return all.length ? all[all.length - 1][1].trim() : null;
}

export type CyrusLogVerdict = {
  mod: HealthMod;
  /** loaded = load line seen and no error naming it; broken = an error names it; unknown = can't tell. */
  status: "loaded" | "broken" | "not-seen" | "unknown";
  /** The error looks like a version/API mismatch (out of date for this game version). */
  apiMismatch: boolean;
  evidence: string[];
};

/**
 * Every line that names the mod and looks like an error, plus the load verdict from
 * lib/mod-health.ts. Stack traces: an API-mismatch line within 6 lines AFTER a line naming
 * the mod counts as that mod's (Paper prints the plugin line, then the exception).
 */
export function judgeCyrusLog(input: { family: string; variant: string | null; mods: HealthMod[]; log: string }): CyrusLogVerdict[] {
  const pat = LOG_PATTERNS[input.family];
  const base = judgeModHealth({ family: input.family, variant: input.variant, mods: input.mods, log: input.log });
  const lines = input.log.split(/\r?\n/);
  return input.mods.map((mod) => {
    const v = base.verdicts.find((x) => x.mod === mod);
    const evidence: string[] = [];
    let apiMismatch = false;
    if (pat) {
      lines.forEach((line, i) => {
        const isErr = pat.runtime.some((r) => r.test(line)) || pat.apiMismatch.some((r) => r.test(line)) || pat.fatal.some((r) => r.test(line));
        if (!isErr || !mentions(line, mod)) return;
        evidence.push(line.trim().slice(0, 240));
        const tail = lines.slice(i, i + 7);
        if (tail.some((t) => pat.apiMismatch.some((r) => r.test(t)))) apiMismatch = true;
      });
    }
    if (v?.status === "error" && v.evidence && !evidence.includes(v.evidence)) evidence.unshift(v.evidence);
    const broken = evidence.length > 0;
    if (broken && !apiMismatch && pat) apiMismatch = evidence.some((e) => pat.apiMismatch.some((r) => r.test(e)));
    const status: CyrusLogVerdict["status"] = broken ? "broken" : v?.status === "loaded" ? "loaded" : v?.status === "not-seen" ? "not-seen" : "unknown";
    return { mod, status, apiMismatch: broken && apiMismatch, evidence: evidence.slice(0, 5) };
  });
}

export type CrashLoopVerdict = {
  crashLoop: boolean;
  /** Boots seen in the log since the change. */
  starts: number;
  /** The game finished starting after the LAST boot. */
  readyAfterLast: boolean;
  /** The mod we may blame (null = we can't pin it on one). */
  suspect: HealthMod | null;
  why: string;
  evidence: string[];
};

/**
 * Crash loop right after a change: at least `minStarts` boots in the log since the change and
 * the last one never got to "ready", or the runtime says the container is restarting/crashed.
 * `changed` are the mods installed/updated in the window (Cyrus and others).
 */
export function judgeCrashLoop(input: {
  family: string;
  log: string;
  changed: HealthMod[];
  runtimeState: string | null;
  containerState: string | null;
  minStarts?: number;
}): CrashLoopVerdict {
  const pat = LOG_PATTERNS[input.family];
  const min = input.minStarts ?? 2;
  if (!pat) return { crashLoop: false, starts: 0, readyAfterLast: false, suspect: null, why: "No log patterns for this game.", evidence: [] };
  const lines = input.log.split(/\r?\n/);
  const startIdx = lines.map((l, i) => (pat.start.test(l) ? i : -1)).filter((i) => i >= 0);
  const last = startIdx.length ? startIdx[startIdx.length - 1] : -1;
  const readyAfterLast = last >= 0 && lines.slice(last).some((l) => pat.ready.test(l));
  const runtimeDown = input.containerState === "restarting" || input.runtimeState === "crashed";
  const crashLoop = (startIdx.length >= min && !readyAfterLast) || (runtimeDown && startIdx.length >= 1 && !readyAfterLast);
  if (!crashLoop) return { crashLoop: false, starts: startIdx.length, readyAfterLast, suspect: null, why: readyAfterLast ? "The game finished starting." : "Not enough restarts to call it a loop.", evidence: [] };
  // Who: an error line naming exactly one changed mod; else the only changed mod.
  const errLines = lines.filter((l) => pat.runtime.some((r) => r.test(l)) || pat.fatal.some((r) => r.test(l)) || pat.apiMismatch.some((r) => r.test(l)));
  const named = input.changed.filter((m) => errLines.some((l) => mentions(l, m)));
  if (named.length === 1) {
    const ev = errLines.filter((l) => mentions(l, named[0])).slice(-3).map((l) => l.trim().slice(0, 240));
    return { crashLoop, starts: startIdx.length, readyAfterLast, suspect: named[0], why: `The game restarted ${startIdx.length} times and the errors name ${named[0].name}.`, evidence: ev };
  }
  if (named.length === 0 && input.changed.length === 1) {
    return { crashLoop, starts: startIdx.length, readyAfterLast, suspect: input.changed[0], why: `The game restarted ${startIdx.length} times right after ${input.changed[0].name} was the only mod changed.`, evidence: errLines.slice(-3).map((l) => l.trim().slice(0, 240)) };
  }
  return { crashLoop, starts: startIdx.length, readyAfterLast, suspect: null, why: named.length > 1 ? `The errors name several mods (${named.map((m) => m.name).join(", ")}).` : "Several mods changed and none is named in the errors.", evidence: errLines.slice(-3).map((l) => l.trim().slice(0, 240)) };
}

// One plugin jar -> descriptor + bytecode summary + safety flags. Pure (bytes in, data out). Never extracts or runs.
import { createHash } from "node:crypto";
import { parseClass } from "./classfile";
import { addClass, emptySummary, finishSummary } from "./bytecode";
import { readDescriptor } from "./descriptor";
import { DEFAULT_ZIP_LIMITS, findEntry, indexZip, readEntry, type ZipLimits } from "./zipread";
import type { PluginJar } from "./types";

export const JAR_LIMITS = { maxClasses: 4000, maxClassBytes: 1024 * 1024, maxDescriptorBytes: 256 * 1024 };

/** Signs that a jar is a Minecraft/Paper SERVER (bundler/paperclip/CraftBukkit main), never a plugin. */
const SERVER_MARKERS = ["net/minecraft/server/Main.class", "net/minecraft/bundler/Main.class", "io/papermc/paperclip/Main.class", "io/papermc/paperclip/Paperclip.class", "org/bukkit/craftbukkit/Main.class", "META-INF/versions.list"];

export function inspectJar(file: string, path: string, buf: Buffer, opts: { zipLimits?: ZipLimits; bytecode?: boolean } = {}): PluginJar {
  const jar: PluginJar = {
    file, path, size: buf.length,
    sha256: createHash("sha256").update(buf).digest("hex"),
    sha1: createHash("sha1").update(buf).digest("hex"),
    descriptor: null, bytecode: null,
    flags: { unsafeNames: [], duplicateNames: [], bombEntries: [], unreadable: null, serverJar: false, serverJarEvidence: null },
  };
  const idx = indexZip(buf, opts.zipLimits ?? DEFAULT_ZIP_LIMITS);
  if (!idx.ok) { jar.flags.unreadable = idx.error; return jar; }
  const z = idx.zip;
  jar.flags.unsafeNames = z.unsafeNames.slice(0, 20);
  jar.flags.duplicateNames = z.duplicateNames.slice(0, 20);
  const marker = SERVER_MARKERS.find((m) => findEntry(z, m));
  if (marker) { jar.flags.serverJar = true; jar.flags.serverJarEvidence = `contains ${marker}`; }

  // Paper uses paper-plugin.yml when a jar has both.
  const both = !!findEntry(z, "plugin.yml") && !!findEntry(z, "paper-plugin.yml");
  for (const f of ["paper-plugin.yml", "plugin.yml"] as const) {
    const e = findEntry(z, f);
    if (!e) continue;
    const r = readEntry(z, e, JAR_LIMITS.maxDescriptorBytes);
    if (!r.ok) { if (r.bomb) jar.flags.bombEntries.push(f); jar.descriptor = { ...readDescriptor("", f), issues: [`${f} unreadable: ${r.error}`] }; break; }
    jar.descriptor = readDescriptor(r.data.toString("utf8"), f);
    if (both) jar.descriptor.issues.push("jar has both plugin.yml and paper-plugin.yml: Paper uses paper-plugin.yml");
    break;
  }
  if (opts.bytecode === false) return jar;

  const sum = emptySummary();
  const notes = new Map<string, number>();
  const ns = jar.descriptor?.name ? jar.descriptor.name.toLowerCase().replace(/[^a-z0-9._-]/g, "") : null;
  let n = 0;
  for (const e of z.entries) {
    if (e.dir || !e.name.endsWith(".class")) continue;
    if (n >= JAR_LIMITS.maxClasses) { sum.classesSkipped++; continue; }
    n++;
    const r = readEntry(z, e, JAR_LIMITS.maxClassBytes);
    if (!r.ok) { if (r.bomb) jar.flags.bombEntries.push(e.name.slice(0, 120)); sum.classesSkipped++; continue; }
    const c = parseClass(r.data);
    if (!c.ok) { sum.classesFailed++; continue; }
    addClass(sum, c.cls, ns, notes);
  }
  jar.flags.bombEntries = jar.flags.bombEntries.slice(0, 20);
  jar.bytecode = finishSummary(sum, notes);
  return jar;
}
