  main: string | null;
  apiVersion: string | null;
  foliaSupported: boolean;
  depend: string[];
  softdepend: string[];
  loadbefore: string[];
  provides: string[];
  libraries: string[];
  commands: DeclaredCommand[];
  permissions: DeclaredPermission[];
  issues: string[];
};

const PERM_DEFAULTS: Record<string, PermissionDefault> = {
  true: "true", t: "true", yes: "true", y: "true",
  false: "false", f: "false", no: "false", n: "false",
  op: "op", isop: "op", operator: "op", isoperator: "op", admin: "op", isadmin: "op",
  "!op": "not op", notop: "not op", "not op": "not op", "!operator": "not op", notoperator: "not op", "!admin": "not op", notadmin: "not op",
};
export const normalizePermDefault = (v: YamlValue | undefined): PermissionDefault | null => {
  const s = asStr(v);
  return s == null ? null : PERM_DEFAULTS[s.toLowerCase().replace(/_/g, " ").trim()] ?? PERM_DEFAULTS[s.toLowerCase().replace(/[\s_]/g, "")] ?? null;
};

const NAME_RE = /^[A-Za-z0-9 _.-]{1,64}$/;


/** Everything the inventory found, as server-origin entries, plus the context for the engine. */
export function inventoryEntries(inv: InventoryReport, opts: { exclude?: (path: string) => boolean } = {}): { mods: ModEntry[]; ctx: ConflictContext } {
  const mods: ModEntry[] = [];
  for (const p of inv.plugins) if (!opts.exclude?.(p.path)) mods.push(pluginEntry(p, "server"));
  for (const d of inv.datapacks.folder) if (!opts.exclude?.(`datapacks/${d.name}`)) mods.push(datapackEntry(d, "server"));
  return { mods, ctx: { mcVersion: inv.software.mcVersion, software: inv.software.name, packOwners: inv.resourcePackOwners } };
}

