// Cyrus Server Doctor: STARTUP LOG analysis (pure: log text in, findings out). Paper / Spigot / vanilla console
// lines in either format: stdout "[HH:MM:SS LEVEL]: msg" or logs/latest.log "[HH:MM:SS] [thread/LEVEL]: msg".
// Each pattern says whether it was SEEN on a real Paper 1.21.11 log in a node-2 flight (`seen: true`, see
// docs "Cyrus Server Doctor") or written from Paper's source/documented output only (`seen: false`).

export type LogFindingKind =
  | "plugin_load_failed" | "plugin_enable_failed" | "plugin_runtime_error" | "legacy_plugin" | "unsupported_api"
  | "dependency_missing" | "ambiguous_name" | "class_version" | "cant_keep_up" | "out_of_memory" | "crash" | "datapack_error"
  | "error_line";

export type LogFinding = { kind: LogFindingKind; plugin: string | null; line: number; text: string; detail?: string };

export type LogFacts = {
  /** Lines analysed (after the last server start in the file). */
  lines: number;
  /** The file holds more than one boot; only the last one is analysed. */
  boots: number;
  started: boolean;
  /** "Done (12.3s)!" of the last boot, seconds. null = the last boot never finished (or the log was cut). */
  doneSec: number | null;
  mcVersion: string | null;
  software: string | null;
  javaVersion: string | null;
  /** Plugins the log shows being enabled, by name. */
  enabled: string[];
  /** "Loading server plugin X vY" names (attempted loads). */
  loading: string[];
  findings: LogFinding[];
  /** "Can't keep up" warnings: count and the worst "Running Nms or M ticks behind". */
  lag: { count: number; worstMs: number | null; worstTicks: number | null };
  truncated: boolean;
};

const STRIP = /\x1b\[[0-9;]*m/g;
/** Message part of a console line (drops "[HH:MM:SS LEVEL]: " / "[HH:MM:SS] [thread/LEVEL]: "). */
export function messageOf(line: string): { level: string | null; msg: string } {
  const l = line.replace(STRIP, "");
  const a = /^\[\d{2}:\d{2}:\d{2}(?: (INFO|WARN|ERROR|FATAL|DEBUG))?\](?: \[[^\]]*?\/(INFO|WARN|ERROR|FATAL|DEBUG)\])?:? ?(.*)$/.exec(l);
  if (!a) return { level: null, msg: l };
  return { level: a[1] ?? a[2] ?? null, msg: a[3] };
}

type Rule = { kind: LogFindingKind; re: RegExp; plugin?: number; detail?: number; seen: boolean };
/** Ordered: the first rule that matches a line wins. */
export const LOG_RULES: Rule[] = [
  { kind: "plugin_load_failed", re: /Could not load '(?:plugins\/)?([^']+?)(?:\.jar)?' in (?:folder|'?plugins)/, plugin: 1, seen: true },
  { kind: "plugin_enable_failed", re: /Error occurred while enabling (\S+) v\S+/, plugin: 1, seen: true },
  { kind: "plugin_runtime_error", re: /Could not pass event (\w+) to (\S+) v/, plugin: 2, detail: 1, seen: false },
  { kind: "plugin_runtime_error", re: /Task #\d+ for (\S+) v\S+ generated an exception/, plugin: 1, seen: false },
  { kind: "legacy_plugin", re: /Legacy plugin (\S+) v\S+ does not specify an api-version/, plugin: 1, seen: false },
  { kind: "unsupported_api", re: /Unsupported API version (\S+)/, detail: 1, seen: false },
  { kind: "dependency_missing", re: /Unknown\/missing dependency plugins: \[([^\]]*)\]/, detail: 1, seen: false },
  { kind: "ambiguous_name", re: /Ambiguous plugin name `([^`]+)'/, plugin: 1, seen: false },
  { kind: "class_version", re: /UnsupportedClassVersionError: (\S+) has been compiled by a more recent version/, detail: 1, seen: false },
  { kind: "cant_keep_up", re: /Can't keep up! Is the server overloaded\? Running (\d+)ms or (\d+) ticks behind/, seen: false },
  { kind: "out_of_memory", re: /java\.lang\.OutOfMemoryError(?:: (.*))?/, detail: 1, seen: false },
  { kind: "crash", re: /(Encountered an unexpected exception|Exception in server tick loop|This crash report has been saved to)/, detail: 1, seen: false },
  { kind: "datapack_error", re: /(Couldn't (?:parse|load) data file|Failed to (?:load|parse) (?:datapack|data pack|function))/i, detail: 1, seen: false },
];

/** Analyse the LAST boot in a log (a latest.log can hold several if the server restarted without rotating). */
export function analyseLog(text: string, opts: { maxLines?: number } = {}): LogFacts {
  const all = text.split(/\r?\n/);
  const maxLines = opts.maxLines ?? 20000;
  const starts = all.map((l, i) => (/Starting minecraft server version|Loading Paper |Starting org\.bukkit\.craftbukkit\.Main/.test(l) ? i : -1)).filter((i) => i >= 0);
  // A boot begins at its "Starting minecraft server version" line; use the last one.
  const firstLine = starts.length ? starts[starts.length - 1] : 0;
  let lines = all.slice(firstLine);
  const truncated = lines.length > maxLines;
  if (truncated) lines = lines.slice(0, maxLines);
  const facts: LogFacts = {
    lines: lines.length, boots: Math.max(starts.length, 0), started: starts.length > 0, doneSec: null, mcVersion: null, software: null, javaVersion: null,
    enabled: [], loading: [], findings: [], lag: { count: 0, worstMs: null, worstTicks: null }, truncated,
  };
  // the "Starting minecraft server version" line may be after Paper's own "Loading Paper" banner; scan the whole file for it
  for (const l of all) { const m = /Starting minecraft server version ([0-9][0-9A-Za-z.\-+]*)/.exec(l); if (m) facts.mcVersion = m[1]; }
  const ex = (re: RegExp) => { for (const l of all) { const m = re.exec(l); if (m) return m; } return null; };
  const run = ex(/This server is running (\S+) version (\S+)/);
  if (run) facts.software = `${run[1]} ${run[2]}`.slice(0, 120);
  const jv = ex(/Running Java (\d+) \(([^)]*)\)/) ?? ex(/Java version: ?([0-9][0-9.+_\-]*)/);
  if (jv) facts.javaVersion = jv[1];
  lines.forEach((raw, i) => {
    const { level, msg } = messageOf(raw);
    const done = /Done \(([\d.,]+)s\)! For help, type/.exec(msg);
    if (done) facts.doneSec = Number(done[1].replace(",", "."));
    const en = /^\[?([^\]\s]+)\]? Enabling \1 v\S+/.exec(msg) ?? /^Enabling (\S+) v\S+/.exec(msg);
    if (en && !facts.enabled.includes(en[1])) facts.enabled.push(en[1]);
    const lo = /^\[?([^\]\s]+)\]? Loading server plugin \1 v\S+/.exec(msg) ?? /^Loading server plugin (\S+) v\S+/.exec(msg);
    if (lo && !facts.loading.includes(lo[1])) facts.loading.push(lo[1]);
    for (const r of LOG_RULES) {
      const m = r.re.exec(msg);
      if (!m) continue;
      if (r.kind === "cant_keep_up") {
        facts.lag.count++;
        const ms = Number(m[1]), t = Number(m[2]);
        if (facts.lag.worstMs == null || ms > facts.lag.worstMs) { facts.lag.worstMs = ms; facts.lag.worstTicks = t; }
        if (facts.lag.count > 3) return;
      }
      facts.findings.push({ kind: r.kind, plugin: r.plugin ? m[r.plugin] : null, line: firstLine + i + 1, text: msg.slice(0, 300), ...(r.detail && m[r.detail] ? { detail: m[r.detail].slice(0, 200) } : {}) });
      // the exception right after a load/enable failure explains it: keep the first one as detail
      if ((r.kind === "plugin_load_failed" || r.kind === "plugin_enable_failed") && !facts.findings[facts.findings.length - 1].detail) {
        const cause = lines.slice(i + 1, i + 4).map((x) => messageOf(x).msg.trim()).find((x) => /(?:Exception|Error)\b/.test(x));
        if (cause) facts.findings[facts.findings.length - 1].detail = cause.slice(0, 200);
      }
      return;
    }
    if (level === "ERROR" || level === "FATAL") facts.findings.push({ kind: "error_line", plugin: null, line: firstLine + i + 1, text: msg.slice(0, 300) });
  });
  // keep the report readable
  const errLines = facts.findings.filter((f) => f.kind === "error_line");
  if (errLines.length > 20) facts.findings = [...facts.findings.filter((f) => f.kind !== "error_line"), ...errLines.slice(0, 20)];
  return facts;
}

/** Paper `tps` reply: "TPS from last 1m, 5m, 15m: 20.0, 20.0, 20.0" (colours stripped; "*20.0" = capped). */
export function parseTps(reply: string | null | undefined): { m1: number; m5: number; m15: number } | null {
  const m = /TPS from last 1m, 5m, 15m: \*?([\d.]+),\s*\*?([\d.]+),\s*\*?([\d.]+)/.exec(String(reply ?? "").replace(/§[0-9a-fk-orx]/gi, ""));
  return m ? { m1: Number(m[1]), m5: Number(m[2]), m15: Number(m[3]) } : null;
}

/** Paper `mspt` reply: "Server tick times (avg/min/max) from last 5s, 10s, 1m:" then "◴ a/b/c, d/e/f, g/h/i". */
export function parseMspt(reply: string | null | undefined): { avg5s: number; max1m: number } | null {
  const s = String(reply ?? "").replace(/§[0-9a-fk-orx]/gi, "");
  const m = /([\d.]+)\/([\d.]+)\/([\d.]+),\s*([\d.]+)\/([\d.]+)\/([\d.]+),\s*([\d.]+)\/([\d.]+)\/([\d.]+)/.exec(s);
  return m ? { avg5s: Number(m[1]), max1m: Number(m[9]) } : null;
}

