input.content:
// Cyrus Server Doctor: mod-loader jars (Fabric / Quilt / Forge / NeoForge) -> minimal descriptor facts. Pure (bytes
// in, data out); never extracts or runs anything. The R2 inventory only reads Bukkit/Paper plugin descriptors; this
// adds what the Doctor needs for a modded server or for a mod jar dropped into a Paper plugins folder.
import { createHash } from "node:crypto";
import { findEntry, indexZip, readEntry } from "../inventory/zipread";

export type LoaderKind = "fabric" | "quilt" | "forge" | "neoforge";
export type ModJar = {
  file: string;
  path: string;
  size: number;
  sha256: string;
  loader: LoaderKind | null;
  id: string | null;
  version: string | null;
  name: string | null;
  /** Declared Minecraft version requirement, as written (e.g. ">=1.21", "~1.21.1", "[1.21,1.22)"). */
  minecraft: string | null;
  /** Fabric/Quilt `environment` (client / server / *). */
  environment: string | null;
  depends: string[];
  /** The jar also carries a Bukkit plugin.yml / paper-plugin.yml. */
  alsoPlugin: boolean;
  issues: string[];
};

const MAX_DESC = 256 * 1024;

/** Tiny TOML reader for the few mods.toml keys we need ([[mods]] modId/version/displayName, [[dependencies.<id>]] modId/versionRange). */
export function readModsToml(text: string): { mods: { modId?: string; version?: string; displayName?: string }[]; deps: { modId?: string; versionRange?: string }[] } {
  const mods: Record<string, string>[] = [], deps: Record<string, string>[] = [];
  let cur: Record<string, string> | null = null;
  for (const raw of text.split(/\r?\n/).slice(0, 5000)) {
    const line = raw.replace(/#.*$/, "").trim();
    if (!line) continue;
    if (/^\[\[mods\]\]$/.test(line)) { cur = {}; mods.push(cur); continue; }
    if (/^\[\[dependencies\.[^\]]+\]\]$/.test(line)) { cur = {}; deps.push(cur); continue; }
    if (/^\[/.test(line)) { cur = null; continue; }
    const m = /^([A-Za-z0-9_]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|(\S+))/.exec(line);
    if (m && cur) cur[m[1]] = m[2] ?? m[3] ?? m[4];
  }
  return { mods, deps };
}

export function inspectModJar(file: string, path: string, buf: Buffer): ModJar {
  const jar: ModJar = { file, path, size: buf.length, sha256: createHash("sha256").update(buf).digest("hex"), loader: null, id: null, version: null, name: null, minecraft: null, environment: null, depends: [], alsoPlugin: false, issues: [] };
  const idx = indexZip(buf);
  if (!idx.ok) { jar.issues.push(`unreadable: ${idx.error}`); return jar; }
  const z = idx.zip;
  jar.alsoPlugin = !!findEntry(z, "plugin.yml") || !!findEntry(z, "paper-plugin.yml");
  const text = (name: string): string | null => {
    const e = findEntry(z, name);
    if (!e) return null;
    const r = readEntry(z, e, MAX_DESC);
    return r.ok ? r.data.toString("utf8") : (jar.issues.push(`${name} unreadable: ${r.error}`), null);
  };
  const fabric = text("fabric.mod.json"), quilt = text("quilt.mod.json");
  if (fabric != null || quilt != null) {
    jar.loader = fabric != null ? "fabric" : "quilt";
    try {
      const j = JSON.parse((fabric ?? quilt)!) as Record<string, unknown>;
      const q = (j.quilt_loader ?? null) as Record<string, unknown> | null;
      const src = q ?? j;
      jar.id = typeof src.id === "string" ? src.id.slice(0, 64) : null;
      jar.version = typeof src.version === "string" ? src.version.slice(0, 64) : null;
      const meta = (q?.metadata ?? j) as Record<string, unknown>;
      jar.name = typeof meta.name === "string" ? meta.name.slice(0, 100) : null;
