      jar.name = typeof meta.name === "string" ? meta.name.slice(0, 100) : null;
      jar.environment = typeof j.environment === "string" ? j.environment : typeof (j.minecraft as Record<string, unknown> | undefined)?.environment === "string" ? String((j.minecraft as Record<string, unknown>).environment) : null;
      const dep = (j.depends ?? null) as Record<string, unknown> | null;
