          if (id) jar.depends.push(String(id));
          if (id === "minecraft" && typeof (d as { versions?: unknown }).versions === "string") jar.minecraft = String((d as { versions: string }).versions);
        }
      }
    } catch { jar.issues.push(`${fabric != null ? "fabric" : "quilt"}.mod.json is not valid JSON`); }
