// Cyrus Server Doctor: KNOWN-ISSUE rules (pure). Two kinds:
//  1. platform rules: facts about how Paper / Fabric / Forge treat a jar (a Fabric mod in a Paper plugins folder is
//     never loaded, a client-only mod does nothing on a server, a plugin without api-version is a legacy plugin ...);
//  2. a KNOWN-BROKEN list of specific jars (by sha256, or plugin name + version prefix), each with a reason and a
//     SOURCE. Shipped EMPTY on purpose: entries come from the owner/ops (curated, with a source) or from mod-health
//     telemetry signatures (lib/cyrus/telemetry), never from guesses.
import type { PluginJar } from "../inventory/types";
import type { ModJar } from "./mods";

export type KnownBrokenEntry = {
  id: string;
  /** Exact jar. */
  sha256?: string;
  /** Plugin/mod name (case-insensitive) + optional version prefix ("2.3" matches 2.3, 2.3.1 ...). */
  name?: string;
  versionPrefix?: string;
  /** Only on these Minecraft versions (prefix match, e.g. "1.21"). Omit = any. */
  mcPrefix?: string;
  severity: "problem" | "warn";
  reason: string;
  advice: string;
  /** Where the fact comes from (issue tracker URL, owner note, telemetry signature id). Required. */
  source: string;
};

/** The curated list. Empty until the owner adds entries with a source (see OWNER-ACTIONS "Server Doctor"). */
export const KNOWN_BROKEN: readonly KnownBrokenEntry[] = [];

export type KnownIssue = { id: string; severity: "problem" | "warn" | "info"; title: string; detail: string; advice: string; evidence: string[]; rule: string };

/** Minecraft version requirement check for mod metadata. null = the syntax is not understood (reported as not checked). */
export function satisfiesMc(range: string, version: string): boolean | null {
  const v = parse(version);
  if (!v) return null;
  const r = range.trim();
  if (!r || r === "*") return true;
  // Forge / Maven interval: [1.21,1.22) or [1.21.1] or (,1.21] ; comma-separated union of intervals
  if (/^[[(]/.test(r)) {
    const parts = r.match(/[[(][^\])]*[\])]/g);
    if (!parts) return null;
    let any = false;
    for (const p of parts) {
      const m = /^([[(])\s*([^,\])]*)\s*(?:,\s*([^\])]*))?\s*([\])])$/.exec(p);
      if (!m) return null;
      const lo = m[2] ? parse(m[2]) : null, hi = m[3] != null ? (m[3] ? parse(m[3]) : null) : lo;
      if ((m[2] && !lo) || (m[3] && !hi)) return null;
      const single = m[3] === undefined;
      const okLo = !lo || (m[1] === "[" ? cmp(v, lo) >= 0 : cmp(v, lo) > 0);
      const okHi = single ? (lo ? cmp(v, lo) === 0 : true) : !hi || (m[4] === "]" ? cmp(v, hi) <= 0 : cmp(v, hi) < 0);
      if (okLo && okHi) any = true;
    }
    return any;
  }
  // Fabric: alternatives with ||, each a space-separated AND of comparators
  const alts = r.split("||").map((a) => a.trim()).filter(Boolean);
  let any = false;
  for (const alt of alts) {
    let all = true;
    for (const c of alt.split(/\s+/)) {
      const m = /^(>=|<=|>|<|=|~|\^)?\s*([0-9][0-9a-z.\-+*x]*)$/i.exec(c);
      if (!m) return null;
      const op = m[1] ?? "", want = m[2];
      if (/[x*]/i.test(want)) { // 1.21.x
        const pre = want.replace(/\.?[x*].*$/i, "");
        if (!(version === pre || version.startsWith(pre + "."))) all = false;
        continue;
      }
      const w = parse(want);
      if (!w) return null;
      const d = cmp(v, w);
      if (op === ">=" && !(d >= 0)) all = false;
      else if (op === ">" && !(d > 0)) all = false;
      else if (op === "<=" && !(d <= 0)) all = false;
      else if (op === "<" && !(d < 0)) all = false;
      else if ((op === "=" || op === "") && d !== 0) all = false;
      else if (op === "~" && !(d >= 0 && v[0] === w[0] && v[1] === w[1])) all = false;
      else if (op === "^" && !(d >= 0 && v[0] === w[0] && (w[0] !== 1 || v[1] === w[1]))) all = false; // Minecraft 1.x: ^1.21 means 1.21.x
    }
    if (all) any = true;
  }
  return any;
}
function parse(s: string): number[] | null {
  const m = /^(\d+)(?:\.(\d+))?(?:\.(\d+))?(?:[-+].*)?$/.exec(s.trim());
  return m ? [Number(m[1]), Number(m[2] ?? 0), Number(m[3] ?? 0)] : null;
}
function cmp(a: number[], b: number[]): number {
  for (let i = 0; i < 3; i++) if (a[i] !== b[i]) return a[i] - b[i];
  return 0;
}

export type KnownInput = {
  software: string;
  mcVersion: string | null;
  plugins: PluginJar[];
  /** Jars in plugins/ that have no plugin descriptor (re-read as mod jars). */
  pluginFolderMods: ModJar[];
  /** Jars in mods/ (modded servers). */
  mods: ModJar[];
  disabledJars: string[];
  knownBroken?: readonly KnownBrokenEntry[];
};

export function knownIssues(i: KnownInput): { issues: KnownIssue[]; notChecked: string[] } {
  const issues: KnownIssue[] = [];
  const notChecked: string[] = [];
  const paperLike = ["paper", "purpur", "folia", "spigot", "craftbukkit"].includes(i.software);
  const modded = ["fabric", "forge", "neoforge"].includes(i.software);
  for (const p of i.plugins) {
    const d = p.descriptor;
    if (d && d.file === "plugin.yml" && !d.apiVersion && paperLike) issues.push({
      id: `legacy:${p.file}`, severity: "warn", rule: "platform.legacy_plugin",
      title: `${d.name ?? p.file} is a legacy plugin`,
      detail: "Its plugin.yml has no api-version, so Paper treats it as written for Minecraft 1.12 or older and loads it through a compatibility layer. Such plugins often misbehave on current versions and slow the start.",
      advice: "Look for an up-to-date version of this plugin, or a maintained replacement.",
      evidence: [`${p.path}: plugin.yml without api-version`],
    });
  }
  for (const m of i.pluginFolderMods) {
    if (!m.loader) continue;
    issues.push({
      id: `mod-in-plugins:${m.file}`, severity: "problem", rule: "platform.mod_in_plugin_folder",
      title: `${m.name ?? m.id ?? m.file} is a ${m.loader} mod, not a plugin`,
      detail: `It sits in the plugins folder, but it is a ${m.loader} mod (it has no plugin.yml). ${paperLike ? "Paper" : "This server"} cannot load it: it does nothing and logs an error at every start.`,
      advice: `Remove it from plugins/. It only works on a ${m.loader} server.`,
      evidence: [`${m.path}: ${m.loader} descriptor, id ${m.id ?? "?"} ${m.version ?? ""}`.trim()],
    });
  }
  for (const m of i.mods) {
    if (!m.loader && m.alsoPlugin) issues.push({
      id: `plugin-in-mods:${m.file}`, severity: "problem", rule: "platform.plugin_in_mods_folder",
      title: `${m.file} is a Bukkit/Paper plugin in the mods folder`,
      detail: "Mod loaders do not load Bukkit/Paper plugins, so it does nothing here.", advice: "Remove it, or run a Paper server for plugins.", evidence: [`${m.path}: plugin.yml, no mod descriptor`],
    });
    if (m.loader && modded && m.loader !== i.software && !(m.loader === "quilt" && i.software === "fabric")) issues.push({
      id: `wrong-loader:${m.file}`, severity: "warn", rule: "platform.wrong_loader",
      title: `${m.name ?? m.id ?? m.file} is a ${m.loader} mod on a ${i.software} server`,
      detail: `${i.software} does not load ${m.loader} mods (unless a compatibility layer is installed).`, advice: `Use the ${i.software} build of this mod.`, evidence: [`${m.path}: ${m.loader}`],
    });
    if (m.environment === "client") issues.push({
      id: `client-only:${m.file}`, severity: "warn", rule: "platform.client_only_mod",
      title: `${m.name ?? m.id ?? m.file} is a client-only mod`,
      detail: "Its metadata says it is for the game client only, so it does nothing on a server.", advice: "Remove it from the server; players install it on their own PC if they want it.", evidence: [`${m.path}: environment "client"`],
    });
    if (m.minecraft && i.mcVersion) {
      const ok = satisfiesMc(m.minecraft, i.mcVersion);
      if (ok === false) issues.push({
        id: `mc-range:${m.file}`, severity: "problem", rule: "platform.minecraft_range",
        title: `${m.name ?? m.id ?? m.file} is not made for Minecraft ${i.mcVersion}`,
        detail: `It declares Minecraft ${m.minecraft}; the server runs ${i.mcVersion}. The loader refuses to start, or the mod breaks.`, advice: `Install the version of this mod built for ${i.mcVersion}.`, evidence: [`${m.path}: minecraft ${m.minecraft}`],
      });
      else if (ok === null) notChecked.push(`${m.file}: Minecraft requirement "${m.minecraft}" could not be read`);
    }
  }
  if (i.disabledJars.length) issues.push({
    id: "disabled-jars", severity: "info", rule: "inventory.disabled_jars", title: `${i.disabledJars.length} switched-off jar(s)`,
    detail: "Files ending in .disabled (or similar) are not loaded.", advice: "Delete them if you no longer need them.", evidence: i.disabledJars.slice(0, 10),
  });
  const list = i.knownBroken ?? KNOWN_BROKEN;
  if (!list.length) notChecked.push("known-broken list: no curated entries yet, so specific broken plugin versions were not looked up");
  for (const k of list) {
    if (!k.source) continue; // an entry without a source is never used
    if (k.mcPrefix && !(i.mcVersion && (i.mcVersion === k.mcPrefix || i.mcVersion.startsWith(k.mcPrefix + ".")))) continue;
    const hits = [
      ...i.plugins.map((p) => ({ file: p.path, sha: p.sha256, name: p.descriptor?.name ?? null, version: p.descriptor?.version ?? null })),
      ...i.mods.map((m) => ({ file: m.path, sha: m.sha256, name: m.name ?? m.id, version: m.version })),
    ].filter((x) => (k.sha256 && x.sha === k.sha256) || (!k.sha256 && k.name && x.name && x.name.toLowerCase() === k.name.toLowerCase() && (!k.versionPrefix || (x.version ?? "").startsWith(k.versionPrefix))));
    for (const h of hits) issues.push({ id: `known:${k.id}:${h.file}`, severity: k.severity, rule: "known_broken", title: `${h.name ?? h.file} ${h.version ?? ""} is known to be broken`.replace(/\s+/g, " ").trim(), detail: k.reason, advice: k.advice, evidence: [`${h.file} sha256 ${h.sha.slice(0, 16)}...`, `source: ${k.source}`] });
  }
  return { issues, notChecked };
}

