// Cyrus SERVER DOCTOR (R4): a READ-ONLY diagnostic for a customer Minecraft server, including one with NO Cyrus mods.
// Reads files only through the injectable ReadOnlyServerFs (same seam as the R2 inventory), and, optionally, a
// read-only console limited to DOCTOR_CONSOLE_COMMANDS. Writes nothing, restarts nothing, never reads secrets
// (the inventory's server.properties allow-list applies). Produces a customer-readable report with honest
// "could not check" states: a section that did not run is never shown as healthy.
//
// Sections: server facts (software, version, loader, Java), inventory (plugins/mods), conflicts (the R2 conflict
// engine over everything installed), known issues (platform rules + the curated known-broken list), startup log
// (latest.log, last boot), performance (memory/TPS hints from files, the log, and the live console when given).
import { scanServer } from "../inventory/scan";
import type { InventoryReport, PluginJar, ReadOnlyServerFs } from "../inventory/types";
import { inventoryEntries } from "../conflicts/normalize";
import { detectConflicts } from "../conflicts/engine";
import type { ConflictReport } from "../conflicts/types";
import { analyseLog, parseMspt, parseTps, type LogFacts } from "./log";
import { inspectModJar, type ModJar } from "./mods";
import { knownIssues, type KnownBrokenEntry } from "./known";

export const DOCTOR_VERSION = "cyrus-doctor-1";
/** The only console commands the Doctor may send (all read-only on Paper). */
export const DOCTOR_CONSOLE_COMMANDS = ["tps", "mspt", "version"] as const;
export type ReadOnlyConsole = { run(command: string): Promise<string | null> };

export type Severity = "problem" | "warn" | "info";
export type SectionId = "server" | "inventory" | "conflicts" | "known_issues" | "startup_log" | "performance";
export type SectionStatus = "ok" | "attention" | "problems" | "could_not_check";
export type DoctorItem = { id: string; severity: Severity; title: string; detail: string; advice: string | null; evidence: string[] };
export type DoctorSection = { id: SectionId; title: string; status: SectionStatus; summary: string; items: DoctorItem[]; couldNotCheck: string[] };
export type PluginRow = { name: string; version: string | null; file: string; kind: "plugin" | "mod" | "unknown"; loader: string | null; enabledAtLastStart: boolean | null; problems: number };

export type DoctorReport = {
  schema: 1;
  doctor: typeof DOCTOR_VERSION;
  generatedAt: string;
  readOnly: true;
  overall: "healthy" | "attention" | "problems" | "incomplete";
  headline: string;
  server: { software: string; mcVersion: string | null; build: string | null; java: string | null; loader: string | null; plugins: number; mods: number; datapacks: number; evidence: string[] };
  sections: DoctorSection[];
  installed: PluginRow[];
  counts: { problems: number; warnings: number; info: number; couldNotCheck: number };
  limits: InventoryReport["limits"] & { logBytes: number; logTruncated: boolean };
};

export type DoctorOptions = {
  base?: string;
  console?: ReadOnlyConsole | null;
  knownBroken?: readonly KnownBrokenEntry[];
  /** Optional facts the host knows (plan RAM, JVM max heap); never guessed by the Doctor. */
  host?: { memoryLimitMb?: number | null; xmxMb?: number | null };
  now?: () => Date;
  maxLogBytes?: number;
};

const join = (...p: string[]) => p.filter(Boolean).join("/").replace(/\/+/g, "/");
const plural = (n: number, w: string) => `${n} ${w}${n === 1 ? "" : "s"}`;

function sectionOf(id: SectionId, title: string, items: DoctorItem[], couldNotCheck: string[], ran: boolean, okSummary: string): DoctorSection {
  const p = items.filter((x) => x.severity === "problem").length, w = items.filter((x) => x.severity === "warn").length;
  const status: SectionStatus = !ran ? "could_not_check" : p ? "problems" : w ? "attention" : "ok";
  const summary = !ran ? (couldNotCheck[0] ?? "Could not check.") : p || w ? [p && plural(p, "problem"), w && plural(w, "warning")].filter(Boolean).join(", ") : okSummary;
  return { id, title, status, summary, items, couldNotCheck };
}

/** Wrap a console so only the allow-listed read-only commands can ever be sent. */
export function guardConsole(c: ReadOnlyConsole): ReadOnlyConsole {
  return { run: async (cmd: string) => { if (!(DOCTOR_CONSOLE_COMMANDS as readonly string[]).includes(cmd.trim())) throw new Error(`Server Doctor never sends '${cmd}'`); return c.run(cmd.trim()); } };
}

export async function runDoctor(fs: ReadOnlyServerFs, opts: DoctorOptions = {}): Promise<DoctorReport> {
  const base = (opts.base ?? "/opt/mc").replace(/\/$/, "");
  const inv = await scanServer(fs, { base });
  const safeList = async (d: string) => { try { return (await fs.list(d)).filter((n) => n && n !== "." && n !== ".." && !/[\/\\\0]/.test(n)).sort(); } catch { return []; } };

  // ---- mod-loader jars: mods/ on modded servers; plugin-folder jars without a plugin descriptor
  const mods: ModJar[] = [];
  const pluginFolderMods: ModJar[] = [];
  const readJar = async (p: string) => { try { const st = await fs.stat(p); if (!st || st.type !== "file" || st.size > 64 * 1024 * 1024) return null; return await fs.readFile(p, 64 * 1024 * 1024); } catch { return null; } };
  const modFiles = (await safeList(join(base, "mods"))).filter((f) => f.toLowerCase().endsWith(".jar")).slice(0, 300);
  for (const f of modFiles) { const b = await readJar(join(base, "mods", f)); if (b) mods.push(inspectModJar(f, `mods/${f}`, b)); }
  for (const p of inv.plugins.filter((x) => !x.descriptor)) { const b = await readJar(join(base, p.path)); if (b) pluginFolderMods.push(inspectModJar(p.file, p.path, b)); }
  const disabledJars = [...(await safeList(join(base, "plugins"))), ...(await safeList(join(base, "mods"))).map((x) => `mods/${x}`)].filter((f) => /\.jar\.(disabled|off|old|bak)$/i.test(f));

  // ---- startup log (last boot)
  const maxLog = opts.maxLogBytes ?? 4 * 1024 * 1024;
  let logBuf: Buffer | null = null;
  try { logBuf = await fs.readFile(join(base, "logs/latest.log"), maxLog); } catch { logBuf = null; }
  const log: LogFacts | null = logBuf ? analyseLog(logBuf.toString("utf8")) : null;

  // ---- server facts
  const loader = inv.software.name === "fabric" || inv.software.name === "forge" || inv.software.name === "neoforge" ? inv.software.name
    : mods.length ? (mods.find((m) => m.loader)?.loader ?? null) : null;
  const serverItems: DoctorItem[] = [];
  const serverCnc: string[] = [...inv.undetermined.filter((u) => /version|software/i.test(u))];
  const mcVersion = inv.software.mcVersion ?? log?.mcVersion ?? null;
  if (!mcVersion) serverCnc.push("Minecraft version: not found in the files");
  if (inv.software.name === "unknown") serverCnc.push("Server software: not recognised");
  if (!log?.javaVersion) serverCnc.push("Java version: not shown in the log");
  if (inv.software.name === "spigot" || inv.software.name === "craftbukkit") serverItems.push({ id: "software-spigot", severity: "info", title: `Runs ${inv.software.name}`, detail: "Paper is a faster, compatible replacement for Spigot/CraftBukkit and runs the same plugins.", advice: "Consider switching to Paper.", evidence: inv.software.evidence.slice(0, 2) });
  const server = sectionOf("server", "Server", serverItems, serverCnc, inv.software.name !== "unknown" || !!mcVersion, `${inv.software.name} ${mcVersion ?? ""}`.trim());

  // ---- inventory
  const invItems: DoctorItem[] = [];
  for (const p of inv.plugins) for (const iss of p.descriptor?.issues ?? []) invItems.push({ id: `desc:${p.file}:${iss.slice(0, 30)}`, severity: "info", title: `${p.descriptor?.name ?? p.file}: plugin.yml note`, detail: iss, advice: null, evidence: [p.path] });
  const invCnc = [...inv.limits.truncated, ...inv.undetermined.filter((u) => !/version|software/i.test(u))];
  const inventory = sectionOf("inventory", "Plugins and mods", invItems, invCnc, true, `${plural(inv.plugins.length, "plugin")}${mods.length ? `, ${plural(mods.length, "mod")}` : ""}, ${plural(inv.datapacks.folder.length, "data pack")}`);

  // ---- conflicts (R2 engine over everything installed)
  let conflictReport: ConflictReport | null = null;
  const confItems: DoctorItem[] = [];
  const confCnc: string[] = [];
  if (inv.plugins.length + inv.datapacks.folder.length === 0) confCnc.push("No plugins or data packs to compare.");
  else {
    const { mods: entries, ctx } = inventoryEntries(inv);
    conflictReport = detectConflicts(entries, ctx);
    for (const f of conflictReport.findings) confItems.push({
      id: `conflict:${f.id}`, severity: f.severity === "blocking" ? "problem" : f.severity === "warn" ? "warn" : "info",
      title: f.message, detail: `${f.class.replace(/[._]/g, " ")}: ${f.subject}`, advice: f.resolution.text, evidence: f.items.map((x) => `${x.label}: ${x.evidence}`).slice(0, 6),
    });
    confCnc.push(...conflictReport.notChecked);
  }
  if (mods.length) confCnc.push(`${plural(mods.length, "mod-loader jar")}: the conflict engine checks Paper plugins and data packs only`);
  const conflicts = sectionOf("conflicts", "Conflicts", confItems, confCnc, !!conflictReport, "No conflicts found between installed plugins and data packs");

  // ---- known issues
  const ki = knownIssues({ software: inv.software.name, mcVersion, plugins: inv.plugins, pluginFolderMods, mods, disabledJars, knownBroken: opts.knownBroken });
  const known = sectionOf("known_issues", "Known problems", ki.issues.map((k) => ({ id: k.id, severity: k.severity, title: k.title, detail: k.detail, advice: k.advice, evidence: k.evidence })), ki.notChecked, true, "None of the known problem patterns matched");

  // ---- startup log
  const logItems: DoctorItem[] = [];
  const logCnc: string[] = [];
  const pluginNames = inv.plugins.map((p) => p.descriptor?.name).filter((n): n is string => !!n);
  if (!log) logCnc.push("logs/latest.log not found: the server may never have started, or logs are elsewhere");
  else {
    if (!log.started) logCnc.push("latest.log has no server start line; the log may be from a crash or cut off");
    if (log.truncated) logCnc.push(`only the first ${log.lines} lines of the last start were read`);
    const by = (k: string) => log.findings.filter((f) => f.kind === k);
    for (const f of by("plugin_load_failed")) logItems.push({ id: `log-load:${f.plugin}`, severity: "problem", title: `${f.plugin} did not load`, detail: f.detail ? `Paper could not load it: ${f.detail}` : "Paper could not load it.", advice: "Check the plugin's requirements (Minecraft version, Java version, dependencies) or remove it.", evidence: [`latest.log line ${f.line}: ${f.text}`] });
    for (const f of by("plugin_enable_failed")) logItems.push({ id: `log-enable:${f.plugin}`, severity: "problem", title: `${f.plugin} crashed while starting`, detail: f.detail ? `It threw an error when it was enabled: ${f.detail}` : "It threw an error when it was enabled, so Paper switched it off.", advice: "Update the plugin or check its config; send the log lines to its author.", evidence: [`latest.log line ${f.line}: ${f.text}`] });
    for (const f of by("plugin_runtime_error").slice(0, 5)) logItems.push({ id: `log-runtime:${f.plugin}:${f.line}`, severity: "warn", title: `${f.plugin} logged an error while running`, detail: f.text, advice: "If players notice problems, update this plugin.", evidence: [`latest.log line ${f.line}`] });
    for (const f of by("legacy_plugin")) logItems.push({ id: `log-legacy:${f.plugin}`, severity: "warn", title: `${f.plugin} runs in legacy mode`, detail: "Paper reported it as a legacy plugin (no api-version).", advice: "Update it to a current version.", evidence: [`latest.log line ${f.line}: ${f.text}`] });
    for (const k of ["unsupported_api", "dependency_missing", "ambiguous_name", "class_version", "datapack_error"] as const) for (const f of by(k).slice(0, 5)) logItems.push({ id: `log-${k}:${f.line}`, severity: k === "datapack_error" ? "warn" : "problem", title: ({ unsupported_api: "A plugin needs a newer server", dependency_missing: "A plugin is missing a dependency", ambiguous_name: "Two jars have the same plugin name", class_version: "A plugin needs a newer Java", datapack_error: "A data pack has an error" } as const)[k], detail: f.text, advice: k === "dependency_missing" ? "Install the missing plugin(s) named in the line, or remove the one that needs them." : k === "class_version" ? "Use a build of the plugin for this server's Java, or upgrade Java." : "Update or remove the plugin/pack named in the line.", evidence: [`latest.log line ${f.line}`] });
    for (const f of by("crash")) logItems.push({ id: `log-crash:${f.line}`, severity: "problem", title: "The server crashed", detail: f.text, advice: "Open the crash report; the first lines name the cause.", evidence: [`latest.log line ${f.line}`] });
    for (const f of by("out_of_memory")) logItems.push({ id: `log-oom:${f.line}`, severity: "problem", title: "The server ran out of memory", detail: f.text, advice: "Give the server more memory, lower view-distance, or remove heavy plugins.", evidence: [`latest.log line ${f.line}`] });
    if (log.started && log.doneSec == null) logItems.push({ id: "log-not-done", severity: "problem", title: "The last start did not finish", detail: "The log has no \"Done\" line after the last start: the server stopped or crashed while starting (or is still starting).", advice: "Look at the last lines of the log for the error.", evidence: [`${log.lines} lines after the last start`] });
    if (log.doneSec != null) {
      const notEnabled = pluginNames.filter((n) => !log.enabled.some((e) => e.toLowerCase() === n.toLowerCase()));
      const explained = new Set(log.findings.map((f) => (f.plugin ?? "").toLowerCase()));
      for (const n of notEnabled) if (!explained.has(n.toLowerCase())) logItems.push({ id: `log-not-enabled:${n}`, severity: "warn", title: `${n} was not enabled at the last start`, detail: "The plugin is in the folder but the log never shows it being enabled. It may have been added after the last start, or it failed quietly.", advice: "Restart the server; if it is still missing, check its requirements.", evidence: [`no "Enabling ${n}" line in the last start`] });
    }
    const errs = by("error_line");
    if (errs.length) logItems.push({ id: "log-errors", severity: "info", title: `${plural(errs.length, "other error line")} in the start log`, detail: "Lines logged at ERROR level that the Doctor did not tie to a cause.", advice: null, evidence: errs.slice(0, 6).map((f) => `line ${f.line}: ${f.text.slice(0, 160)}`) });
  }
  const startup = sectionOf("startup_log", "Last start", logItems, logCnc, !!log && log.started, log?.doneSec != null ? `Started cleanly in ${log.doneSec.toFixed(1)} s` : "No problems found in the log");

  // ---- performance hints
  const perfItems: DoctorItem[] = [];
  const perfCnc: string[] = [];
  const props = inv.serverProperties.keys;
  const vd = Number(props["view-distance"]), sd = Number(props["simulation-distance"]);
  if (inv.serverProperties.present) {
    if (Number.isFinite(vd) && vd > 12) perfItems.push({ id: "perf-view", severity: "warn", title: `View distance is ${vd}`, detail: "Every extra step of view distance loads many more chunks per player, the most common cause of lag and memory use.", advice: "Most servers run 6-10. Lower view-distance in server.properties (players can still see far with simulation-distance lower).", evidence: [`server.properties view-distance=${vd}`] });
    if (Number.isFinite(sd) && sd > 10) perfItems.push({ id: "perf-sim", severity: "warn", title: `Simulation distance is ${sd}`, detail: "Entities and redstone tick in this radius around each player.", advice: "4-8 is plenty for most servers.", evidence: [`server.properties simulation-distance=${sd}`] });
  } else perfCnc.push("server.properties not found: view and simulation distance unknown");
  if (inv.plugins.length > 60) perfItems.push({ id: "perf-plugins", severity: "info", title: `${inv.plugins.length} plugins installed`, detail: "Many plugins mean more memory and a slower start.", advice: "Remove plugins you do not use.", evidence: [] });
  if (log?.lag.count) perfItems.push({ id: "perf-lag", severity: log.lag.worstMs != null && log.lag.worstMs > 10000 ? "problem" : "warn", title: "The server could not keep up", detail: `The log shows ${plural(log.lag.count, "\"Can't keep up\" warning")}; the worst was ${log.lag.worstMs} ms (${log.lag.worstTicks} ticks) behind.`, advice: "Lower view-distance, pre-generate the world, or look for a plugin doing heavy work.", evidence: [] });
  if (log?.doneSec != null && log.doneSec > 90) perfItems.push({ id: "perf-boot", severity: "info", title: `Start took ${log.doneSec.toFixed(0)} s`, detail: "A slow start usually means many plugins, a large world or little CPU/memory.", advice: null, evidence: [] });
  const host = opts.host ?? {};
  if (host.memoryLimitMb != null && host.memoryLimitMb < 2048 && inv.plugins.length > 20) perfItems.push({ id: "perf-mem", severity: "warn", title: `${host.memoryLimitMb} MB of memory for ${inv.plugins.length} plugins`, detail: "Paper with this many plugins usually needs 3-4 GB or more.", advice: "Consider a plan with more memory.", evidence: [] });
  if (host.memoryLimitMb == null) perfCnc.push("memory: the plan's memory limit was not provided");
  let tpsChecked = false;
  if (opts.console) {
    const con = guardConsole(opts.console);
    try {
      const tps = parseTps(await con.run("tps"));
      if (tps) {
        tpsChecked = true;
        if (tps.m1 < 18) perfItems.push({ id: "perf-tps", severity: tps.m1 < 15 ? "problem" : "warn", title: `TPS is ${tps.m1.toFixed(1)} (target 20)`, detail: `Last 1, 5, 15 minutes: ${tps.m1}, ${tps.m5}, ${tps.m15}. Below 20 the game runs slow for everyone.`, advice: "Lower view/simulation distance, or find the plugin or farm using the most time (a profiler like spark helps).", evidence: [] });
      } else perfCnc.push("TPS: the console gave no TPS reading");
      const ms = parseMspt(await con.run("mspt"));
      if (ms && ms.avg5s > 40) perfItems.push({ id: "perf-mspt", severity: ms.avg5s > 50 ? "problem" : "warn", title: `Ticks take ${ms.avg5s.toFixed(1)} ms on average`, detail: "A tick must finish in 50 ms or the server falls behind.", advice: "See the TPS advice above.", evidence: [`worst in the last minute: ${ms.max1m} ms`] });
    } catch (e) { perfCnc.push(`live console: ${(e as Error).message.slice(0, 120)}`); }
  } else perfCnc.push("TPS: no live console (the Doctor only read files)");
  const performance = sectionOf("performance", "Performance", perfItems, perfCnc, inv.serverProperties.present || !!log || tpsChecked, tpsChecked ? "TPS is fine and no performance warnings were found" : "No performance warnings in the files (live TPS not checked)");

  // ---- installed table
  const problemsFor = (name: string) => [...confItems, ...known.items, ...logItems].filter((x) => x.severity === "problem" && x.title.toLowerCase().includes(name.toLowerCase())).length;
  const enabledAt = (name: string): boolean | null => (log?.doneSec != null ? log.enabled.some((e) => e.toLowerCase() === name.toLowerCase()) : null);
  const installed: PluginRow[] = [
    ...inv.plugins.map((p: PluginJar) => {
      const asMod = pluginFolderMods.find((m) => m.path === p.path);
      const name = p.descriptor?.name ?? asMod?.name ?? asMod?.id ?? p.file;
      return { name, version: p.descriptor?.version ?? asMod?.version ?? null, file: p.path, kind: p.descriptor ? "plugin" as const : asMod?.loader ? "mod" as const : "unknown" as const, loader: p.descriptor ? null : asMod?.loader ?? null, enabledAtLastStart: p.descriptor?.name ? enabledAt(p.descriptor.name) : null, problems: problemsFor(name) };
    }),
    ...mods.map((m) => ({ name: m.name ?? m.id ?? m.file, version: m.version, file: m.path, kind: m.loader ? "mod" as const : m.alsoPlugin ? "plugin" as const : "unknown" as const, loader: m.loader, enabledAtLastStart: null, problems: problemsFor(m.name ?? m.id ?? m.file) })),
  ];

  const sections = [server, inventory, conflicts, known, startup, performance];
  const all = sections.flatMap((s) => s.items);
  const counts = { problems: all.filter((x) => x.severity === "problem").length, warnings: all.filter((x) => x.severity === "warn").length, info: all.filter((x) => x.severity === "info").length, couldNotCheck: sections.reduce((a, s) => a + s.couldNotCheck.length, 0) };
  const skipped = sections.filter((s) => s.status === "could_not_check");
  const overall: DoctorReport["overall"] = counts.problems ? "problems" : counts.warnings ? "attention" : skipped.length ? "incomplete" : "healthy";
  const where = `${inv.software.name === "unknown" ? "this server" : inv.software.name[0].toUpperCase() + inv.software.name.slice(1)}${mcVersion ? ` ${mcVersion}` : ""}`;
  const headline = overall === "healthy" ? `No problems found on ${where} (${plural(inv.plugins.length + mods.length, "plugin/mod")} checked).`
    : overall === "incomplete" ? `No problems found in what could be checked on ${where}; ${skipped.map((s) => s.title.toLowerCase()).join(", ")} could not be checked.`
    : `${[counts.problems && plural(counts.problems, "problem"), counts.warnings && plural(counts.warnings, "warning")].filter(Boolean).join(" and ")} found on ${where}.`;
  return {
    schema: 1, doctor: DOCTOR_VERSION, generatedAt: (opts.now ?? (() => new Date()))().toISOString(), readOnly: true, overall, headline,
    server: { software: inv.software.name, mcVersion, build: inv.software.build, java: log?.javaVersion ?? null, loader, plugins: inv.plugins.length, mods: mods.length, datapacks: inv.datapacks.folder.length, evidence: inv.software.evidence.slice(0, 4) },
    sections, installed, counts,
    limits: { ...inv.limits, logBytes: logBuf?.length ?? 0, logTruncated: !!log?.truncated || (logBuf?.length ?? 0) >= maxLog },
  };
}

/** Plain-text rendering (support ticket, email, CLI). Same honesty: could-not-check lines are always printed. */
export function renderDoctorText(r: DoctorReport): string {
  const out: string[] = [`Server Doctor (${r.doctor}, read-only) - ${r.generatedAt}`, r.headline, ""];
  const mark: Record<SectionStatus, string> = { ok: "OK", attention: "CHECK", problems: "PROBLEM", could_not_check: "NOT CHECKED" };
  for (const s of r.sections) {
    out.push(`[${mark[s.status]}] ${s.title}: ${s.summary}`);
    for (const i of s.items) {
      out.push(`  - ${i.severity.toUpperCase()}: ${i.title}`);
      out.push(`    ${i.detail}`);
      if (i.advice) out.push(`    What to do: ${i.advice}`);
    }
    for (const c of s.couldNotCheck) out.push(`  - not checked: ${c}`);
  }
  return out.join("\n");
}

