// Cyrus Server Doctor (R4): pure tests over in-memory servers (no ssh, no JVM). The real node-2 run (a throwaway
// Paper server with a seeded conflict and a seeded broken plugin) is test/cyrus-doctor-real.ts; its real latest.log
// is kept as test/fixtures/cyrus-doctor/latest-1.21.11.log and replayed here.
// Run: tsx --test test/cyrus-doctor.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { runDoctor, renderDoctorText, guardConsole, type ReadOnlyConsole } from "../lib/cyrus/doctor/doctor";
import { analyseLog, parseMspt, parseTps, LOG_RULES } from "../lib/cyrus/doctor/log";
import { inspectModJar, readModsToml } from "../lib/cyrus/doctor/mods";
import { satisfiesMc, KNOWN_BROKEN } from "../lib/cyrus/doctor/known";
import { zip } from "../lib/cyrus/textures/zip";
import { genJar } from "./_cyrus-jarfixture";
import { MemFs } from "./_cyrus-fakeserver";

const B = (s: string) => Buffer.from(s);
const T = "[12:00:00 INFO]: ";
const LOG = [
  `${T}Starting minecraft server version 1.21.11`,
  `${T}This server is running Paper version 1.21.11-132-main@abc (2026-05-11T00:00:00Z) (Implementing API version 1.21.11-R0.1-SNAPSHOT)`,
  `${T}[TfClashA] Loading server plugin TfClashA v1.0.0`,
  `${T}[TfClashB] Loading server plugin TfClashB v1.0.0`,
  `${T}[TfBroken] Loading server plugin TfBroken v1.0.0`,
  `[12:00:01 ERROR]: Could not load 'plugins/FabricThing.jar' in folder 'plugins'`,
  "org.bukkit.plugin.InvalidDescriptionException: Invalid plugin.yml",
  `${T}[TfClashA] Enabling TfClashA v1.0.0`,
  `${T}[TfClashB] Enabling TfClashB v1.0.0`,
  `${T}[TfBroken] Enabling TfBroken v1.0.0`,
  `[12:00:02 ERROR]: Error occurred while enabling TfBroken v1.0.0 (Is it up to date?)`,
  "java.lang.IllegalStateException: TfBroken deliberately failed in onEnable",
  "\tat dev.nxeon.tf.broken.BrokenPlugin.onEnable(BrokenPlugin.java:9)",
  `${T}[TfBroken] Disabling TfBroken v1.0.0`,
  `[12:00:05 WARN]: Can't keep up! Is the server overloaded? Running 2500ms or 50 ticks behind`,
  `[12:00:09 WARN]: Can't keep up! Is the server overloaded? Running 12000ms or 240 ticks behind`,
  `${T}Done (9.512s)! For help, type "help"`,
].join("\n");

function server(over: Record<string, Buffer | null> = {}): MemFs {
  const m = new Map<string, Buffer>();
  const put = (p: string, d: Buffer) => m.set(`/opt/mc/${p}`, d);
  put("server.properties", B("level-name=world\nview-distance=16\nsimulation-distance=6\nrcon.password=hunter2-secret\n"));
  put("logs/latest.log", B(LOG));
  put("version_history.json", B(JSON.stringify({ currentVersion: "1.21.11-132-main@abc (MC: 1.21.11)" })));
  put("plugins/TfClashA.jar", genJar({ name: "TfClashA", extraYml: "commands:\n  nxclash:\n    permission: nxclash.use\npermissions:\n  nxclash.use:\n    default: true\n" }));
  put("plugins/TfClashB.jar", genJar({ name: "TfClashB", extraYml: "commands:\n  nxclash:\n    permission: nxclash.use\npermissions:\n  nxclash.use:\n    default: op\n" }));
  put("plugins/TfBroken.jar", genJar({ name: "TfBroken" }));
  put("plugins/OldThing.jar", genJar({ name: "OldThing", yml: "name: OldThing\nversion: 0.9\nmain: a.B\n" }));
  put("plugins/FabricThing.jar", zip([{ path: "fabric.mod.json", data: B(JSON.stringify({ id: "fabricthing", version: "2.0.0", name: "Fabric Thing", depends: { minecraft: ">=1.21" } })) }]));
  put("plugins/Gone.jar.disabled", B("x"));
  for (const [k, v] of Object.entries(over)) { if (v == null) m.delete(`/opt/mc/${k}`); else put(k, v); }
  return new MemFs(m);
}
const fixed = () => new Date("2026-10-10T00:00:00Z");

describe("Server Doctor report (seeded conflict + seeded broken plugin)", () => {
  it("finds the conflict, the crash at enable, the legacy plugin, the mod in the plugins folder and the lag", async () => {
    const r = await runDoctor(server(), { now: fixed });
    assert.equal(r.overall, "problems");
    assert.equal(r.readOnly, true);
    assert.equal(r.server.software, "paper");
    assert.equal(r.server.mcVersion, "1.21.11");
    const sec = Object.fromEntries(r.sections.map((s) => [s.id, s]));
    const titles = (id: string) => sec[id].items.map((i) => `${i.severity}: ${i.title}`);
    assert.ok(titles("conflicts").some((t) => /nxclash/i.test(t) || /command/i.test(t)), titles("conflicts").join(" | "));
    assert.ok(sec.conflicts.items.some((i) => /nxclash/.test(i.detail + i.evidence.join(" "))));
    assert.ok(titles("startup_log").includes("problem: TfBroken crashed while starting"));
    assert.match(sec.startup_log.items.find((i) => i.title === "TfBroken crashed while starting")!.detail, /IllegalStateException: TfBroken deliberately failed/);
    assert.ok(titles("startup_log").includes("problem: FabricThing did not load"));
    assert.ok(titles("known_issues").includes("warn: OldThing is a legacy plugin"));
    assert.ok(titles("known_issues").includes("problem: Fabric Thing is a fabric mod, not a plugin"));
    assert.ok(titles("known_issues").some((t) => /switched-off jar/.test(t)));
    assert.ok(titles("performance").includes("warn: View distance is 16"));
    assert.ok(titles("performance").some((t) => /^problem: The server could not keep up/.test(t)), "12 s behind is a problem");
    assert.ok(sec.performance.couldNotCheck.some((c) => /no live console/.test(c)));
    assert.ok(sec.known_issues.couldNotCheck.some((c) => /known-broken list/.test(c)), "an empty curated list is said, not hidden");
    assert.equal(r.installed.find((p) => p.name === "TfBroken")!.enabledAtLastStart, true, "Paper logged Enabling before the crash");
    assert.equal(r.installed.find((p) => p.file === "plugins/FabricThing.jar")!.kind, "mod");
    assert.match(r.headline, /problems? and \d+ warnings? found on Paper 1\.21\.11/);
    assert.ok(!JSON.stringify(r).includes("hunter2"), "server.properties secrets never reach the report");
    const text = renderDoctorText(r);
    assert.match(text, /\[PROBLEM\] Last start/);
    assert.match(text, /not checked: TPS: no live console/);
  });
  it("is deterministic for the same files", async () => {
    assert.deepEqual(await runDoctor(server(), { now: fixed }), await runDoctor(server(), { now: fixed }));
  });
  it("a clean server is healthy; a missing log is 'could not check', never healthy", async () => {
    const clean = server({ "plugins/TfClashB.jar": null, "plugins/TfBroken.jar": null, "plugins/OldThing.jar": null, "plugins/FabricThing.jar": null, "plugins/Gone.jar.disabled": null,
      "server.properties": B("view-distance=8\n"), "logs/latest.log": B([`${T}Starting minecraft server version 1.21.11`, `${T}This server is running Paper version 1.21.11-132-main@abc`, `${T}[TfClashA] Enabling TfClashA v1.0.0`, `${T}Done (5.0s)! For help, type "help"`].join("\n")) });
    const r = await runDoctor(clean, { now: fixed });
    assert.equal(r.overall, "healthy", JSON.stringify(r.sections.map((s) => [s.id, s.status, s.items.map((i) => i.title)])));
    assert.equal(r.sections.find((s) => s.id === "startup_log")!.summary, "Started cleanly in 5.0 s");
    const nolog = await runDoctor(server({ "logs/latest.log": null, "plugins/TfBroken.jar": null, "plugins/OldThing.jar": null, "plugins/FabricThing.jar": null, "plugins/TfClashB.jar": null, "plugins/Gone.jar.disabled": null, "server.properties": B("view-distance=8\n") }), { now: fixed });
    assert.equal(nolog.sections.find((s) => s.id === "startup_log")!.status, "could_not_check");
    assert.equal(nolog.overall, "incomplete");
    assert.match(nolog.headline, /last start could not be checked/);
  });
  it("live console: only tps/mspt/version are ever sent; low TPS is reported", async () => {
    const sent: string[] = [];
    const con: ReadOnlyConsole = { run: async (c) => { sent.push(c); return c === "tps" ? "§6TPS from last 1m, 5m, 15m: §c14.2, §e17.9, *20.0" : "§6Server tick times §e(§7avg§e/§7min§e/§7max§e)§6 from last 5s,§7 10s,§7 1m§6:\n§6◴ §a62.1§7/§a3.0§7/§a120.4§6, §a40.0§7/§a3.0§7/§a120.4§6, §a30.0§7/§a2.0§7/§a150.0"; } };
    const r = await runDoctor(server(), { now: fixed, console: con });
    assert.deepEqual(sent, ["tps", "mspt"]);
    const perf = r.sections.find((s) => s.id === "performance")!;
    assert.ok(perf.items.some((i) => i.title === "TPS is 14.2 (target 20)" && i.severity === "problem"));
    assert.ok(perf.items.some((i) => /Ticks take 62\.1 ms/.test(i.title)));
    await assert.rejects(guardConsole(con).run("stop"), /never sends 'stop'/);
    await assert.rejects(guardConsole(con).run("op someone"), /never sends/);
    assert.deepEqual(parseTps("TPS from last 1m, 5m, 15m: *20.0, *20.0, *20.0"), { m1: 20, m5: 20, m15: 20 });
    assert.equal(parseTps("Unknown command"), null);
    assert.equal(parseMspt("nope"), null);
  });
  it("a curated known-broken entry matches by sha256 or name+version; an entry without a source is ignored", async () => {
    assert.equal(KNOWN_BROKEN.length, 0, "shipped empty: entries need a real source");
    const fs = server();
    const sha = (await import("node:crypto")).createHash("sha256").update((await fs.readFile("/opt/mc/plugins/TfClashA.jar"))!).digest("hex");
    const r = await runDoctor(fs, { now: fixed, knownBroken: [
      { id: "kb1", sha256: sha, severity: "problem", reason: "Breaks chat on 1.21.11", advice: "Update to 1.0.1", source: "owner note 2026-10-10 (test)" },
      { id: "kb2", name: "tfclashb", versionPrefix: "1.0", severity: "warn", reason: "Leaks memory", advice: "Update", source: "test" },
      { id: "kb3", name: "TfBroken", severity: "problem", reason: "x", advice: "y", source: "" },
    ] });
    const ki = r.sections.find((s) => s.id === "known_issues")!;
    assert.ok(ki.items.some((i) => i.id.startsWith("known:kb1:") && i.severity === "problem"));
    assert.ok(ki.items.some((i) => i.id.startsWith("known:kb2:") && i.severity === "warn"));
    assert.ok(!ki.items.some((i) => i.id.startsWith("known:kb3:")));
  });
});

