    assert.deepEqual(readModsToml('[[mods]]\nmodId = "a" # c\n[other]\nmodId="no"\n').mods, [{ modId: "a" }]);
  });
  it("Minecraft version ranges (Fabric and Maven syntax)", () => {
    const cases: [string, string, boolean | null][] = [
      [">=1.21", "1.21.1", true], [">=1.21.2", "1.21.1", false], ["~1.21", "1.21.11", true], ["~1.20.4", "1.21.1", false], ["1.21.x", "1.21.4", true], ["1.21.x", "1.20.6", false],
      [">=1.21 <1.21.5", "1.21.4", true], [">=1.21 <1.21.5", "1.21.5", false], ["1.20.1 || 1.21.1", "1.21.1", true], ["*", "26.1", true], ["^1.21", "1.21.11", true], ["^1.21", "1.22", false],
      ["[1.21,1.22)", "1.21.11", true], ["[1.21,1.22)", "1.22", false], ["[1.21.1]", "1.21.1", true], ["(,1.21]", "1.21.1", false], ["[26.1,)", "26.2", true], ["banana", "1.21", null],
    ];
    for (const [r, v, want] of cases) assert.equal(satisfiesMc(r, v), want, `${r} vs ${v}`);
