// Cyrus MOD HEALTH TELEMETRY (R4): the signal schema. Pure + client-safe.
//
// What it is: opt-in, aggregate-only health signals about Cyrus mods running on servers whose owner switched it on:
//   boot_ok            the server finished starting with the mod enabled
//   enable_error       the mod threw while being enabled (Paper "Error occurred while enabling")
//   exception          the mod threw at runtime (event handler / scheduled task), reduced to a SIGNATURE
//   crash              the server crashed or crash-looped and the crash names the mod
//   command_registered / command_missing   a command the mod declares is / is not registered after start
// What it never holds: player names, UUIDs, IP addresses, chat, world or server names, coordinates, file paths,
// exception MESSAGES or any free text. Only fixed enums, version ids, hashes and counts pass the validator; an
// unknown field or a string outside its pattern rejects the whole signal (fail closed).
//
// Identity: `serverKey` is an HMAC of the server id with a salt that ROTATES every retention window (30 days), so a
// server's signals can be counted as "distinct servers" inside one window but cannot be linked across windows.
// Retention: raw daily signals 30 days, aggregates 180 days (./retention.ts).

export const TELEMETRY_SCHEMA = 1 as const;
export const TELEMETRY_FLAG = "CYRUS_HEALTH_TELEMETRY";
export const CONSENT_SCOPE = "cyrus-mod-health-v1" as const;
export const SIGNAL_EVENTS = ["boot_ok", "enable_error", "exception", "crash", "command_registered", "command_missing"] as const;
export type SignalEvent = (typeof SIGNAL_EVENTS)[number];

export type HealthSignal = {
  v: 1;
  /** UTC day bucket, YYYY-MM-DD. No finer time is ever stored. */
  day: string;
  /** HMAC-SHA256(serverId, window salt), 32 hex. Rotates with the window. */
  serverKey: string;
  /** Rotating window number the serverKey belongs to (floor(epochDay / 30)). */
  window: number;
  /** The Cyrus build the server runs (ModBuild id) - a Cyrus id, not player data. */
  buildId: string;
  /** Minecraft version id of the server (registry form, e.g. 1.21.11). */
  mcVersion: string;
  software: "paper" | "purpur" | "folia" | "spigot" | "other";
  event: SignalEvent;
  /** exception / crash / enable_error only: sig_<16 hex> of (exception class + first frame in the mod's packages). */
  signature?: string;
  /** exception / crash / enable_error only: the exception CLASS (e.g. java.lang.NoSuchMethodError), never its message. */
  exceptionClass?: string;
  /** API-mismatch family (NoSuchMethodError, NoSuchFieldError, NoClassDefFoundError on the game API, UnsupportedClassVersionError). */
  apiMismatch?: boolean;
  /** command_* only: the command LABEL the mod itself declares (from the build, a-z0-9_-). */
  command?: string;
  /** How many times in that day (1-10000). */
  count: number;
};

export type Consent = { optedIn: boolean; scope: typeof CONSENT_SCOPE; at: string; byUserId: string };

const DAY_RE = /^\d{4}-\d{2}-\d{2}$/;
const HEX32 = /^[0-9a-f]{32}$/;
const BUILD_RE = /^[A-Za-z0-9_-]{6,40}$/;
const MC_RE = /^(?:1\.\d{1,2}(?:\.\d{1,2})?|\d{2}\.\d{1,2}(?:\.\d{1,2})?)$/;
const SIG_RE = /^sig_[0-9a-f]{16}$/;
/** A Java class name: dotted identifiers only (no spaces, no message text). */
const CLASS_RE = /^[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*){0,12}$/;
const CMD_RE = /^[a-z0-9_-]{1,32}$/;
const SOFTWARE = ["paper", "purpur", "folia", "spigot", "other"];
const FIELDS = new Set(["v", "day", "serverKey", "window", "buildId", "mcVersion", "software", "event", "signature", "exceptionClass", "apiMismatch", "command", "count"]);

/** Untrusted JSON -> problems (empty = a valid signal). Strict: unknown fields and free text are refused. */
export function validateSignal(raw: unknown): string[] {
  const s = raw as Record<string, unknown> | null;
  if (!s || typeof s !== "object" || Array.isArray(s)) return ["signal must be an object"];
  const e: string[] = [];
  for (const k of Object.keys(s)) if (!FIELDS.has(k)) e.push(`unknown field ${k} (refused: only the fixed schema is accepted)`);
  if (s.v !== 1) e.push("v must be 1");
  if (typeof s.day !== "string" || !DAY_RE.test(s.day) || Number.isNaN(Date.parse(`${s.day}T00:00:00Z`))) e.push("day must be YYYY-MM-DD");
  if (typeof s.serverKey !== "string" || !HEX32.test(s.serverKey)) e.push("serverKey must be 32 hex chars (an HMAC, never a server id)");
  if (!Number.isInteger(s.window) || (s.window as number) < 0) e.push("window must be a whole number");
  if (typeof s.buildId !== "string" || !BUILD_RE.test(s.buildId)) e.push("buildId must be a Cyrus build id");
  if (typeof s.mcVersion !== "string" || !MC_RE.test(s.mcVersion)) e.push("mcVersion must be a Minecraft version id");
  if (!SOFTWARE.includes(String(s.software))) e.push(`software must be one of ${SOFTWARE.join(", ")}`);
  if (!(SIGNAL_EVENTS as readonly string[]).includes(String(s.event))) e.push(`event must be one of ${SIGNAL_EVENTS.join(", ")}`);
  if (!Number.isInteger(s.count) || (s.count as number) < 1 || (s.count as number) > 10000) e.push("count must be 1-10000");
  const errorish = s.event === "exception" || s.event === "crash" || s.event === "enable_error";
  const cmdish = s.event === "command_registered" || s.event === "command_missing";
  if (s.signature != null && (!errorish || typeof s.signature !== "string" || !SIG_RE.test(s.signature))) e.push("signature must be sig_<16 hex>, only on enable_error/exception/crash");
  if (s.exceptionClass != null && (!errorish || typeof s.exceptionClass !== "string" || s.exceptionClass.length > 200 || !CLASS_RE.test(s.exceptionClass))) e.push("exceptionClass must be a Java class name, only on enable_error/exception/crash");
  if (s.apiMismatch != null && (!errorish || typeof s.apiMismatch !== "boolean")) e.push("apiMismatch must be a boolean, only on enable_error/exception/crash");
  if (s.event === "exception" && s.signature == null) e.push("exception needs a signature");
  if (cmdish ? !(typeof s.command === "string" && CMD_RE.test(s.command)) : s.command != null) e.push("command must be a declared command label, only on command_* events");
  return e;
}

export const isSignal = (raw: unknown): raw is HealthSignal => validateSignal(raw).length === 0;

/** Consent must be explicit, for this scope, and recorded with who and when. Anything else = not opted in. */
export function hasConsent(c: Consent | null | undefined): boolean {
  return !!c && c.optedIn === true && c.scope === CONSENT_SCOPE && typeof c.at === "string" && !Number.isNaN(Date.parse(c.at)) && typeof c.byUserId === "string" && c.byUserId.length > 0;
}

