// Cyrus mod health telemetry: turn what a server's log already shows into SIGNALS (pure). Runs where Nxeon already
// reads game logs for the lifecycle (worker side), only for servers whose owner opted in, only with the flag on.
// Every free-text part of a log line is dropped here: the output passes validateSignal or is not emitted.
import { createHash, createHmac } from "node:crypto";
import { CONSENT_SCOPE, hasConsent, validateSignal, TELEMETRY_FLAG, type Consent, type HealthSignal } from "./schema";

export const WINDOW_DAYS = 30;
export const epochDay = (d: Date) => Math.floor(d.getTime() / 86400000);
export const windowOf = (d: Date) => Math.floor(epochDay(d) / WINDOW_DAYS);
export const dayOf = (d: Date) => d.toISOString().slice(0, 10);

/**
 * The rotating serverKey: HMAC(serverId) with a per-window salt derived from the secret. A new window = a new key,
 * so the same server is not linkable across windows. The secret lives in the host (env), never in a signal.
 */
export function serverKey(serverId: string, secret: string, window: number): string {
  if (!secret || secret.length < 24) throw new Error("telemetry secret must be at least 24 chars");
  const salt = createHmac("sha256", secret).update(`${CONSENT_SCOPE}:window:${window}`).digest();
  return createHmac("sha256", salt).update(serverId).digest("hex").slice(0, 32);
}

const API_MISMATCH = /^(java\.lang\.(NoSuchMethodError|NoSuchFieldError|NoClassDefFoundError|UnsupportedClassVersionError|AbstractMethodError|IncompatibleClassChangeError))$/;
const EXC_LINE = /(?:^|\s|Caused by: )((?:[a-zA-Z_$][\w$]*\.)+[\w$]*(?:Exception|Error))(?::|$|\s)/;
const FRAME = /^\s*at ((?:[\w$]+\.)+[\w$<>]+)\(/;

/**
 * Signature of an error: exception class + the FIRST stack frame inside the mod's own packages (line numbers and the
 * message are dropped). Same bug on two servers = same signature. Returns null when no exception class is found.
 */
export function signatureOf(lines: string[], modPackages: string[]): { signature: string; exceptionClass: string; apiMismatch: boolean } | null {
  let cls: string | null = null;
  let frame: string | null = null;
  for (const l of lines.slice(0, 60)) {
    if (!cls) { const m = EXC_LINE.exec(l); if (m) cls = m[1]; }
    const f = FRAME.exec(l);
    if (f && !frame && modPackages.some((p) => f[1].startsWith(p + "."))) frame = f[1];
  }
  if (!cls) return null;
  const signature = "sig_" + createHash("sha256").update(`${cls}|${frame ?? "-"}`).digest("hex").slice(0, 16);
  return { signature, exceptionClass: cls, apiMismatch: API_MISMATCH.test(cls) };
}

export type CollectMod = {
  buildId: string;
  /** Plugin name as Paper prints it (plugin.yml name). */
  pluginName: string;
  /** Java packages of the mod (from its main class), for the signature frame. */
  packages: string[];
  /** Command labels the build declares. */
  commands: string[];
};

export type CollectInput = {
  env?: Record<string, string | undefined>;
  consent: Consent | null;
  serverId: string;
  secret: string;
  now: Date;
  mcVersion: string;
  software: string;
  mods: CollectMod[];
  /** The game log since the last collection (text). */
  log: string;
  /** Command labels the server reported as registered (e.g. from `help <label>`), when the host checked them. */
  registeredCommands?: string[] | null;
};

export type CollectResult = { collected: false; reason: string } | { collected: true; signals: HealthSignal[]; dropped: number };

const SW = (s: string): HealthSignal["software"] => (["paper", "purpur", "folia", "spigot"].includes(s) ? (s as HealthSignal["software"]) : "other");

/** Log -> signals for one server and one day. OFF unless the flag is on AND the owner opted in (fail closed). */
export function collectSignals(i: CollectInput): CollectResult {
  const env = i.env ?? process.env;
  if (env[TELEMETRY_FLAG] !== "1") return { collected: false, reason: `${TELEMETRY_FLAG} is off` };
  if (!hasConsent(i.consent)) return { collected: false, reason: "the server owner has not opted in" };
  const window = windowOf(i.now);
  const base = { v: 1 as const, day: dayOf(i.now), serverKey: serverKey(i.serverId, i.secret, window), window, mcVersion: i.mcVersion, software: SW(i.software) };
  const lines = i.log.split(/\r?\n/);
  const counts = new Map<string, HealthSignal>();
  const add = (s: Omit<HealthSignal, "count" | keyof typeof base>) => {
    const sig = { ...base, ...s, count: 1 } as HealthSignal;
    const k = JSON.stringify({ ...sig, count: 0 });
    const cur = counts.get(k);
    if (cur) cur.count = Math.min(10000, cur.count + 1); else counts.set(k, sig);
  };
  const done = lines.some((l) => /Done \([\d.,]+s\)! For help, type/.test(l));
  for (const m of i.mods) {
    const name = m.pluginName.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const enabled = new RegExp(`Enabling ${name} v`).test(i.log);
    const enableErr = new RegExp(`Error occurred while enabling ${name} v`);
    const runtime = [new RegExp(`Could not pass event \\w+ to ${name} v`), new RegExp(`Task #\\d+ for ${name} v\\S+ generated an exception`)];
    lines.forEach((l, idx) => {
      if (enableErr.test(l)) {
        const s = signatureOf(lines.slice(idx + 1, idx + 40), m.packages);
        add({ buildId: m.buildId, event: "enable_error", ...(s ? { signature: s.signature, exceptionClass: s.exceptionClass, apiMismatch: s.apiMismatch } : {}) });
      } else if (runtime.some((r) => r.test(l))) {
        const s = signatureOf(lines.slice(idx + 1, idx + 40), m.packages);
        if (s) add({ buildId: m.buildId, event: "exception", signature: s.signature, exceptionClass: s.exceptionClass, apiMismatch: s.apiMismatch });
      } else if (/(Encountered an unexpected exception|Exception in server tick loop)/.test(l)) {
        const tail = lines.slice(idx, idx + 60);
        if (tail.some((t) => m.packages.some((p) => t.includes(`at ${p}.`)))) {
          const s = signatureOf(tail, m.packages);
          add({ buildId: m.buildId, event: "crash", ...(s ? { signature: s.signature, exceptionClass: s.exceptionClass, apiMismatch: s.apiMismatch } : {}) });
        }
      }
    });
