// Cyrus mod health telemetry: AGGREGATION, RETENTION and the two consumers (pure).
//  - aggregate(): signals -> rows per (build, Minecraft version, event, signature/command, window) with counts and
//    DISTINCT servers (by the rotating serverKey; only countable inside one window);
//  - k-anonymity: a row seen on fewer than K_MIN_SERVERS distinct servers is never shown or used ("suppressed");
//  - healthFor(): the lifecycle feed, in the shape lifecycle/state.ts already takes (`broken`), plus an "outdated"
//    hint for API-mismatch signatures; never more than the rows say;
//  - opsTelemetryView(): the admin ops read model block;
//  - retention(): raw signals 30 days, aggregates 180 days, then deleted.
import { WINDOW_DAYS, epochDay } from "./collect";
import type { HealthSignal, SignalEvent } from "./schema";

/** Same threshold the creator warnings use (lib/cyrus/lifecycle/creator.ts ERROR_SERVER_THRESHOLD = 2). */
export const K_MIN_SERVERS = 2;
export const RETENTION = { rawDays: 30, aggregateDays: 180 } as const;

export type AggregateRow = {
  buildId: string;
  mcVersion: string;
  event: SignalEvent;
  /** signature for errors, command label for command_* events, "" otherwise. */
  key: string;
  exceptionClass: string | null;
  apiMismatch: boolean;
  window: number;
  firstDay: string;
  lastDay: string;
  count: number;
  servers: number;
};

/** Signals (already validated) -> aggregate rows. Deterministic order. */
export function aggregate(signals: readonly HealthSignal[]): AggregateRow[] {
  const m = new Map<string, AggregateRow & { keys: Set<string> }>();
  for (const s of signals) {
    const key = s.signature ?? s.command ?? "";
    const id = [s.buildId, s.mcVersion, s.event, key, s.window].join("|");
    const r = m.get(id) ?? { buildId: s.buildId, mcVersion: s.mcVersion, event: s.event, key, exceptionClass: s.exceptionClass ?? null, apiMismatch: !!s.apiMismatch, window: s.window, firstDay: s.day, lastDay: s.day, count: 0, servers: 0, keys: new Set<string>() };
    r.count += s.count;
    r.keys.add(s.serverKey);
    if (s.day < r.firstDay) r.firstDay = s.day;
    if (s.day > r.lastDay) r.lastDay = s.day;
    r.apiMismatch = r.apiMismatch || !!s.apiMismatch;
    m.set(id, r);
  }
  return [...m.values()].map(({ keys, ...r }) => ({ ...r, servers: keys.size }))
    .sort((a, b) => (a.buildId + a.mcVersion + a.event + a.key + a.window < b.buildId + b.mcVersion + b.event + b.key + b.window ? -1 : 1));
}

/** Rows that may be shown or acted on (k-anonymity). The rest are only counted. */
export function visible(rows: readonly AggregateRow[], k = K_MIN_SERVERS): { rows: AggregateRow[]; suppressed: number } {
  const ok = rows.filter((r) => r.servers >= k);
  return { rows: ok, suppressed: rows.length - ok.length };
}

export type TelemetryHealth = {
  buildId: string;
  mcVersion: string;
  /** Feeds LifecycleInput.broken (lib/cyrus/lifecycle/state.ts) for this build on this version, or null. */
  broken: { evidence: string; apiMismatch: boolean } | null;
  /** The errors look like "built against another game version": the build is out of date for mcVersion. */
  outdatedHint: string | null;
  servers: { bootOk: number; failing: number };
  basis: string;
};

/**
 * Lifecycle feed for one build on one Minecraft version, from the CURRENT window's visible rows only.
 * broken = enable errors or crashes on >= K servers, or runtime exceptions on >= K servers (same signature).
 */
export function healthFor(rows: readonly AggregateRow[], buildId: string, mcVersion: string, window: number, k = K_MIN_SERVERS): TelemetryHealth {
  const mine = visible(rows.filter((r) => r.buildId === buildId && r.mcVersion === mcVersion && r.window === window), k).rows;
  const by = (e: SignalEvent) => mine.filter((r) => r.event === e);
  const bootOk = Math.max(0, ...by("boot_ok").map((r) => r.servers));
  const failingRows = [...by("enable_error"), ...by("crash"), ...by("exception")].sort((a, b) => b.servers - a.servers || b.count - a.count);
  const failing = Math.max(0, ...failingRows.map((r) => r.servers));
  const top = failingRows[0] ?? null;
  const api = failingRows.filter((r) => r.apiMismatch);
  const label = (r: AggregateRow) => `${r.event.replace("_", " ")} ${r.exceptionClass ?? ""} on ${r.servers} servers (${r.count}x, ${r.firstDay}..${r.lastDay})`.replace(/\s+/g, " ");
  return {
    buildId, mcVersion,
    broken: top ? { evidence: `Mod health telemetry: ${label(top)}`, apiMismatch: api.length > 0 } : null,
    outdatedHint: api.length ? `Servers on ${mcVersion} report ${api[0].exceptionClass} from this mod: it was built for a different game version.` : null,
    servers: { bootOk, failing },
    basis: mine.length ? `${mine.length} aggregate row(s) with >= ${k} servers in window ${window}` : `no rows with >= ${k} servers in window ${window}`,
  };
}

export type OpsTelemetryView = {
  enabled: boolean;
  window: number;
  k: number;
  builds: { buildId: string; mcVersion: string; bootOkServers: number; failingServers: number; commandMissing: string[]; topSignatures: { key: string; exceptionClass: string | null; event: string; servers: number; count: number; apiMismatch: boolean }[]; state: "broken" | "outdated" | "ok" | "no_data" }[];
  suppressedRows: number;
  retention: typeof RETENTION;
};

/** Admin ops block (read-only), for lib/cyrus/delivery/admin.ts cyrusOpsReport({ telemetry }). */
export function opsTelemetryView(rows: readonly AggregateRow[], opts: { enabled: boolean; window: number; k?: number }): OpsTelemetryView {
  const k = opts.k ?? K_MIN_SERVERS;
  const cur = rows.filter((r) => r.window === opts.window);
  const { rows: vis, suppressed } = visible(cur, k);
  const pairs = [...new Set(vis.map((r) => `${r.buildId}|${r.mcVersion}`))].sort();
  return {
    enabled: opts.enabled, window: opts.window, k, suppressedRows: suppressed, retention: RETENTION,
    builds: pairs.map((p) => {
      const [buildId, mcVersion] = p.split("|");
      const h = healthFor(vis, buildId, mcVersion, opts.window, k);
      const mine = vis.filter((r) => r.buildId === buildId && r.mcVersion === mcVersion);
      return {
        buildId, mcVersion, bootOkServers: h.servers.bootOk, failingServers: h.servers.failing,
        commandMissing: mine.filter((r) => r.event === "command_missing").map((r) => r.key),
        topSignatures: mine.filter((r) => ["enable_error", "crash", "exception"].includes(r.event)).sort((a, b) => b.servers - a.servers || b.count - a.count).slice(0, 5)
          .map((r) => ({ key: r.key, exceptionClass: r.exceptionClass, event: r.event, servers: r.servers, count: r.count, apiMismatch: r.apiMismatch })),
        state: h.outdatedHint ? "outdated" : h.broken ? "broken" : mine.length ? "ok" : "no_data",
      };
    }),
  };
}

/** Retention rule: which stored rows must be deleted at `now`. Raw signals by day; aggregates by their last day. */
export function retention(now: Date, raw: readonly { id: string; day: string }[], aggregates: readonly { id: string; lastDay: string }[]): { deleteRaw: string[]; deleteAggregates: string[] } {
  const today = epochDay(now);
  const age = (day: string) => today - epochDay(new Date(`${day}T00:00:00Z`));
  return {
    deleteRaw: raw.filter((r) => age(r.day) >= RETENTION.rawDays).map((r) => r.id),
    deleteAggregates: aggregates.filter((r) => age(r.lastDay) >= RETENTION.aggregateDays).map((r) => r.id),
  };
}

export { WINDOW_DAYS };

