// Cyrus mod health telemetry (R4): schema (privacy-safe, fail closed), collection gates (flag + consent),
// signatures, aggregation with k-anonymity, the lifecycle feed, the admin read model and the retention rule.
// Pure; no DB. Run: tsx --test test/cyrus-telemetry.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { validateSignal, hasConsent, CONSENT_SCOPE, type HealthSignal, type Consent } from "../lib/cyrus/telemetry/schema";
import { collectSignals, serverKey, signatureOf, windowOf, type CollectInput } from "../lib/cyrus/telemetry/collect";
import { aggregate, visible, healthFor, opsTelemetryView, retention, K_MIN_SERVERS, RETENTION } from "../lib/cyrus/telemetry/aggregate";
import { deriveLifecycle } from "../lib/cyrus/lifecycle/state";
import { cyrusOpsReport } from "../lib/cyrus/delivery/admin";

const SECRET = "test-secret-at-least-24-chars-long";
const NOW = new Date("2026-10-10T12:00:00Z");
const consent: Consent = { optedIn: true, scope: CONSENT_SCOPE, at: "2026-10-01T00:00:00Z", byUserId: "user_1" };
const good: HealthSignal = { v: 1, day: "2026-10-10", serverKey: "a".repeat(32), window: 681, buildId: "build_abc123", mcVersion: "1.21.11", software: "paper", event: "exception", signature: "sig_0123456789abcdef", exceptionClass: "java.lang.NullPointerException", apiMismatch: false, count: 3 };

const LOG = [
  "[12:00:00 INFO]: Starting minecraft server version 1.21.11",
  "[12:00:01 INFO]: [TfPlay] Enabling TfPlay v1.0.0",
  "[12:00:02 INFO]: Done (9.5s)! For help, type \"help\"",
  "[12:01:00 ERROR]: Could not pass event PlayerJoinEvent to TfPlay v1.0.0",
  "java.lang.NullPointerException: Cannot invoke \"String.length()\" because player Steve (uuid 069a79f4-44e9-4726-a5be-fca90e38aaf5) from 203.0.113.9 said hi",
  "\tat org.bukkit.Something.call(Something.java:10)",
  "\tat dev.nxeon.tf.play.PlayPlugin.onJoin(PlayPlugin.java:33)",
  "[12:02:00 ERROR]: Could not pass event PlayerJoinEvent to TfPlay v1.0.0",
  "java.lang.NullPointerException: Cannot invoke \"String.length()\" because player Alex said bye",
  "\tat dev.nxeon.tf.play.PlayPlugin.onJoin(PlayPlugin.java:35)",
].join("\n");
const input = (over: Partial<CollectInput> = {}): CollectInput => ({
  env: { CYRUS_HEALTH_TELEMETRY: "1" }, consent, serverId: "srv_1", secret: SECRET, now: NOW, mcVersion: "1.21.11", software: "paper",
  mods: [{ buildId: "build_abc123", pluginName: "TfPlay", packages: ["dev.nxeon.tf.play"], commands: ["tfgem", "tfboost"] }], log: LOG, registeredCommands: ["tfgem"], ...over,
});

describe("schema: privacy by construction", () => {
  it("accepts a valid signal and refuses unknown fields, free text, raw ids and misplaced fields", () => {
    assert.deepEqual(validateSignal(good), []);
    const bad: [Record<string, unknown>, RegExp][] = [
      [{ ...good, playerName: "Steve" }, /unknown field playerName/],
      [{ ...good, ip: "203.0.113.9" }, /unknown field ip/],
      [{ ...good, message: "boom" }, /unknown field message/],
      [{ ...good, exceptionClass: "java.lang.Exception: Steve broke it" }, /exceptionClass/],
      [{ ...good, serverKey: "srv_1" }, /serverKey/],
      [{ ...good, day: "2026-10-10T12:00:00Z" }, /day/],
      [{ ...good, event: "exception", signature: undefined }, /exception needs a signature/],
      [{ ...good, event: "boot_ok", signature: undefined, exceptionClass: undefined, apiMismatch: undefined, command: "x" }, /command must be/],
      [{ ...good, count: 0 }, /count/],
      [{ ...good, mcVersion: "latest" }, /mcVersion/],
    ];
    for (const [s, re] of bad) {
      const clean = Object.fromEntries(Object.entries(s).filter(([, v]) => v !== undefined));
      assert.match(validateSignal(clean).join("; "), re, JSON.stringify(clean));
    }
  });
  it("consent must be explicit, scoped, dated and attributed", () => {
    assert.equal(hasConsent(consent), true);
    assert.equal(hasConsent(null), false);
    assert.equal(hasConsent({ ...consent, optedIn: false }), false);
    assert.equal(hasConsent({ ...consent, scope: "other" as typeof CONSENT_SCOPE }), false);
    assert.equal(hasConsent({ ...consent, byUserId: "" }), false);
  });
});

describe("collection (flag + opt-in, nothing personal leaves the log)", () => {
  it("is off without the flag and without the owner's opt-in", () => {
    assert.deepEqual(collectSignals(input({ env: {} })), { collected: false, reason: "CYRUS_HEALTH_TELEMETRY is off" });
    assert.deepEqual(collectSignals(input({ consent: null })), { collected: false, reason: "the server owner has not opted in" });
  });
  it("turns a log into boot / exception / command signals with one signature for one bug, and no player data", () => {
    const r = collectSignals(input());
    assert.equal(r.collected, true);
    if (!r.collected) return;
    assert.equal(r.dropped, 0);
    const ev = r.signals.map((s) => `${s.event}:${s.count}`).sort();
    assert.deepEqual(ev, ["boot_ok:1", "command_missing:1", "command_registered:1", "exception:2"]);
    const ex = r.signals.find((s) => s.event === "exception")!;
    assert.equal(ex.exceptionClass, "java.lang.NullPointerException");
    assert.match(ex.signature!, /^sig_[0-9a-f]{16}$/);
    const json = JSON.stringify(r.signals);
    for (const leak of ["Steve", "Alex", "069a79f4", "203.0.113.9", "srv_1", "String.length", "PlayPlugin.java"]) assert.ok(!json.includes(leak), `leaked ${leak}`);
    for (const s of r.signals) assert.deepEqual(validateSignal(s), []);
  });
  it("signatures ignore messages and line numbers but tell different bugs apart", () => {
    const a = signatureOf(["java.lang.IllegalStateException: one", "\tat dev.x.A.run(A.java:1)"], ["dev.x"]);
    const b = signatureOf(["java.lang.IllegalStateException: two", "\tat dev.x.A.run(A.java:99)"], ["dev.x"]);
    const c = signatureOf(["java.lang.IllegalStateException: one", "\tat dev.x.B.run(B.java:1)"], ["dev.x"]);
    assert.equal(a!.signature, b!.signature);
    assert.notEqual(a!.signature, c!.signature);
    assert.equal(signatureOf(["java.lang.NoSuchMethodError: 'void org.bukkit.X.y()'"], ["dev.x"])!.apiMismatch, true);
    assert.equal(signatureOf(["no exception here"], ["dev.x"]), null);
  });
  it("serverKey: stable inside a window, different across windows and servers, never the id", () => {
    const w = windowOf(NOW);
    assert.equal(serverKey("srv_1", SECRET, w), serverKey("srv_1", SECRET, w));
    assert.notEqual(serverKey("srv_1", SECRET, w), serverKey("srv_1", SECRET, w + 1));
    assert.notEqual(serverKey("srv_1", SECRET, w), serverKey("srv_2", SECRET, w));
    assert.match(serverKey("srv_1", SECRET, w), /^[0-9a-f]{32}$/);
    assert.throws(() => serverKey("srv_1", "short", w), /at least 24/);
  });
});

describe("aggregation, k-anonymity and the lifecycle feed", () => {
  const w = windowOf(NOW);
  const sig = (srv: string, over: Partial<HealthSignal>): HealthSignal => ({ ...good, window: w, serverKey: serverKey(srv, SECRET, w), ...over });
  const signals = [
    sig("s1", { event: "enable_error", signature: "sig_aaaaaaaaaaaaaaaa", exceptionClass: "java.lang.NoSuchMethodError", apiMismatch: true, count: 2 }),
    sig("s2", { event: "enable_error", signature: "sig_aaaaaaaaaaaaaaaa", exceptionClass: "java.lang.NoSuchMethodError", apiMismatch: true, count: 1, day: "2026-10-09" }),
    sig("s1", { event: "boot_ok", signature: undefined, exceptionClass: undefined, apiMismatch: undefined, count: 1 }),
    sig("s3", { event: "exception", signature: "sig_bbbbbbbbbbbbbbbb", count: 5 }),
    sig("s1", { buildId: "build_other1", event: "crash", signature: "sig_cccccccccccccccc", count: 1 }),
  ];
  it("counts distinct servers per row and suppresses rows seen on fewer than K servers", () => {
    const rows = aggregate(signals);
    const ee = rows.find((r) => r.event === "enable_error")!;
    assert.deepEqual([ee.count, ee.servers, ee.firstDay, ee.lastDay, ee.apiMismatch], [3, 2, "2026-10-09", "2026-10-10", true]);
    const v = visible(rows);
    assert.equal(K_MIN_SERVERS, 2);
    assert.deepEqual(v.rows.map((r) => r.event), ["enable_error"]);
    assert.equal(v.suppressed, 3);
    assert.deepEqual(aggregate(signals), aggregate([...signals].reverse()), "order independent");
  });
  it("healthFor feeds the existing lifecycle 'broken' input (API mismatch -> out of date); one server is never enough", () => {
    const rows = aggregate(signals);
    const h = healthFor(rows, "build_abc123", "1.21.11", w);
    assert.ok(h.broken);
    assert.equal(h.broken!.apiMismatch, true);
    assert.match(h.outdatedHint!, /NoSuchMethodError/);
    const view = deriveLifecycle({ status: "INSTALLED", error: null, restartPending: false, broken: h.broken, autoDisabled: null, outdated: [], rolledBack: false });
    assert.equal(view.state, "broken");
    assert.match(view.notes.join(" "), /out of date for this version/);
    assert.match(view.notes.join(" "), /Mod health telemetry: enable error java.lang.NoSuchMethodError on 2 servers/);
    assert.equal(healthFor(rows, "build_other1", "1.21.11", w).broken, null, "a crash on one server is suppressed");
    assert.equal(healthFor(rows, "build_abc123", "1.21.11", w + 1).broken, null, "other windows do not count");
  });
  it("admin read model: only visible rows, with state and top signatures; cyrusOpsReport adds it only when given", async () => {
    const rows = aggregate(signals);
    const v = opsTelemetryView(rows, { enabled: false, window: w });
    assert.equal(v.builds.length, 1);
    assert.equal(v.builds[0].state, "outdated");
    assert.equal(v.builds[0].topSignatures[0].key, "sig_aaaaaaaaaaaaaaaa");
    assert.equal(v.suppressedRows, 3);
    assert.deepEqual(v.retention, RETENTION);
    const db = { job: { findMany: async () => [] }, modBuild: { findMany: async () => [] } };
    const plain = await cyrusOpsReport(db, { now: NOW });
    assert.equal("health" in plain, false);
    const withT = await cyrusOpsReport(db, { now: NOW, telemetry: { enabled: true, rows: async () => rows } });
    assert.equal(withT.health!.builds[0].buildId, "build_abc123");
  });
});

describe("retention", () => {
  it("raw signals go after 30 days, aggregates after 180 days", () => {
    const r = retention(NOW, [{ id: "r29", day: "2026-09-11" }, { id: "r30", day: "2026-09-10" }, { id: "r0", day: "2026-10-10" }], [{ id: "a179", lastDay: "2026-04-14" }, { id: "a180", lastDay: "2026-04-13" }]);
    assert.deepEqual(r.deleteRaw, ["r30"]);
    assert.deepEqual(r.deleteAggregates, ["a180"]);
    assert.deepEqual(RETENTION, { rawDays: 30, aggregateDays: 180 });
  });
});

