// REAL Server Doctor run on node-2 (not part of the unit suite), against a THROWAWAY Test Flight server only:
//   ssh node-2: cd /tank/nxeon-build/wt/<worktree> && npx tsx test/cyrus-doctor-real.ts --local [--out file.json] [--save-log dest]
// 1. ONE Test Flight (real Paper 1.21.11, private netns, node-2 lock) boots a server seeded with problems:
//    TfClashA + TfClashB (same /nxclash command, same permission with different defaults = a seeded CONFLICT),
//    TfBroken (throws in onEnable = a seeded BROKEN plugin), TfLegacy (no api-version) and FabricThing.jar
//    (a Fabric mod dropped into plugins/). RCON tps / mspt / version replies are recorded while it runs.
// 2. The run dir is kept (keepDir) only long enough for the Doctor to read it read-only, then REMOVED.
// 3. The Doctor runs over that real server dir (files written by real Paper) + the recorded console replies.
import { spawn } from "node:child_process";
import { existsSync, mkdtempSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync, copyFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { runTestFlight, type Remote } from "../lib/cyrus/testflight/client";
import type { ReadOnlyServerFs } from "../lib/cyrus/inventory/types";
import { runDoctor, renderDoctorText, type ReadOnlyConsole } from "../lib/cyrus/doctor/doctor";
import { zip } from "../lib/cyrus/textures/zip";

const TF = "/tank/nxeon-build/tmp/testflight";
const FX = `${TF}/inbox/fx/doctor`;
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d)); child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {}); child.stdin.end(opts.input ?? undefined);
  }),
};
const arg = (k: string) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : null; };

/** Read-only fs over a local directory (what LocalGuestFs does, without importing Nxeon). */
function localFs(): ReadOnlyServerFs {
  return {
    async stat(p) { try { const s = statSync(p); return { type: s.isDirectory() ? "dir" : "file", size: s.size }; } catch { return null; } },
    async readFile(p, max = Infinity) { try { const s = statSync(p); if (!s.isFile()) return null; const b = readFileSync(p); return b.length > max ? b.subarray(0, max) : b; } catch { return null; } },
    async list(d) { try { return readdirSync(d); } catch { return []; } },
  };
}

async function main() {
  const tmp = mkdtempSync(path.join(tmpdir(), "cyrus-doctor-"));
  const fabric = path.join(tmp, "FabricThing.jar");
  writeFileSync(fabric, zip([{ path: "fabric.mod.json", data: Buffer.from(JSON.stringify({ schemaVersion: 1, id: "fabricthing", version: "2.0.0", name: "Fabric Thing", environment: "*", depends: { minecraft: ">=1.21" } })) }]));
  let report = null;
  for (let i = 0, wait = 15000; i < 16; i++, wait = Math.min(wait * 2, 120000)) {
    report = (await runTestFlight({
      version: "1.21.11", keepDir: true,
      plugins: [{ remotePath: `${FX}/TfClashA-1.21.11.jar` }, { remotePath: `${FX}/TfClashB-1.21.11.jar` }, { remotePath: `${FX}/TfBroken-1.21.11.jar` }, { remotePath: `${FX}/TfLegacy-1.21.11.jar` }, { localPath: fabric }],
      rcon: [{ id: "tps", command: "tps", required: false }, { id: "mspt", command: "mspt", required: false }, { id: "version", command: "version", required: false }],
    }, { remote: localRemote })).report;
    if (report.status !== "busy") break;
    console.log(`node-2 busy, retry in ${wait / 1000}s`); await sleep(wait);
  }
  rmSync(tmp, { recursive: true, force: true });
  if (!report || report.status === "busy") throw new Error("node-2 stayed busy");
  const runId = String(report.runId);
  if (!/^[a-z0-9][a-z0-9-]{5,63}$/.test(runId)) throw new Error(`bad runId ${runId}`);
  const runDir = `${TF}/runs/${runId}`;
  // console replies recorded while the server ran (evidence lines: "<id> '<cmd>' [...]: ok -> <reply with ' | ' for newlines>")
  const rc = report.checks.find((c) => c.id === "rcon_checks")?.evidence ?? [];
  const reply = (id: string) => { const l = rc.find((e) => e.startsWith(`${id} '`)); return l ? l.replace(/^.*?-> /, "").replace(/ \| /g, "\n") : null; };
  const console_: ReadOnlyConsole = { run: async (c) => reply(c) };
  const out: Record<string, unknown> = { recordedAt: new Date().toISOString(), what: "Cyrus Server Doctor (R4): real throwaway Paper 1.21.11 server on node-2 (Test Flight, keepDir) with a seeded conflict and a seeded broken plugin", runId, flight: { overall: report.overall, checks: Object.fromEntries(report.checks.map((c) => [c.id, c.status])), bootMs: report.bootMs, peakRssKb: report.peakRssKb, engine: report.engine, rconEvidence: rc } };
  try {
    if (!existsSync(runDir)) throw new Error(`run dir ${runDir} was not kept`);
    const t0 = Date.now();
    const doc = await runDoctor(localFs(), { base: runDir, console: console_ });
    out.doctorMs = Date.now() - t0;
    out.doctor = doc;
    out.text = renderDoctorText(doc);
    out.serverFiles = readdirSync(runDir).sort();
    const save = arg("--save-log");
    if (save && existsSync(`${runDir}/logs/latest.log`)) copyFileSync(`${runDir}/logs/latest.log`, save);
    console.log(out.text);
  } finally {
    rmSync(runDir, { recursive: true, force: true }); // ALWAYS tear down the throwaway server dir
    out.teardown = { runDirRemoved: !existsSync(runDir) };
  }
  const o = arg("--out");
  if (o) { const prev = existsSync(o) ? JSON.parse(readFileSync(o, "utf8")) : {}; writeFileSync(o, JSON.stringify({ ...prev, doctor: out }, null, 1)); }
}

main().catch((e) => { console.error(e); process.exit(1); });

